    # ============================================================================
    # SUPPORTING METHODS FOR ENHANCED GEOLOGICAL DATA INTEGRATION
    # ============================================================================
    
    def _standardize_geological_unit(self, unit_name: str) -> str:
        """Standardize geological unit names across different databases"""
        if not unit_name or unit_name.lower() in ['unknown', 'null', 'none']:
            return 'unknown'
        
        unit_lower = unit_name.lower().strip()
        
        # Mapping common variations
        unit_mappings = {
            'igneous': ['granite', 'basalt', 'rhyolite', 'andesite', 'gabbro', 'diorite'],
            'sedimentary': ['limestone', 'sandstone', 'shale', 'conglomerate', 'mudstone'],
            'metamorphic': ['gneiss', 'schist', 'slate', 'marble', 'quartzite', 'amphibolite'],
            'volcanic': ['tuff', 'lava', 'pyroclastic', 'volcanic_breccia'],
            'plutonic': ['granite', 'granodiorite', 'monzonite', 'syenite'],
            'continental_crust': ['continental', 'craton', 'shield', 'platform'],
            'oceanic_crust': ['oceanic', 'ophiolite', 'pillow_basalt']
        }
        
        for standard_unit, variations in unit_mappings.items():
            if any(var in unit_lower for var in variations):
                return standard_unit
        
        return unit_name
    
    def _standardize_rock_type(self, rock_type: str) -> str:
        """Standardize rock type classifications"""
        if not rock_type or rock_type.lower() in ['unknown', 'null', 'mixed']:
            return 'mixed'
        
        rock_lower = rock_type.lower().strip()
        
        # Primary rock classifications
        if any(term in rock_lower for term in ['igneous', 'magmatic', 'plutonic', 'volcanic']):
            return 'igneous'
        elif any(term in rock_lower for term in ['sedimentary', 'clastic', 'carbonate']):
            return 'sedimentary'
        elif any(term in rock_lower for term in ['metamorphic', 'gneiss', 'schist']):
            return 'metamorphic'
        elif any(term in rock_lower for term in ['unconsolidated', 'alluvial', 'quaternary']):
            return 'unconsolidated'
        
        return rock_type
    
    def _standardize_geological_age(self, age: str) -> str:
        """Standardize geological age classifications"""
        if not age or age.lower() in ['unknown', 'null']:
            return 'unknown'
        
        age_lower = age.lower().strip()
        
        # Geological time periods
        age_mappings = {
            'precambrian': ['precambrian', 'archean', 'proterozoic'],
            'paleozoic': ['paleozoic', 'cambrian', 'ordovician', 'silurian', 'devonian', 'carboniferous', 'permian'],
            'mesozoic': ['mesozoic', 'triassic', 'jurassic', 'cretaceous'],
            'cenozoic': ['cenozoic', 'paleogene', 'neogene', 'quaternary', 'tertiary'],
            'quaternary': ['quaternary', 'pleistocene', 'holocene', 'recent']
        }
        
        for standard_age, variations in age_mappings.items():
            if any(var in age_lower for var in variations):
                return standard_age
        
        return age
    
    def _standardize_lithology(self, lithology: str) -> str:
        """Standardize lithological classifications"""
        if not lithology or lithology.lower() in ['unknown', 'null', 'mixed']:
            return 'mixed'
        
        litho_lower = lithology.lower().strip()
        
        # Lithological classifications
        litho_mappings = {
            'crystalline': ['granite', 'gneiss', 'schist', 'crystalline'],
            'carbonate': ['limestone', 'dolomite', 'marble', 'carbonate'],
            'clastic': ['sandstone', 'conglomerate', 'shale', 'mudstone'],
            'volcanic': ['basalt', 'andesite', 'rhyolite', 'tuff', 'volcanic'],
            'metamorphic': ['gneiss', 'schist', 'slate', 'amphibolite', 'metamorphic'],
            'unconsolidated': ['sand', 'clay', 'gravel', 'alluvium', 'till']
        }
        
        for standard_litho, variations in litho_mappings.items():
            if any(var in litho_lower for var in variations):
                return standard_litho
        
        return lithology
    
    def _assess_structural_complexity(self, structural_info: str) -> str:
        """Assess structural complexity from geological data"""
        if not structural_info:
            return 'moderate'
        
        info_lower = structural_info.lower()
        
        # Complexity indicators
        high_complexity = ['fault', 'fold', 'shear', 'thrust', 'complex', 'deformed']
        low_complexity = ['simple', 'horizontal', 'flat', 'stable', 'undeformed']
        
        if any(term in info_lower for term in high_complexity):
            return 'high'
        elif any(term in info_lower for term in low_complexity):
            return 'low'
        
        return 'moderate'
    
    def _parse_embedded_gml(self, complex_data, namespaces: Dict) -> Dict:
        """Parse embedded GML data from WPS responses"""
        try:
            gml_data = {}
            
            # Look for GML geometry and properties
            for gml_elem in complex_data.findall('.//gml:*', namespaces):
                if gml_elem.tag.endswith('Polygon') or gml_elem.tag.endswith('Point'):
                    gml_data['geometry_type'] = gml_elem.tag.split('}')[-1]
                elif gml_elem.tag.endswith('coordinates'):
                    gml_data['coordinates'] = gml_elem.text
            
            return gml_data
        except Exception:
            return {}
    
    def _derive_geological_properties(self, geological_data: Dict) -> Dict:
        """Derive additional geological properties from base data"""
        derived = {}
        
        # Derive rock strength characteristics
        if 'rock_type' in geological_data:
            derived['estimated_strength'] = self._estimate_rock_strength_from_type(
                geological_data['rock_type']
            )
        
        # Derive weathering susceptibility
        if 'lithology' in geological_data:
            derived['weathering_susceptibility'] = self._estimate_weathering_susceptibility(
                geological_data['lithology']
            )
        
        # Derive seismic properties
        if 'geological_unit' in geological_data:
            derived['seismic_velocity_estimate'] = self._estimate_seismic_velocity(
                geological_data['geological_unit']
            )
        
        return derived
    
    def _assess_data_confidence(self, data: Dict, source: str) -> float:
        """Assess confidence level of geological data"""
        confidence = 0.0
        
        # Base confidence by source
        source_confidence = {
            'usgs': 0.8,
            'onegeology': 0.7,
            'lithological': 0.6,
            'regional': 0.5
        }
        
        confidence = source_confidence.get(source.lower(), 0.4)
        
        # Adjust based on data completeness
        completeness = len([v for v in data.values() if v and v != 'unknown']) / max(len(data), 1)
        confidence *= (0.5 + 0.5 * completeness)
        
        return min(confidence, 1.0)
    
    def _get_current_timestamp(self) -> str:
        """Get current timestamp in ISO format"""
        from datetime import datetime
        return datetime.utcnow().isoformat() + 'Z'
    
    def _parse_usgs_text_response(self, response_text: str) -> Dict:
        """Fallback text-based parsing for USGS responses"""
        try:
            # Simple text parsing for key-value pairs
            geological_data = {}
            lines = response_text.split('\n')
            
            for line in lines:
                if ':' in line:
                    key, value = line.split(':', 1)
                    key = key.strip().lower().replace(' ', '_')
                    value = value.strip()
                    
                    if key in ['geological_unit', 'rock_type', 'age', 'lithology']:
                        geological_data[key] = value
            
            return geological_data
        except Exception:
            return {}
    
    def _log_parsing_error(self, source: str, error: str) -> None:
        """Log parsing errors for debugging"""
        print(f"Geological data parsing error [{source}]: {error}")
    
    def _assess_data_completeness(self, feature_data: Dict) -> float:
        """Assess completeness of feature data"""
        total_fields = len(feature_data)
        complete_fields = len([v for v in feature_data.values() 
                             if v and v not in ['unknown', 'mixed', None]])
        return complete_fields / max(total_fields, 1)
    
    def _estimate_spatial_resolution(self, json_data: Dict) -> str:
        """Estimate spatial resolution from GeoJSON data"""
        try:
            features = json_data.get('features', [])
            if features and len(features) > 1:
                return 'high'
            elif features:
                return 'medium'
            else:
                return 'low'
        except Exception:
            return 'unknown'
    
    def _consolidate_geological_data(self, aggregated_data: Dict) -> Dict:
        """Consolidate aggregated geological data from multiple features"""
        consolidated = {}
        
        for key, values in aggregated_data.items():
            if not values:
                continue
                
            # For categorical data, use most common value
            if isinstance(values[0], str):
                from collections import Counter
                most_common = Counter(values).most_common(1)[0][0]
                consolidated[key] = most_common
            # For numerical data, use mean
            elif isinstance(values[0], (int, float)):
                consolidated[key] = np.mean(values)
            else:
                consolidated[key] = values[0]  # Take first value
        
        return consolidated
    
    def _classify_rock_strength(self, strength_info: Dict) -> str:
        """Classify rock strength from detailed strength information"""
        try:
            ucs = strength_info.get('ucs_range', {})  # Unconfined compressive strength
            
            if isinstance(ucs, dict) and 'max' in ucs:
                max_ucs = ucs['max']
                if max_ucs > 100:  # MPa
                    return 'very_strong'
                elif max_ucs > 50:
                    return 'strong'
                elif max_ucs > 25:
                    return 'moderate'
                elif max_ucs > 5:
                    return 'weak'
                else:
                    return 'very_weak'
            
            return 'moderate'
        except Exception:
            return 'moderate'
    
    def _classify_weathering_grade(self, weathering_info: Dict) -> str:
        """Classify weathering grade from detailed weathering information"""
        try:
            intensity = weathering_info.get('intensity', 'moderate')
            depth = weathering_info.get('depth', 0)
            
            if intensity == 'severe' or depth > 10:
                return 'highly_weathered'
            elif intensity == 'moderate' or (depth > 3 and depth <= 10):
                return 'moderately_weathered'
            elif intensity == 'slight' or depth <= 3:
                return 'slightly_weathered'
            else:
                return 'fresh'
        except Exception:
            return 'moderate'
    
    def _assess_lithological_confidence(self, json_data: Dict) -> float:
        """Assess confidence of lithological data"""
        confidence = 0.5  # Base confidence
        
        # Increase confidence based on data richness
        if 'physical_properties' in json_data:
            confidence += 0.2
        if 'mineral_composition' in json_data:
            confidence += 0.2
        if 'geochemistry' in json_data:
            confidence += 0.1
        
        return min(confidence, 1.0)
    
    def _derive_lithological_properties(self, lithological_data: Dict) -> Dict:
        """Derive additional lithological properties"""
        derived = {}
        
        # Derive engineering properties from lithology
        dominant_litho = lithological_data.get('dominant_lithology', 'mixed')
        derived['engineering_classification'] = self._classify_engineering_properties(dominant_litho)
        
        # Derive hydrological properties
        porosity = lithological_data.get('porosity')
        if porosity:
            derived['hydrological_class'] = self._classify_hydrological_properties(porosity)
        
        return derived
    
    def _estimate_rock_strength_from_type(self, rock_type: str) -> str:
        """Estimate rock strength from rock type"""
        strength_map = {
            'igneous': 'strong',
            'metamorphic': 'strong',
            'sedimentary': 'moderate',
            'unconsolidated': 'weak'
        }
        return strength_map.get(rock_type, 'moderate')
    
    def _estimate_weathering_susceptibility(self, lithology: str) -> str:
        """Estimate weathering susceptibility from lithology"""
        susceptibility_map = {
            'carbonate': 'high',
            'clastic': 'moderate', 
            'crystalline': 'low',
            'volcanic': 'moderate'
        }
        return susceptibility_map.get(lithology, 'moderate')
    
    def _estimate_seismic_velocity(self, geological_unit: str) -> float:
        """Estimate seismic velocity from geological unit"""
        velocity_map = {
            'crystalline': 6000,
            'sedimentary': 3000,
            'volcanic': 4000,
            'metamorphic': 5500
        }
        return velocity_map.get(geological_unit, 4000)
    
    def _classify_engineering_properties(self, lithology: str) -> str:
        """Classify engineering properties from lithology"""
        eng_map = {
            'crystalline': 'excellent',
            'metamorphic': 'good',
            'clastic': 'moderate',
            'unconsolidated': 'poor'
        }
        return eng_map.get(lithology, 'moderate')
    
    def _classify_hydrological_properties(self, porosity: float) -> str:
        """Classify hydrological properties from porosity"""
        if porosity > 0.3:
            return 'high_permeability'
        elif porosity > 0.1:
            return 'moderate_permeability'
        else:
            return 'low_permeability'
    
    # Additional helper methods for the enhanced geological integration
    def _determine_applicable_geological_regions(self, lat: float, lon: float) -> List[str]:
        """Determine all applicable geological regions for a location"""
        regions = []
        
        # Continental regions
        if -180 <= lon <= -30:  # Americas
            if lat >= 25:
                regions.append('north_america')
            else:
                regions.append('south_america')
        elif -30 < lon <= 60:  # Europe/Africa
            if lat >= 35:
                regions.append('europe')
            else:
                regions.append('africa')
        elif 60 < lon <= 180:  # Asia/Australia
            if lat >= 10:
                regions.append('asia')
            else:
                regions.append('australia')
        
        return regions
    
    def _query_specific_regional_survey(self, survey: str, base_url: str, 
                                       lat: float, lon: float, region: str) -> Optional[Dict]:
        """Query a specific regional geological survey with real API integration"""
        try:
            # Rate limiting check
            if not self._check_rate_limit('usgs'):
                time.sleep(30)  # Wait for rate limit reset
            
            # Construct query parameters based on survey type
            if 'usgs' in survey.lower():
                params = {
                    'service': 'WFS',
                    'version': '2.0.0',
                    'request': 'GetFeature',
                    'outputFormat': 'application/json',
                    'CQL_FILTER': f'INTERSECTS(geom, POINT({lon} {lat}))'
                }
            elif 'geological' in survey.lower():
                params = {
                    'format': 'json',
                    'lat': lat,
                    'lon': lon,
                    'radius': 5000  # 5km radius
                }
            else:
                # Generic parameters for unknown survey types
                params = {'lat': lat, 'lon': lon, 'format': 'json'}
            
            # Make the API request
            response = requests.get(base_url, params=params, timeout=30)
            
            if response.status_code == 200:
                self._record_api_call('usgs')
                data = response.json()
                
                # Extract relevant geological information
                geological_info = {}
                
                if 'features' in data and data['features']:
                    feature = data['features'][0]
                    properties = feature.get('properties', {})
                    
                    geological_info = {
                        'rock_type': properties.get('rock_type') or properties.get('ROCKTYPE1'),
                        'formation': properties.get('formation') or properties.get('UNIT_NAME'),
                        'age': properties.get('age') or properties.get('MIN_AGE'),
                        'lithology': properties.get('lithology') or properties.get('LITHOLOGY'),
                        'description': properties.get('description') or properties.get('DESCRIP'),
                        'confidence': 0.8,
                        'survey_source': survey,
                        'region': region
                    }
                elif 'data' in data:
                    # Handle different response formats
                    geological_info = {
                        'survey_data': data['data'][:3] if isinstance(data['data'], list) else data['data'],
                        'survey_source': survey,
                        'region': region,
                        'confidence': 0.6
                    }
                
                return geological_info if geological_info else None
            
            return None
            
        except Exception as e:
            logging.warning(f"Regional survey query failed [{survey}]: {e}")
            return None
    
    def _consolidate_regional_geological_data(self, geological_data: Dict) -> Dict:
        """Advanced multi-source geological data consolidation with ML-enhanced integration"""
        try:
            consolidated_data = {
                'metadata': {
                    'total_sources': len(geological_data),
                    'processed_at': datetime.now().isoformat(),
                    'consolidation_method': 'advanced_ml_weighted',
                    'confidence_threshold': 0.85
                },
                'consolidated': True,
                'sources': list(geological_data.keys()),
                'integrated_layers': {},
                'quality_metrics': {},
                'uncertainty_maps': {},
                'conflict_resolution': {}
            }
            
            # Advanced integration using DataIntegrationPipeline
            if hasattr(self, 'data_pipeline') and self.data_pipeline:
                pipeline_results = self.data_pipeline.process_multi_source_data(
                    geological_data, 
                    integration_method='weighted_ensemble',
                    quality_control=True
                )
                consolidated_data['integrated_layers'] = pipeline_results.get('processed_layers', {})
                consolidated_data['quality_metrics'] = pipeline_results.get('quality_metrics', {})
            
            # Spatial coherence analysis
            spatial_coherence = self._analyze_spatial_coherence(geological_data)
            consolidated_data['spatial_coherence'] = spatial_coherence
            
            # Cross-validation between sources
            cross_validation = self._cross_validate_geological_sources(geological_data)
            consolidated_data['cross_validation'] = cross_validation
            
            # Uncertainty quantification
            uncertainty_analysis = self._quantify_source_uncertainties(geological_data)
            consolidated_data['uncertainty_maps'] = uncertainty_analysis
            
            # Conflict resolution using ML-based prioritization
            conflicts = self._detect_data_conflicts(geological_data)
            if conflicts:
                resolved_conflicts = self._resolve_conflicts_ml(conflicts, geological_data)
                consolidated_data['conflict_resolution'] = resolved_conflicts
            
            # Store consolidated results in database
            if hasattr(self, 'database_integration') and self.database_integration:
                storage_result = self.database_integration.store_consolidated_geological_data(
                    consolidated_data, 
                    table_name='consolidated_geological_data'
                )
                consolidated_data['database_storage'] = storage_result
            
            return consolidated_data
            
        except Exception as e:
            self._log_regional_query_error('consolidation', 'multi_source', str(e))
            return {
                'consolidated': False, 
                'error': str(e),
                'sources': list(geological_data.keys()),
                'fallback_data': self._create_fallback_geological_data(geological_data)
            }
    
    def _log_regional_query_error(self, region: str, survey: str, error: str) -> None:
        """Advanced error logging with database integration and ML-enhanced diagnostics"""
        try:
            error_data = {
                'timestamp': datetime.now().isoformat(),
                'region': region,
                'survey': survey,
                'error_message': error,
                'error_type': self._classify_error_type(error),
                'severity': self._assess_error_severity(error),
                'suggested_resolution': self._generate_error_resolution(error),
                'error_hash': hashlib.md5(f"{region}-{survey}-{error}".encode()).hexdigest(),
                'system_context': {
                    'processor_state': getattr(self, 'processing_state', 'unknown'),
                    'memory_usage': self._get_memory_usage(),
                    'concurrent_operations': getattr(self, 'active_operations', 0)
                }
            }
            
            # Enhanced logging with multiple outputs
            self.logger.error(f"Regional geological survey error [{region}-{survey}]: {error}")
            
            # Database logging if available
            if hasattr(self, 'database_integration') and self.database_integration:
                self.database_integration.log_error(
                    error_data, 
                    table_name='regional_query_errors',
                    severity=error_data['severity']
                )
            
            # ML-based error pattern analysis
            if hasattr(self, 'model_manager') and self.model_manager:
                pattern_analysis = self.model_manager.analyze_error_patterns(error_data)
                if pattern_analysis and pattern_analysis.get('recurring_pattern'):
                    self._handle_recurring_error_pattern(pattern_analysis)
            
            # Real-time alerting for critical errors
            if error_data['severity'] in ['critical', 'high']:
                self._send_critical_error_alert(error_data)
                
        except Exception as logging_error:
            # Fallback logging
            print(f"Regional geological survey error [{region}-{survey}]: {error}")
            print(f"Logging system error: {logging_error}")
    
    def _query_fault_database(self, db_name: str, config: Dict, lat: float, lon: float) -> Optional[Dict]:
        """Advanced fault database querying with ML-enhanced feature extraction and spatial analysis"""
        try:
            # Initialize query context
            query_context = {
                'database': db_name,
                'query_timestamp': datetime.now().isoformat(),
                'coordinates': {'lat': lat, 'lon': lon},
                'search_radius': config.get('search_radius_km', 50),
                'confidence_threshold': config.get('confidence_threshold', 0.75),
                'ml_enhancement': config.get('enable_ml_enhancement', True)
            }
            
            # Database-specific querying logic
            fault_features = []
            if hasattr(self, 'database_integration') and self.database_integration:
                
                # Spatial query with PostGIS integration
                spatial_query = f"""
                SELECT 
                    fault_id, fault_name, fault_type, strike, dip, rake,
                    displacement_m, age_ma, confidence_score, data_quality,
                    ST_AsText(geometry) as geometry_wkt,
                    ST_Distance(geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance_m
                FROM {db_name}_faults 
                WHERE ST_DWithin(
                    geometry, 
                    ST_SetSRID(ST_MakePoint(%s, %s), 4326), 
                    %s
                ) 
                ORDER BY distance_m ASC
                LIMIT 1000
                """
                
                raw_results = self.database_integration.execute_spatial_query(
                    spatial_query, 
                    (lon, lat, lon, lat, query_context['search_radius'] * 1000)
                )
                
                if raw_results:
                    # Enhanced feature processing with ML
                    for fault_record in raw_results:
                        enhanced_fault = self._enhance_fault_feature_ml(fault_record, lat, lon)
                        if enhanced_fault['confidence_score'] >= query_context['confidence_threshold']:
                            fault_features.append(enhanced_fault)
            
            # Alternative data source integration
            if not fault_features or len(fault_features) < 5:
                external_features = self._query_external_fault_databases(db_name, lat, lon, config)
                fault_features.extend(external_features)
            
            # ML-based fault classification and analysis
            if query_context['ml_enhancement'] and fault_features:
                fault_features = self._apply_ml_fault_classification(fault_features, lat, lon)
            
            # Comprehensive analysis results
            analysis_results = {
                'database': db_name,
                'query_metadata': query_context,
                'total_features': len(fault_features),
                'features': fault_features,
                'spatial_analysis': self._analyze_fault_spatial_distribution(fault_features, lat, lon),
                'kinematic_analysis': self._analyze_fault_kinematics(fault_features),
                'age_distribution': self._analyze_fault_age_distribution(fault_features),
                'quality_assessment': self._assess_fault_data_quality(fault_features),
                'ml_predictions': self._generate_fault_predictions(fault_features, lat, lon) if query_context['ml_enhancement'] else None
            }
            
            # Cache results for performance optimization
            if hasattr(self, 'cache_manager'):
                cache_key = f"fault_query_{db_name}_{lat:.4f}_{lon:.4f}_{query_context['search_radius']}"
                self.cache_manager.store(cache_key, analysis_results, ttl_hours=24)
            
            return analysis_results
            
        except Exception as e:
            self._log_fault_query_error(db_name, str(e))
            return {
                'database': db_name,
                'features': [],
                'error': str(e),
                'fallback_data': self._generate_fallback_fault_data(lat, lon)
            }
    
    def _log_fault_query_error(self, db_name: str, error: str) -> None:
        """Advanced fault query error logging with ML-enhanced diagnostics and recovery"""
        try:
            error_context = {
                'timestamp': datetime.now().isoformat(),
                'database_name': db_name,
                'error_message': error,
                'error_classification': self._classify_fault_error(error),
                'severity_level': self._assess_fault_error_severity(error),
                'recovery_strategy': self._suggest_fault_error_recovery(error, db_name),
                'system_state': {
                    'active_connections': getattr(self, 'active_db_connections', 0),
                    'query_load': getattr(self, 'current_query_load', 'unknown'),
                    'memory_pressure': self._check_memory_pressure()
                }
            }
            
            # Multi-level error logging
            self.logger.error(f"Fault database query error [{db_name}]: {error}")
            
            # Database error tracking if available
            if hasattr(self, 'database_integration') and self.database_integration:
                try:
                    self.database_integration.log_query_error(
                        error_context,
                        table_name='fault_query_errors',
                        include_stacktrace=True
                    )
                except Exception:
                    pass  # Don't fail if error logging fails
            
            # ML-based error pattern recognition
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    pattern_result = self.model_manager.analyze_fault_error_patterns(error_context)
                    if pattern_result and pattern_result.get('known_issue'):
                        self._apply_automated_fault_error_fix(pattern_result)
                except Exception:
                    pass  # Don't fail if ML analysis fails
            
            # Automated recovery attempts for specific error types
            if error_context['error_classification'] in ['connection_timeout', 'database_unavailable']:
                self._attempt_fault_database_recovery(db_name, error_context)
            
            # Critical error alerting
            if error_context['severity_level'] == 'critical':
                self._send_fault_database_alert(error_context)
                
        except Exception as logging_error:
            # Ultimate fallback
            print(f"Fault database query error [{db_name}]: {error}")
            print(f"Error logging system failure: {logging_error}")
    
