    def _classify_dominant_fault_types(self, fault_data: Dict) -> List[str]:
        """Advanced ML-enhanced fault type classification with geological context analysis"""
        try:
            features = fault_data.get('features', [])
            if not features:
                return ['unknown']
            
            # Extract fault parameters for classification
            fault_parameters = []
            for feature in features:
                params = {
                    'strike': feature.get('strike', 0),
                    'dip': feature.get('dip', 90),
                    'rake': feature.get('rake', 0),
                    'displacement': feature.get('displacement_m', 0),
                    'length': feature.get('length_m', 0),
                    'confidence': feature.get('confidence_score', 0.5)
                }
                fault_parameters.append(params)
            
            # ML-based fault type classification
            if hasattr(self, 'model_manager') and self.model_manager:
                ml_classifications = self.model_manager.classify_fault_types(fault_parameters)
                if ml_classifications:
                    return ml_classifications
            
            # Traditional geometric classification with advanced analysis
            fault_types = []
            type_counts = {'normal': 0, 'reverse': 0, 'thrust': 0, 'strike_slip': 0, 'oblique': 0, 'unknown': 0}
            
            for params in fault_parameters:
                fault_type = self._classify_single_fault_type(params)
                fault_types.append(fault_type)
                type_counts[fault_type] += 1
            
            # Statistical analysis of fault type distribution
            total_faults = len(fault_types)
            dominant_types = []
            
            for fault_type, count in type_counts.items():
                if count > 0:
                    percentage = (count / total_faults) * 100
                    if percentage >= 15:  # At least 15% to be considered dominant
                        dominant_types.append(fault_type)
            
            # Sort by frequency
            dominant_types.sort(key=lambda x: type_counts[x], reverse=True)
            
            return dominant_types if dominant_types else ['unknown']
            
        except Exception as e:
            self.logger.error(f"Fault type classification error: {str(e)}")
            return ['unknown']
    
    def _determine_tectonic_setting_from_faults(self, fault_data: Dict, lat: float, lon: float) -> str:
        """Advanced tectonic setting determination using ML-enhanced geological analysis"""
        try:
            features = fault_data.get('features', [])
            
            # Multi-criteria tectonic analysis
            tectonic_indicators = {
                'location_analysis': self._analyze_tectonic_location(lat, lon),
                'fault_pattern_analysis': self._analyze_fault_patterns(features),
                'stress_regime_analysis': self._analyze_regional_stress_regime(features),
                'seismicity_analysis': self._analyze_seismicity_patterns(lat, lon),
                'geological_context': self._analyze_geological_context(lat, lon)
            }
            
            # ML-based tectonic classification if available
            if hasattr(self, 'model_manager') and self.model_manager:
                ml_classification = self.model_manager.classify_tectonic_setting(
                    tectonic_indicators, lat, lon
                )
                if ml_classification and ml_classification.get('confidence', 0) > 0.75:
                    return ml_classification['setting']
            
            # Rule-based tectonic setting determination
            setting_scores = {
                'extensional': 0,
                'compressional': 0,
                'strike_slip': 0,
                'stable_continental': 0,
                'active_margin': 0,
                'intraplate': 0
            }
            
            # Analyze fault types for tectonic signature
            dominant_fault_types = self._classify_dominant_fault_types(fault_data)
            for fault_type in dominant_fault_types:
                if fault_type == 'normal':
                    setting_scores['extensional'] += 3
                elif fault_type in ['reverse', 'thrust']:
                    setting_scores['compressional'] += 3
                elif fault_type == 'strike_slip':
                    setting_scores['strike_slip'] += 2
            
            # Location-based scoring
            location_setting = tectonic_indicators['location_analysis']
            if location_setting in setting_scores:
                setting_scores[location_setting] += 2
            
            # Seismicity-based scoring
            seismicity_level = tectonic_indicators['seismicity_analysis'].get('activity_level', 'low')
            if seismicity_level == 'high':
                setting_scores['active_margin'] += 2
            elif seismicity_level == 'low':
                setting_scores['stable_continental'] += 2
                setting_scores['intraplate'] += 1
            
            # Determine dominant setting
            dominant_setting = max(setting_scores, key=setting_scores.get)
            max_score = setting_scores[dominant_setting]
            
            # Confidence assessment
            total_score = sum(setting_scores.values())
            confidence = max_score / total_score if total_score > 0 else 0
            
            if confidence < 0.4:
                return 'mixed_setting'
            
            return dominant_setting
            
        except Exception as e:
            self.logger.error(f"Tectonic setting determination error: {str(e)}")
            return 'unknown'
    
    def _find_nearest_major_fault(self, fault_data: Dict, lat: float, lon: float) -> Dict:
        """Advanced nearest major fault analysis with ML-enhanced significance assessment"""
        try:
            features = fault_data.get('features', [])
            if not features:
                return {'distance_km': float('inf'), 'fault_name': 'none_found', 'confidence': 0.0}
            
            target_point = (lat, lon)
            nearest_fault = None
            min_distance = float('inf')
            
            # Analyze each fault for significance and proximity
            fault_analyses = []
            for feature in features:
                fault_analysis = {
                    'fault_id': feature.get('fault_id', 'unknown'),
                    'fault_name': feature.get('fault_name', 'unnamed'),
                    'distance_km': self._calculate_fault_distance(feature, lat, lon),
                    'significance_score': self._calculate_fault_significance(feature),
                    'activity_level': feature.get('activity_level', 'unknown'),
                    'length_km': feature.get('length_m', 0) / 1000.0,
                    'displacement_m': feature.get('displacement_m', 0),
                    'confidence_score': feature.get('confidence_score', 0.5),
                    'age_ma': feature.get('age_ma', None),
                    'fault_type': feature.get('fault_type', 'unknown')
                }
                fault_analyses.append(fault_analysis)
            
            # ML-enhanced fault importance ranking
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    importance_ranking = self.model_manager.rank_fault_importance(
                        fault_analyses, target_point
                    )
                    if importance_ranking:
                        fault_analyses = importance_ranking
                except Exception as ml_error:
                    self.logger.warning(f"ML fault ranking failed: {ml_error}")
            
            # Filter for major faults (using multiple criteria)
            major_fault_criteria = {
                'min_length_km': 10.0,
                'min_significance_score': 0.6,
                'max_distance_km': 200.0,
                'active_within_ma': 2.6  # Quaternary
            }
            
            major_faults = []
            for fault in fault_analyses:
                if self._is_major_fault(fault, major_fault_criteria):
                    major_faults.append(fault)
            
            if not major_faults:
                # Relax criteria if no major faults found
                relaxed_criteria = {
                    'min_length_km': 5.0,
                    'min_significance_score': 0.4,
                    'max_distance_km': 500.0,
                    'active_within_ma': 5.0
                }
                for fault in fault_analyses:
                    if self._is_major_fault(fault, relaxed_criteria):
                        major_faults.append(fault)
            
            if not major_faults:
                return {
                    'distance_km': min([f['distance_km'] for f in fault_analyses]),
                    'fault_name': 'no_major_fault_found',
                    'confidence': 0.0,
                    'analysis_summary': 'No major faults identified within search criteria'
                }
            
            # Find nearest major fault with comprehensive analysis
            nearest_major = min(major_faults, key=lambda x: x['distance_km'])
            
            # Enhanced result with detailed analysis
            result = {
                'distance_km': nearest_major['distance_km'],
                'fault_name': nearest_major['fault_name'],
                'fault_id': nearest_major['fault_id'],
                'confidence': nearest_major['confidence_score'],
                'fault_characteristics': {
                    'length_km': nearest_major['length_km'],
                    'displacement_m': nearest_major['displacement_m'],
                    'fault_type': nearest_major['fault_type'],
                    'activity_level': nearest_major['activity_level'],
                    'age_ma': nearest_major['age_ma'],
                    'significance_score': nearest_major['significance_score']
                },
                'hazard_implications': self._assess_fault_hazard_implications(nearest_major, lat, lon),
                'alternative_major_faults': sorted(major_faults, key=lambda x: x['distance_km'])[:5],
                'analysis_metadata': {
                    'total_faults_analyzed': len(features),
                    'major_faults_identified': len(major_faults),
                    'search_radius_km': major_fault_criteria['max_distance_km']
                }
            }
            
            # Store analysis results
            if hasattr(self, 'database_integration') and self.database_integration:
                self.database_integration.store_nearest_fault_analysis(
                    result, lat, lon, table_name='nearest_major_fault_analysis'
                )
            
            return result
            
        except Exception as e:
            self.logger.error(f"Nearest major fault analysis error: {str(e)}")
            return {
                'distance_km': float('inf'),
                'fault_name': 'analysis_error',
                'confidence': 0.0,
                'error': str(e)
            }
    
    def _compute_advanced_fault_density(self, fault_data: Dict, lat: float, lon: float) -> float:
        """Advanced fault density computation with ML-enhanced spatial analysis and geological context"""
        try:
            features = fault_data.get('features', [])
            if not features:
                return 0.0
            
            # Multi-scale density analysis
            density_results = {
                'point_density': 0.0,
                'length_weighted_density': 0.0,
                'displacement_weighted_density': 0.0,
                'activity_weighted_density': 0.0,
                'quality_weighted_density': 0.0
            }
            
            # Define analysis scales (km)
            analysis_scales = [5, 10, 25, 50, 100]
            scale_densities = {}
            
            for scale_km in analysis_scales:
                scale_analysis = self._compute_fault_density_at_scale(
                    features, lat, lon, scale_km
                )
                scale_densities[f'{scale_km}km'] = scale_analysis
            
            # Comprehensive density metrics
            total_area_km2 = np.pi * (50 ** 2)  # Default 50km radius analysis area
            
            # Point density (number of faults per km²)
            density_results['point_density'] = len(features) / total_area_km2
            
            # Length-weighted density (total fault length per km²)
            total_fault_length = sum(f.get('length_m', 0) for f in features) / 1000.0  # Convert to km
            density_results['length_weighted_density'] = total_fault_length / total_area_km2
            
            # Displacement-weighted density
            total_displacement = sum(f.get('displacement_m', 0) for f in features)
            density_results['displacement_weighted_density'] = (total_displacement / 1000.0) / total_area_km2
            
            # Activity-weighted density
            activity_weights = {'active': 1.0, 'potentially_active': 0.7, 'inactive': 0.3, 'unknown': 0.5}
            weighted_activity_sum = sum(
                activity_weights.get(f.get('activity_level', 'unknown'), 0.5) 
                for f in features
            )
            density_results['activity_weighted_density'] = weighted_activity_sum / total_area_km2
            
            # Quality-weighted density
            quality_weighted_sum = sum(f.get('confidence_score', 0.5) for f in features)
            density_results['quality_weighted_density'] = quality_weighted_sum / total_area_km2
            
            # ML-enhanced density prediction
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    ml_density_prediction = self.model_manager.predict_fault_density(
                        features, lat, lon, density_results
                    )
                    if ml_density_prediction:
                        density_results['ml_predicted_density'] = ml_density_prediction
                except Exception as ml_error:
                    self.logger.warning(f"ML density prediction failed: {ml_error}")
            
            # Spatial clustering analysis
            clustering_analysis = self._analyze_fault_clustering(features, lat, lon)
            density_results['clustering_metrics'] = clustering_analysis
            
            # Fractal dimension analysis
            fractal_dimension = self._calculate_fault_fractal_dimension(features)
            density_results['fractal_dimension'] = fractal_dimension
            
            # Geological context adjustment
            geological_context = self._get_geological_context(lat, lon)
            context_adjusted_density = self._adjust_density_for_geological_context(
                density_results, geological_context
            )
            
            # Compute composite density score
            composite_density = self._compute_composite_fault_density(
                density_results, scale_densities, geological_context
            )
            
            # Store comprehensive analysis
            comprehensive_analysis = {
                'location': {'lat': lat, 'lon': lon},
                'density_metrics': density_results,
                'scale_analysis': scale_densities,
                'geological_context': geological_context,
                'composite_density': composite_density,
                'analysis_timestamp': datetime.now().isoformat()
            }
            
            if hasattr(self, 'database_integration') and self.database_integration:
                self.database_integration.store_fault_density_analysis(
                    comprehensive_analysis,
                    table_name='advanced_fault_density_analysis'
                )
            
            return composite_density
            
        except Exception as e:
            self.logger.error(f"Advanced fault density computation error: {str(e)}")
            return 0.0
    
    def _compute_seismic_hazard_level(self, fault_data: Dict, lat: float, lon: float) -> str:
        """Advanced seismic hazard level computation with probabilistic analysis and ML enhancement"""
        try:
            # Comprehensive hazard assessment
            hazard_analysis = self._analyze_comprehensive_seismic_data(fault_data, lat, lon)
            
            # Extract key hazard metrics
            hazard_metrics = {
                'pga_475yr': 0.0,  # Peak Ground Acceleration for 475-year return period
                'pga_2475yr': 0.0,  # Peak Ground Acceleration for 2475-year return period
                'fault_proximity_score': 0.0,
                'source_activity_score': 0.0,
                'site_amplification_factor': 1.0,
                'background_seismicity': 0.0
            }
            
            # Extract hazard values from comprehensive analysis
            if 'hazard_curves' in hazard_analysis:
                pga_curve = hazard_analysis['hazard_curves'].get('pga_curve', {})
                hazard_metrics['pga_475yr'] = pga_curve.get('475_year_pga', 0.0)
                hazard_metrics['pga_2475yr'] = pga_curve.get('2475_year_pga', 0.0)
            
            # Fault proximity assessment
            nearest_fault = self._find_nearest_major_fault(fault_data, lat, lon)
            if nearest_fault['distance_km'] < float('inf'):
                # Proximity score decreases with distance
                proximity_score = max(0, 1 - (nearest_fault['distance_km'] / 100.0))
                hazard_metrics['fault_proximity_score'] = proximity_score
            
            # Source activity assessment
            features = fault_data.get('features', [])
            active_faults = [f for f in features if f.get('activity_level') == 'active']
            hazard_metrics['source_activity_score'] = len(active_faults) / max(len(features), 1)
            
            # Site effects assessment
            if 'site_effects' in hazard_analysis:
                site_effects = hazard_analysis['site_effects']
                hazard_metrics['site_amplification_factor'] = site_effects.get('site_amplification', {}).get('amplification_factor', 1.0)
            
            # ML-enhanced hazard classification
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    ml_hazard_classification = self.model_manager.classify_seismic_hazard(
                        hazard_metrics, lat, lon, hazard_analysis
                    )
                    if ml_hazard_classification and ml_hazard_classification.get('confidence', 0) > 0.80:
                        return ml_hazard_classification['hazard_level']
                except Exception as ml_error:
                    self.logger.warning(f"ML hazard classification failed: {ml_error}")
            
            # Rule-based hazard level determination
            hazard_score = 0
            
            # PGA-based scoring
            if hazard_metrics['pga_475yr'] > 0.4:  # High PGA
                hazard_score += 4
            elif hazard_metrics['pga_475yr'] > 0.2:  # Moderate PGA
                hazard_score += 2
            elif hazard_metrics['pga_475yr'] > 0.1:  # Low-moderate PGA
                hazard_score += 1
            
            # Proximity-based scoring
            if hazard_metrics['fault_proximity_score'] > 0.8:
                hazard_score += 3
            elif hazard_metrics['fault_proximity_score'] > 0.5:
                hazard_score += 2
            elif hazard_metrics['fault_proximity_score'] > 0.2:
                hazard_score += 1
            
            # Activity-based scoring
            if hazard_metrics['source_activity_score'] > 0.7:
                hazard_score += 2
            elif hazard_metrics['source_activity_score'] > 0.3:
                hazard_score += 1
            
            # Site amplification adjustment
            if hazard_metrics['site_amplification_factor'] > 2.0:
                hazard_score += 2
            elif hazard_metrics['site_amplification_factor'] > 1.5:
                hazard_score += 1
            
            # Determine hazard level
            if hazard_score >= 8:
                hazard_level = 'very_high'
            elif hazard_score >= 6:
                hazard_level = 'high'
            elif hazard_score >= 4:
                hazard_level = 'moderate_high'
            elif hazard_score >= 2:
                hazard_level = 'moderate'
            elif hazard_score >= 1:
                hazard_level = 'low_moderate'
            else:
                hazard_level = 'low'
            
            # Store comprehensive hazard assessment
            hazard_assessment = {
                'location': {'lat': lat, 'lon': lon},
                'hazard_level': hazard_level,
                'hazard_score': hazard_score,
                'hazard_metrics': hazard_metrics,
                'contributing_factors': {
                    'pga_contribution': hazard_metrics['pga_475yr'],
                    'proximity_contribution': hazard_metrics['fault_proximity_score'],
                    'activity_contribution': hazard_metrics['source_activity_score'],
                    'site_contribution': hazard_metrics['site_amplification_factor']
                },
                'confidence_assessment': self._assess_hazard_confidence(hazard_metrics, hazard_analysis),
                'analysis_timestamp': datetime.now().isoformat()
            }
            
            if hasattr(self, 'database_integration') and self.database_integration:
                self.database_integration.store_seismic_hazard_assessment(
                    hazard_assessment,
                    table_name='seismic_hazard_levels'
                )
            
            return hazard_level
            
        except Exception as e:
            self.logger.error(f"Seismic hazard level computation error: {str(e)}")
            return 'unknown'
    
    def _estimate_ground_motion_potential(self, fault_data: Dict, lat: float, lon: float) -> Dict:
        """Advanced ground motion potential estimation with ML-enhanced GMPE models and site-specific analysis"""
        try:
            ground_motion_analysis = {
                'analysis_metadata': {
                    'timestamp': datetime.now().isoformat(),
                    'location': {'lat': lat, 'lon': lon},
                    'analysis_method': 'advanced_multi_gmpe_ml',
                    'return_periods': [72, 475, 975, 2475],
                    'spectral_periods': [0.01, 0.1, 0.2, 0.3, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 4.0, 5.0]
                },
                'intensity_measures': {},
                'scenario_estimates': {},
                'probabilistic_estimates': {},
                'site_specific_adjustments': {},
                'uncertainty_bounds': {},
                'ml_predictions': {}
            }
            
            features = fault_data.get('features', [])
            
            # Scenario-based ground motion estimation
            scenario_estimates = {}
            for i, feature in enumerate(features[:10]):  # Limit to top 10 sources
                scenario_key = f"fault_{i}_{feature.get('fault_name', 'unnamed')}"
                scenario_gm = self._estimate_scenario_ground_motion(feature, lat, lon)
                scenario_estimates[scenario_key] = scenario_gm
            
            ground_motion_analysis['scenario_estimates'] = scenario_estimates
            
            # Probabilistic hazard analysis
            return_periods = ground_motion_analysis['analysis_metadata']['return_periods']
            probabilistic_estimates = {}
            
            for return_period in return_periods:
                rp_estimates = self._compute_probabilistic_ground_motion(
                    features, lat, lon, return_period
                )
                probabilistic_estimates[f'{return_period}_year'] = rp_estimates
            
            ground_motion_analysis['probabilistic_estimates'] = probabilistic_estimates
            
            # Site-specific adjustments
            site_adjustments = {
                'vs30_effects': self._compute_vs30_effects(lat, lon),
                'basin_effects': self._compute_basin_effects(lat, lon),
                'topographic_effects': self._compute_topographic_effects(lat, lon),
                'nonlinear_effects': self._compute_nonlinear_site_effects(lat, lon)
            }
            ground_motion_analysis['site_specific_adjustments'] = site_adjustments
            
            # ML-enhanced ground motion prediction
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    ml_predictions = {
                        'enhanced_pga': self.model_manager.predict_pga_ml(features, lat, lon, site_adjustments),
                        'spectral_accelerations': self.model_manager.predict_spectral_accelerations_ml(features, lat, lon, site_adjustments),
                        'duration_estimates': self.model_manager.predict_duration_ml(features, lat, lon),
                        'arias_intensity': self.model_manager.predict_arias_intensity_ml(features, lat, lon)
                    }
                    ground_motion_analysis['ml_predictions'] = ml_predictions
                except Exception as ml_error:
                    self.logger.warning(f"ML ground motion prediction failed: {ml_error}")
            
            # Comprehensive intensity measures
            intensity_measures = {
                'pga': self._compute_comprehensive_pga(scenario_estimates, probabilistic_estimates),
                'pgv': self._compute_comprehensive_pgv(scenario_estimates, probabilistic_estimates),
                'pga_v': self._compute_pga_v_ratio(scenario_estimates, probabilistic_estimates),
                'spectral_accelerations': self._compute_comprehensive_spectral_accelerations(
                    scenario_estimates, probabilistic_estimates, 
                    ground_motion_analysis['analysis_metadata']['spectral_periods']
                ),
                'significant_duration': self._compute_significant_duration(scenario_estimates, probabilistic_estimates),
                'arias_intensity': self._compute_arias_intensity(scenario_estimates, probabilistic_estimates),
                'cumulative_absolute_velocity': self._compute_cav(scenario_estimates, probabilistic_estimates)
            }
            ground_motion_analysis['intensity_measures'] = intensity_measures
            
            # Uncertainty quantification
            uncertainty_bounds = {
                'aleatory_uncertainty': self._quantify_gm_aleatory_uncertainty(features),
                'epistemic_uncertainty': self._quantify_gm_epistemic_uncertainty(features),
                'site_uncertainty': self._quantify_site_uncertainty(lat, lon),
                'model_uncertainty': self._quantify_gmpe_model_uncertainty()
            }
            ground_motion_analysis['uncertainty_bounds'] = uncertainty_bounds
            
            # Store comprehensive analysis
            if hasattr(self, 'database_integration') and self.database_integration:
                storage_result = self.database_integration.store_ground_motion_analysis(
                    ground_motion_analysis,
                    table_name='ground_motion_potential_analysis'
                )
                ground_motion_analysis['database_storage'] = storage_result
            
            # Return simplified format for compatibility with legacy code
            return {
                'pga': intensity_measures['pga'].get('mean_estimate', 0.1),
                'sa': intensity_measures['spectral_accelerations'].get('sa_0.2s', {}).get('mean_estimate', 0.2),
                'pgv': intensity_measures['pgv'].get('mean_estimate', 10.0),
                'comprehensive_analysis': ground_motion_analysis
            }
            
        except Exception as e:
            self.logger.error(f"Ground motion potential estimation error: {str(e)}")
            return {
                'pga': 0.1,
                'sa': 0.2,
                'error': str(e),
                'fallback_analysis': True
            }
    
    def _compute_seismic_return_periods(self, fault_data: Dict, lat: float, lon: float) -> Dict:
        """Advanced seismic return period analysis with ML-enhanced recurrence modeling and uncertainty quantification"""
        try:
            return_period_analysis = {
                'analysis_metadata': {
                    'timestamp': datetime.now().isoformat(),
                    'location': {'lat': lat, 'lon': lon},
                    'analysis_method': 'advanced_probabilistic_ml',
                    'return_periods_analyzed': [10, 25, 50, 100, 250, 475, 975, 2475, 5000, 10000],
                    'confidence_levels': [0.16, 0.5, 0.84],  # 16th, 50th, 84th percentiles
                    'time_horizon_years': 50
                },
                'recurrence_models': {},
                'return_period_estimates': {},
                'exceedance_probabilities': {},
                'scenario_contributions': {},
                'ml_enhanced_estimates': {},
                'uncertainty_analysis': {}
            }
            
            features = fault_data.get('features', [])
            return_periods = return_period_analysis['analysis_metadata']['return_periods_analyzed']
            
            # Develop recurrence models for each fault source
            recurrence_models = {}
            for i, feature in enumerate(features):
                fault_id = feature.get('fault_id', f'fault_{i}')
                recurrence_model = self._develop_fault_recurrence_model(feature)
                recurrence_models[fault_id] = recurrence_model
            
            # Background seismicity recurrence model
            background_model = self._develop_background_recurrence_model(lat, lon)
            recurrence_models['background_seismicity'] = background_model
            
            return_period_analysis['recurrence_models'] = recurrence_models
            
            # Compute return period estimates for different intensity measures
            intensity_measures = ['pga', 'sa_0.2s', 'sa_1.0s', 'pgv']
            return_period_estimates = {}
            
            for im in intensity_measures:
                im_estimates = {}
                for rp in return_periods:
                    # Combine contributions from all sources
                    total_hazard = self._combine_source_contributions(
                        recurrence_models, im, rp, lat, lon
                    )
                    im_estimates[f'{rp}_year'] = total_hazard
                return_period_estimates[im] = im_estimates
            
            return_period_analysis['return_period_estimates'] = return_period_estimates
            
            # Calculate exceedance probabilities
            exceedance_probabilities = {}
            time_horizon = return_period_analysis['analysis_metadata']['time_horizon_years']
            
            for im in intensity_measures:
                im_exceedance = {}
                for rp in return_periods:
                    annual_prob = 1.0 / rp
                    prob_exceedance = 1 - (1 - annual_prob) ** time_horizon
                    im_exceedance[f'{rp}_year_exceedance'] = prob_exceedance
                exceedance_probabilities[im] = im_exceedance
            
            return_period_analysis['exceedance_probabilities'] = exceedance_probabilities
            
            # Scenario contributions analysis
            scenario_contributions = {}
            for im in intensity_measures:
                contributions = self._analyze_scenario_contributions(
                    recurrence_models, im, lat, lon
                )
                scenario_contributions[im] = contributions
            
            return_period_analysis['scenario_contributions'] = scenario_contributions
            
            # ML-enhanced return period estimation
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    ml_estimates = {}
                    for im in intensity_measures:
                        ml_im_estimates = self.model_manager.predict_return_periods_ml(
                            features, lat, lon, im, return_periods
                        )
                        if ml_im_estimates:
                            ml_estimates[im] = ml_im_estimates
                    return_period_analysis['ml_enhanced_estimates'] = ml_estimates
                except Exception as ml_error:
                    self.logger.warning(f"ML return period estimation failed: {ml_error}")
            
            # Comprehensive uncertainty analysis
            uncertainty_analysis = {
                'parameter_uncertainty': self._quantify_parameter_uncertainty(recurrence_models),
                'model_uncertainty': self._quantify_recurrence_model_uncertainty(),
                'data_uncertainty': self._quantify_data_uncertainty(features),
                'confidence_intervals': self._compute_return_period_confidence_intervals(
                    return_period_estimates, return_period_analysis['analysis_metadata']['confidence_levels']
                )
            }
            return_period_analysis['uncertainty_analysis'] = uncertainty_analysis
            
            # Time-dependent analysis (if fault slip rates are available)
            time_dependent_analysis = self._perform_time_dependent_analysis(features, lat, lon)
            if time_dependent_analysis:
                return_period_analysis['time_dependent_analysis'] = time_dependent_analysis
            
            # Store comprehensive analysis
            if hasattr(self, 'database_integration') and self.database_integration:
                storage_result = self.database_integration.store_return_period_analysis(
                    return_period_analysis,
                    table_name='seismic_return_period_analysis'
                )
                return_period_analysis['database_storage'] = storage_result
            
            # Return simplified format for legacy compatibility
            pga_estimates = return_period_estimates.get('pga', {})
            return {
                '10_year': pga_estimates.get('10_year', 0.05),
                '25_year': pga_estimates.get('25_year', 0.07),
                '50_year': pga_estimates.get('50_year', 0.08),
                '100_year': pga_estimates.get('100_year', 0.09),
                '475_year': pga_estimates.get('475_year', 0.15),
                '975_year': pga_estimates.get('975_year', 0.20),
                '2475_year': pga_estimates.get('2475_year', 0.30),
                '5000_year': pga_estimates.get('5000_year', 0.40),
                '10000_year': pga_estimates.get('10000_year', 0.50),
                'comprehensive_analysis': return_period_analysis
            }
            
        except Exception as e:
            self.logger.error(f"Seismic return period computation error: {str(e)}")
            return {
                '475_year': 0.1,
                '2475_year': 0.3,
                'error': str(e),
                'fallback_analysis': True
            }
    
