    def _ml_geological_feature_classification(self, lat: float, lon: float) -> Dict[str, Any]:
        """Advanced ML-based geological feature classification with model versioning and automated retraining"""
        try:
            # Initialize advanced geological analysis if not already done
            if not hasattr(self, 'model_manager') or self.model_manager is None:
                self._initialize_advanced_geological_analysis()
            
            # Check for cached results first
            cached_result = self._get_cached_geological_data('geological', lat, lon)
            if cached_result and cached_result.get('cache_hit'):
                self.logger.debug(f"Using cached geological classification for {lat}, {lon}")
                cached_result['classification_source'] = 'cache'
                return cached_result
            
            # Gather comprehensive feature set
            feature_vector = self._compile_geological_feature_vector(lat, lon)
            
            # Load active geological classification models
            classification_models = self._load_geological_classification_models()
            
            # Multi-model ensemble classification
            classification_results = {}
            model_predictions = []
            confidence_scores = []
            
            if classification_models:
                for model_name, model_info in classification_models.items():
                    try:
                        # Load the specific model
                        model_path = self.model_database.get_model(model_info['model_id'])
                        
                        if model_path and self._is_model_compatible(model_info, feature_vector):
                            # Load PyTorch model
                            model = self._load_pytorch_geological_model(model_path, model_info)
                            
                            if model:
                                # Make prediction
                                prediction = self._predict_geological_features(model, feature_vector, model_info)
                                
                                # Store individual model result
                                classification_results[model_name] = {
                                    'prediction': prediction,
                                    'confidence': prediction.get('confidence', 0.5),
                                    'model_version': model_info.get('version', '1.0'),
                                    'model_accuracy': model_info.get('accuracy', 0.8),
                                    'last_trained': model_info.get('last_trained', 'unknown')
                                }
                                
                                model_predictions.append(prediction)
                                confidence_scores.append(prediction.get('confidence', 0.5))
                    
                    except Exception as model_error:
                        self.logger.warning(f"Error with model {model_name}: {str(model_error)}")
                        continue
            
            # Ensemble prediction combining multiple models
            if model_predictions:
                ensemble_prediction = self._create_ensemble_geological_prediction(
                    model_predictions, confidence_scores, classification_results
                )
            else:
                # Fallback to rule-based classification
                ensemble_prediction = self._fallback_geological_classification(feature_vector, lat, lon)
            
            # Uncertainty quantification
            prediction_uncertainty = self._quantify_classification_uncertainty(
                model_predictions, confidence_scores
            )
            ensemble_prediction['uncertainty'] = prediction_uncertainty
            
            # Model performance assessment and retraining trigger
            classification_quality = self._assess_classification_quality(
                ensemble_prediction, feature_vector, lat, lon
            )
            
            # Trigger automated retraining if needed
            if classification_quality < 0.6:
                self._schedule_model_retraining(classification_results, feature_vector, ensemble_prediction)
            
            # Cache results for future queries
            cache_data = {
                'geological_classification': ensemble_prediction,
                'model_count': len(classification_results),
                'confidence': ensemble_prediction.get('overall_confidence', 0.5),
                'classification_timestamp': self._get_current_timestamp()
            }
            self._cache_geological_data('geological', lat, lon, cache_data)
            
            # Comprehensive result structure
            final_result = {
                'primary_classification': ensemble_prediction,
                'model_results': classification_results,
                'feature_vector_summary': self._summarize_feature_vector(feature_vector),
                'classification_quality': classification_quality,
                'ensemble_method': 'weighted_voting',
                'model_count': len(classification_results),
                'processing_timestamp': self._get_current_timestamp(),
                'classification_source': 'ml_ensemble'
            }
            
            return final_result
            
        except Exception as e:
            self.logger.error(f"Error in ML geological classification: {str(e)}")
            # Fallback to basic geological analysis
            return {
                'primary_classification': self._basic_geological_classification(lat, lon),
                'model_results': {},
                'classification_quality': 0.2,
                'ensemble_method': 'fallback',
                'model_count': 0,
                'processing_timestamp': self._get_current_timestamp(),
                'classification_source': 'fallback',
                'error': str(e)
            }
    
    def _compile_geological_feature_vector(self, lat: float, lon: float) -> np.ndarray:
        """Compile comprehensive geological feature vector for ML classification"""
        try:
            features = []
            
            # Basic geographic features
            features.extend([lat, lon])
            
            # Topographic features
            try:
                topo_data = self._query_topography_model('srtm', lat, lon)
                if isinstance(topo_data, dict):
                    features.extend([
                        topo_data.get('elevation_m', 0),
                        topo_data.get('uncertainty_m', 0),
                        topo_data.get('confidence', 0.5)
                    ])
                else:
                    features.extend([0, 0, 0.3])
            except:
                features.extend([0, 0, 0.3])
            
            # Tectonic features
            try:
                tectonic_data = self._calculate_plate_boundary_distance(lat, lon)
                if isinstance(tectonic_data, dict):
                    features.extend([
                        tectonic_data.get('distance_km', 1000),
                        tectonic_data.get('seismic_activity_factor', 1.0),
                        tectonic_data.get('confidence', 0.5)
                    ])
                else:
                    features.extend([1000, 1.0, 0.3])
            except:
                features.extend([1000, 1.0, 0.3])
            
            # Convergent setting features
            try:
                convergent_data = self._assess_convergent_setting(lat, lon)
                if isinstance(convergent_data, dict):
                    features.extend([
                        convergent_data.get('convergent_score', 0.5),
                        convergent_data.get('confidence', 0.5),
                        convergent_data.get('uncertainty', 0.4)
                    ])
                else:
                    features.extend([0.5, 0.3, 0.4])
            except:
                features.extend([0.5, 0.3, 0.4])
            
            # Orogenic belt features
            try:
                orogenic_data = self._assess_orogenic_belt(lat, lon)
                if isinstance(orogenic_data, dict):
                    features.extend([
                        orogenic_data.get('orogenic_score', 0.5),
                        orogenic_data.get('confidence', 0.5),
                        orogenic_data.get('uncertainty', 0.4)
                    ])
                else:
                    features.extend([0.5, 0.3, 0.4])
            except:
                features.extend([0.5, 0.3, 0.4])
            
            # Plutonic density features
            try:
                plutonic_data = self._estimate_plutonic_density(lat, lon)
                if isinstance(plutonic_data, dict):
                    features.extend([
                        plutonic_data.get('density', 0.5),
                        plutonic_data.get('confidence', 0.5),
                        plutonic_data.get('uncertainty', 0.4)
                    ])
                else:
                    features.extend([0.5, 0.3, 0.4])
            except:
                features.extend([0.5, 0.3, 0.4])
            
            # Regional classification features
            try:
                region_data = self._determine_region(lat, lon)
                if isinstance(region_data, dict):
                    # Encode primary region as numerical feature
                    region_encoding = self._encode_region(region_data.get('primary_region', 'global'))
                    features.extend([
                        region_encoding,
                        region_data.get('confidence', 0.5)
                    ])
                else:
                    features.extend([0, 0.3])
            except:
                features.extend([0, 0.3])
            
            # Multi-layer integrated features (if available)
            try:
                integrated_data = self._integrate_multi_layer_geological_processing(lat, lon)
                if isinstance(integrated_data, dict) and integrated_data.get('layer_count', 0) > 0:
                    integrated_analysis = integrated_data.get('integrated_analysis', {})
                    features.extend([
                        integrated_analysis.get('overall_confidence', 0.5),
                        integrated_data.get('layer_count', 0) / 6.0,  # Normalized layer coverage
                        integrated_analysis.get('data_completeness', 0.3)
                    ])
                else:
                    features.extend([0.3, 0.2, 0.3])
            except:
                features.extend([0.3, 0.2, 0.3])
            
            # Convert to numpy array and handle any NaN values
            feature_array = np.array(features, dtype=np.float32)
            feature_array = np.nan_to_num(feature_array, nan=0.0, posinf=1.0, neginf=0.0)
            
            return feature_array
            
        except Exception as e:
            self.logger.error(f"Error compiling geological feature vector: {str(e)}")
            # Return minimal feature vector
            return np.zeros(20, dtype=np.float32)
    
    def _load_geological_classification_models(self) -> Dict[str, Dict]:
        """Load active geological classification models from model database"""
        try:
            if not hasattr(self, 'model_database') or self.model_database is None:
                return {}
            
            # Search for geological classification models
            models = self.model_database.search_models({
                'model_type': 'geological_classification',
                'status': 'active',
                'framework': 'pytorch'
            })
            
            if not models:
                # Fallback to general geological models
                models = self.model_database.search_models({
                    'model_type': 'geological',
                    'status': 'active'
                })
            
            return {f"model_{i}": model for i, model in enumerate(models)}
            
        except Exception as e:
            self.logger.error(f"Error loading geological classification models: {str(e)}")
            return {}
    
    def _create_ensemble_geological_prediction(self, predictions: List[Dict], 
                                             confidences: List[float], 
                                             model_results: Dict) -> Dict[str, Any]:
        """Create ensemble prediction from multiple geological classification models"""
        try:
            if not predictions:
                return self._default_geological_prediction()
            
            # Weighted voting based on model confidence and accuracy
            weights = []
            for i, (model_name, result) in enumerate(model_results.items()):
                model_accuracy = result.get('model_accuracy', 0.8)
                prediction_confidence = confidences[i] if i < len(confidences) else 0.5
                weight = model_accuracy * prediction_confidence
                weights.append(weight)
            
            # Normalize weights
            total_weight = sum(weights)
            normalized_weights = [w / total_weight for w in weights] if total_weight > 0 else [1/len(predictions)] * len(predictions)
            
            # Ensemble classification categories
            ensemble_result = {
                'rock_type': self._ensemble_categorical_prediction(predictions, 'rock_type', normalized_weights),
                'geological_age_ma': self._ensemble_numerical_prediction(predictions, 'geological_age_ma', normalized_weights),
                'tectonic_setting': self._ensemble_categorical_prediction(predictions, 'tectonic_setting', normalized_weights),
                'metamorphic_grade': self._ensemble_categorical_prediction(predictions, 'metamorphic_grade', normalized_weights),
                'structural_complexity': self._ensemble_numerical_prediction(predictions, 'structural_complexity', normalized_weights),
                'resource_potential': self._ensemble_numerical_prediction(predictions, 'resource_potential', normalized_weights),
                'overall_confidence': np.average(confidences, weights=normalized_weights) if confidences else 0.5,
                'prediction_method': 'weighted_ensemble'
            }
            
            return ensemble_result
            
        except Exception as e:
            self.logger.error(f"Error creating ensemble prediction: {str(e)}")
            return self._default_geological_prediction()
    
    def _schedule_model_retraining(self, model_results: Dict, feature_vector: np.ndarray, prediction: Dict):
        """Schedule automated model retraining based on performance assessment"""
        try:
            if not hasattr(self, 'model_manager') or self.model_manager is None:
                return
            
            # Assess which models need retraining
            models_for_retraining = []
            
            for model_name, result in model_results.items():
                model_confidence = result.get('confidence', 0.5)
                model_accuracy = result.get('model_accuracy', 0.8)
                
                # Trigger retraining if confidence is low or accuracy has degraded
                if model_confidence < 0.5 or model_accuracy < 0.7:
                    models_for_retraining.append(model_name)
            
            if models_for_retraining:
                # Schedule retraining job with model manager
                retraining_config = {
                    'models': models_for_retraining,
                    'trigger': 'performance_degradation',
                    'feature_vector_sample': feature_vector.tolist(),
                    'prediction_sample': prediction,
                    'priority': 'medium',
                    'scheduled_time': self._get_current_timestamp()
                }
                
                # Use model manager to schedule retraining
                if hasattr(self.model_manager, 'schedule_retraining'):
                    self.model_manager.schedule_retraining(retraining_config)
                    self.logger.info(f"Scheduled retraining for {len(models_for_retraining)} geological models")
            
        except Exception as e:
            self.logger.error(f"Error scheduling model retraining: {str(e)}")
    
    def _is_shield_location(self, lat: float, lon: float) -> Tuple[bool, Dict[str, Any]]:
        """Advanced Precambrian shield detection using geological age database and crustal analysis
        
        Args:
            lat: Latitude in decimal degrees
            lon: Longitude in decimal degrees
            
        Returns:
            Tuple of (is_shield: bool, geological_metrics: Dict)
        """
        try:
            # Query geological age database for crustal age information
            geological_age_data = self._query_geological_age_database(lat, lon)
            
            # Analyze crustal thickness and structure
            crustal_analysis = self._analyze_crustal_characteristics(lat, lon)
            
            # Integrate geophysical indicators
            geophysical_indicators = self._analyze_shield_geophysical_signatures(lat, lon)
            
            # Perform comprehensive shield classification
            is_shield = self._classify_precambrian_shield(
                geological_age_data, crustal_analysis, geophysical_indicators
            )
            
            # Compile comprehensive geological metrics
            geological_metrics = {
                **geological_age_data,
                **crustal_analysis,
                **geophysical_indicators,
                'confidence': self._calculate_shield_confidence(
                    geological_age_data, crustal_analysis, geophysical_indicators
                )
            }
            
            return is_shield, geological_metrics
            
        except Exception as e:
            self.logger.warning(f"Advanced shield detection failed: {e}")
            # Fallback to regional shield boundaries
            return self._fallback_shield_check(lat, lon)
    
    def _query_geological_age_database(self, lat: float, lon: float) -> Dict[str, Any]:
        """Query geological age database for crustal age information"""
        try:
            age_data = {}
            
            # Query model database for geological age models
            if hasattr(self, 'model_database') and self.model_database:
                age_models = self.model_database.search_models({
                    'model_type': 'geological_age',
                    'region': self._determine_geological_region(lat, lon)
                })
                
                if age_models:
                    # Query the most recent geological age model
                    age_data['crustal_age'] = self._query_age_model(age_models[0], lat, lon)
                    age_data['age_confidence'] = 0.8
                    age_data['data_source'] = 'database'
            
            # Query data integration pipeline for geological maps
            if hasattr(self, 'data_pipeline') and self.data_pipeline:
                geology_layer = self.data_pipeline.get_layer('geology')
                if geology_layer:
                    geological_unit = geology_layer.sample_at_coordinates(lat, lon)
                    if geological_unit:
                        age_data.update(self._interpret_geological_unit(geological_unit))
            
            # Fallback to global geological age estimation
            if not age_data or 'crustal_age' not in age_data:
                age_data.update(self._estimate_global_crustal_age(lat, lon))
            
            return age_data
            
        except Exception as e:
            self.logger.debug(f"Geological age database query failed: {e}")
            return self._estimate_global_crustal_age(lat, lon)
    
    def _analyze_crustal_characteristics(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze crustal thickness and structural characteristics"""
        try:
            crustal_metrics = {}
            
            # Crustal thickness analysis
            crustal_metrics['crustal_thickness'] = self._estimate_crustal_thickness(lat, lon)
            
            # Moho depth estimation
            crustal_metrics['moho_depth'] = self._estimate_moho_depth(lat, lon)
            
            # Lithospheric thickness
            crustal_metrics['lithosphere_thickness'] = self._estimate_lithosphere_thickness(lat, lon)
            
            # Crustal density analysis
            crustal_metrics['crustal_density'] = self._estimate_crustal_density(lat, lon)
            
            # Heat flow characteristics (shields have low heat flow)
            crustal_metrics['heat_flow'] = self._estimate_heat_flow(lat, lon)
            
            # Isostatic state
            crustal_metrics['isostatic_state'] = self._analyze_isostatic_state(lat, lon)
            
            # Structural stability index
            crustal_metrics['stability_index'] = self._calculate_structural_stability(lat, lon)
            
            return crustal_metrics
            
        except Exception as e:
            self.logger.debug(f"Crustal analysis failed: {e}")
            return {'crustal_thickness': 35.0, 'heat_flow': 40.0}
    
    def _analyze_shield_geophysical_signatures(self, lat: float, lon: float) -> Dict[str, float]:
        """Analyze geophysical signatures characteristic of shields"""
        try:
            signatures = {}
            
            # Gravity field analysis (shields show subdued gravity anomalies)
            signatures['gravity_signature'] = self._analyze_gravity_field(lat, lon)
            
            # Magnetic field characteristics (shields have complex magnetic patterns)
            signatures['magnetic_signature'] = self._analyze_magnetic_field(lat, lon)
            
            # Seismic velocity structure
            signatures['seismic_velocity'] = self._analyze_seismic_velocity(lat, lon)
            
            # Regional geological complexity
            signatures['geological_complexity'] = self._assess_geological_complexity(lat, lon)
            
            # Metamorphic grade indicators
            signatures['metamorphic_grade'] = self._assess_metamorphic_grade(lat, lon)
            
            # Mineral resource indicators (shields are rich in certain minerals)
            signatures['mineral_resource_potential'] = self._assess_mineral_resources(lat, lon)
            
            # Surface weathering characteristics
            signatures['weathering_profile'] = self._analyze_weathering_profile(lat, lon)
            
            return signatures
            
        except Exception as e:
            self.logger.debug(f"Geophysical signature analysis failed: {e}")
            return {'gravity_signature': 0.5, 'magnetic_signature': 0.5}
    
    def _classify_precambrian_shield(self, age_data: Dict[str, Any],
                                   crustal_data: Dict[str, float],
                                   geophysical_data: Dict[str, float]) -> bool:
        """Advanced Precambrian shield classification using multiple criteria"""
        try:
            # Multi-criteria shield classification
            shield_score = 0.0
            weights = {
                'geological_age': 0.35,
                'crustal_thickness': 0.20,
                'stability': 0.15,
                'geophysical': 0.15,
                'metamorphic': 0.10,
                'structural': 0.05
            }
            
            # Geological age criterion (primary for shields)
            crustal_age = age_data.get('crustal_age', 1000)  # Ma
            if crustal_age > 2500:  # Archean (very old)
                shield_score += weights['geological_age'] * 1.0
            elif crustal_age > 1800:  # Paleoproterozoic (old)
                shield_score += weights['geological_age'] * 0.8
            elif crustal_age > 1000:  # Mesoproterozoic
                shield_score += weights['geological_age'] * 0.6
            elif crustal_age > 540:  # Neoproterozoic
                shield_score += weights['geological_age'] * 0.3
            
            # Crustal thickness (shields have thick, stable crust)
            thickness = crustal_data.get('crustal_thickness', 35)
            if thickness > 40:  # Very thick crust
                shield_score += weights['crustal_thickness'] * 1.0
            elif thickness > 35:  # Thick crust
                shield_score += weights['crustal_thickness'] * 0.7
            elif thickness > 30:  # Moderate thickness
                shield_score += weights['crustal_thickness'] * 0.4
            
            # Structural stability
            stability = crustal_data.get('stability_index', 0.5)
            shield_score += weights['stability'] * stability
            
            # Geophysical signatures
            gravity_sig = geophysical_data.get('gravity_signature', 0.5)
            magnetic_sig = geophysical_data.get('magnetic_signature', 0.5)
            geophysical_score = (gravity_sig + magnetic_sig) / 2
            shield_score += weights['geophysical'] * geophysical_score
            
            # Metamorphic grade (shields have high-grade metamorphics)
            metamorphic = geophysical_data.get('metamorphic_grade', 0.5)
            shield_score += weights['metamorphic'] * metamorphic
            
            # Structural complexity (shields have complex structures)
            complexity = geophysical_data.get('geological_complexity', 0.5)
            shield_score += weights['structural'] * complexity
            
            # Classification threshold for shields
            shield_threshold = 0.65
            return shield_score > shield_threshold
            
        except Exception:
            # Fallback to simple age-based classification
            crustal_age = age_data.get('crustal_age', 1000)
            return crustal_age > 1800  # Precambrian cutoff
    
    def _calculate_shield_confidence(self, age_data: Dict[str, Any],
                                   crustal_data: Dict[str, float],
                                   geophysical_data: Dict[str, float]) -> float:
        """Calculate confidence level for shield classification"""
        try:
            confidence = 0.5  # Base confidence
            
            # Increase confidence based on data quality
            if age_data.get('data_source') == 'database':
                confidence += 0.2  # High-quality database
            
            if age_data.get('age_confidence', 0) > 0.7:
                confidence += 0.2  # Reliable age data
            
            # Confidence from multiple indicators agreement
            indicators = [
                1.0 if age_data.get('crustal_age', 1000) > 1800 else 0.0,
                1.0 if crustal_data.get('crustal_thickness', 35) > 35 else 0.0,
                crustal_data.get('stability_index', 0.5),
                geophysical_data.get('gravity_signature', 0.5)
            ]
            
            indicator_agreement = sum(1 for i in indicators if i > 0.6) / len(indicators)
            confidence += 0.2 * indicator_agreement
            
            return min(confidence, 1.0)
            
        except Exception:
            return 0.5
    
    # Helper methods for shield analysis
    def _estimate_global_crustal_age(self, lat: float, lon: float) -> Dict[str, Any]:
        """Advanced crustal age estimation using ML models and geological database integration"""
        try:
            # Initialize model database integration for age estimation models
            if not hasattr(self, 'model_database') or self.model_database is None:
                try:
                    from .model_database import ModelDatabase
                    db_config = {'host': 'localhost', 'database': 'prometheus_models'}
                    self.model_database = ModelDatabase(db_config)
                except Exception:
                    self.model_database = None
            
            # Initialize geological data pipeline for multi-source age data
            if not hasattr(self, 'geological_data_pipeline'):
                try:
                    from .data_integration_pipeline import DataIntegrationPipeline, GeophysicalProcessor
                    self.geological_data_pipeline = DataIntegrationPipeline()
                    self.geophysical_processor = GeophysicalProcessor()
                except Exception:
                    self.geological_data_pipeline = None
                    self.geophysical_processor = None
            
            # Multi-source age estimation approach
            age_estimates = []
            confidence_scores = []
            data_sources = []
            
            # 1. ML-based age estimation using trained models
            if self.model_database:
                try:
                    age_models = self.model_database.search_models({
                        'model_type': 'crustal_age_estimation',
                        'status': 'active',
                        'region': self._determine_geological_region(lat, lon)
                    })
                    
                    for model_info in age_models[:3]:  # Use top 3 models
                        model_path = self.model_database.get_model(model_info['model_id'])
                        if model_path:
                            age_model = self._load_age_estimation_model(model_path)
                            if age_model:
                                # Feature extraction for ML model
                                features = self._extract_crustal_age_features(lat, lon)
                                if features is not None:
                                    age_prediction = age_model.predict([features])[0]
                                    age_estimates.append(age_prediction)
                                    confidence_scores.append(model_info.get('accuracy', 0.8))
                                    data_sources.append(f"ml_model_{model_info['model_id']}")
                except Exception as e:
                    self.logger.warning(f"ML age estimation failed: {e}")
            
            # 2. Advanced geological database integration
            if self.geological_data_pipeline:
                try:
                    # Query geological age databases
                    geological_age_data = self._query_geological_age_databases(lat, lon)
                    if geological_age_data:
                        for age_data in geological_age_data:
                            age_estimates.append(age_data['age'])
                            confidence_scores.append(age_data['confidence'])
                            data_sources.append(age_data['source'])
                except Exception as e:
                    self.logger.warning(f"Geological database age query failed: {e}")
            
            # 3. Enhanced Precambrian shield analysis with uncertainty
            enhanced_shield_age = self._enhanced_precambrian_shield_analysis(lat, lon)
            if enhanced_shield_age:
                age_estimates.append(enhanced_shield_age['age'])
                confidence_scores.append(enhanced_shield_age['confidence'])
                data_sources.append('enhanced_shield_analysis')
            
            # 4. Tectonic setting-based age estimation with geophysical constraints
            tectonic_age = self._advanced_tectonic_age_estimation(lat, lon)
            if tectonic_age:
                age_estimates.append(tectonic_age['age'])
                confidence_scores.append(tectonic_age['confidence'])
                data_sources.append('tectonic_geophysical')
            
            # Ensemble prediction with uncertainty quantification
            if age_estimates:
                # Weighted average based on confidence scores
                weights = np.array(confidence_scores)
                weights = weights / np.sum(weights)
                
                ensemble_age = np.average(age_estimates, weights=weights)
                ensemble_confidence = np.average(confidence_scores, weights=weights)
                
                # Calculate uncertainty metrics
                age_std = np.std(age_estimates)
                prediction_uncertainty = age_std / ensemble_age if ensemble_age > 0 else 1.0
                
                # Advanced confidence scoring considering agreement between methods
                method_agreement = 1.0 - (age_std / (ensemble_age + 1e-6))
                final_confidence = ensemble_confidence * max(0.1, method_agreement)
                
                return {
                    'crustal_age': max(0, ensemble_age),
                    'age_confidence': min(1.0, max(0.0, final_confidence)),
                    'age_uncertainty': prediction_uncertainty,
                    'age_std': age_std,
                    'num_sources': len(age_estimates),
                    'data_sources': data_sources,
                    'method': 'ensemble_ml_database',
                    'individual_estimates': list(zip(age_estimates, confidence_scores, data_sources))
                }
            
            # Fallback to enhanced non-shield estimation
            return self._estimate_non_shield_age(lat, lon)
            
        except Exception as e:
            self.logger.error(f"Advanced crustal age estimation failed: {e}")
            return {
                'crustal_age': 500, 
                'age_confidence': 0.3, 
                'age_uncertainty': 0.8,
                'data_source': 'fallback',
                'method': 'fallback_basic'
            }
    
    def _estimate_non_shield_age(self, lat: float, lon: float) -> Dict[str, Any]:
        """Advanced non-shield crustal age estimation with multi-source database integration"""
        try:
            # Initialize database integration for real-time geological data
            if not hasattr(self, 'geological_db_manager'):
                try:
                    from .database_integration import PostgreSQLGISManager, DatabaseConfig
                    db_config = DatabaseConfig(
                        host='localhost',
                        port=5432,
                        database='prometheus_geological_data',
                        user='prometheus',
                        connection_type='postgresql_gis'
                    )
                    self.geological_db_manager = PostgreSQLGISManager(db_config)
                except Exception:
                    self.geological_db_manager = None
            
            # Multi-source age estimation
            age_estimates = []
            confidence_scores = []
            crustal_type_votes = []
            data_sources = []
            
            # 1. Advanced oceanic crust analysis with bathymetry and magnetic data
            oceanic_analysis = self._advanced_oceanic_age_analysis(lat, lon)
            if oceanic_analysis:
                age_estimates.append(oceanic_analysis['age'])
                confidence_scores.append(oceanic_analysis['confidence'])
                crustal_type_votes.append('oceanic')
                data_sources.append('advanced_oceanic_analysis')
            
            # 2. Continental platform age estimation using geological databases
            if self.geological_db_manager:
                try:
                    # Query geological formations database
                    geological_formations = self._query_geological_formations(lat, lon)
                    if geological_formations:
                        for formation in geological_formations:
                            if formation['age_min'] and formation['age_max']:
                                avg_age = (formation['age_min'] + formation['age_max']) / 2
                                age_estimates.append(avg_age)
                                confidence_scores.append(formation['confidence'])
                                crustal_type_votes.append('continental')
                                data_sources.append(f"geological_formation_{formation['name']}")
                except Exception as e:
                    self.logger.warning(f"Geological formation query failed: {e}")
            
            # 3. Tectonic province analysis
            tectonic_province_age = self._analyze_tectonic_province_age(lat, lon)
            if tectonic_province_age:
                age_estimates.append(tectonic_province_age['age'])
                confidence_scores.append(tectonic_province_age['confidence'])
                crustal_type_votes.append(tectonic_province_age['crustal_type'])
                data_sources.append('tectonic_province_analysis')
            
            # 4. Orogenic belt analysis with structural age constraints
            orogenic_analysis = self._analyze_orogenic_age_constraints(lat, lon)
            if orogenic_analysis:
                age_estimates.append(orogenic_analysis['age'])
                confidence_scores.append(orogenic_analysis['confidence'])
                crustal_type_votes.append('continental')
                data_sources.append('orogenic_belt_analysis')
            
            # 5. Sedimentary basin analysis
            basin_analysis = self._analyze_sedimentary_basin_age(lat, lon)
            if basin_analysis:
                age_estimates.append(basin_analysis['basement_age'])
                confidence_scores.append(basin_analysis['confidence'])
                crustal_type_votes.append('continental')
                data_sources.append('sedimentary_basin_analysis')
            
            # Ensemble prediction with uncertainty quantification
            if age_estimates:
                # Weighted ensemble prediction
                weights = np.array(confidence_scores)
                weights = weights / np.sum(weights)
                
                ensemble_age = np.average(age_estimates, weights=weights)
                ensemble_confidence = np.average(confidence_scores, weights=weights)
                
                # Determine crustal type by majority vote
                crustal_type = max(set(crustal_type_votes), key=crustal_type_votes.count)
                
                # Calculate uncertainty metrics
                age_std = np.std(age_estimates)
                prediction_uncertainty = age_std / ensemble_age if ensemble_age > 0 else 1.0
                
                # Method agreement scoring
                method_agreement = 1.0 - (age_std / (ensemble_age + 1e-6))
                final_confidence = ensemble_confidence * max(0.2, method_agreement)
                
                return {
                    'crustal_age': max(0, ensemble_age),
                    'age_confidence': min(1.0, max(0.0, final_confidence)),
                    'age_uncertainty': prediction_uncertainty,
                    'age_std': age_std,
                    'crustal_type': crustal_type,
                    'num_sources': len(age_estimates),
                    'data_sources': data_sources,
                    'method': 'ensemble_database_integration',
                    'individual_estimates': list(zip(age_estimates, confidence_scores, crustal_type_votes, data_sources))
                }
            
            # Enhanced fallback with basic tectonic inference
            oceanic_check = self._is_oceanic_simple_check(lat, lon)
            if oceanic_check:
                # Enhanced oceanic age with spreading rate estimates
                spreading_rate = self._estimate_spreading_rate(lat, lon)
                oceanic_age = self._calculate_oceanic_age_from_spreading(lat, lon, spreading_rate)
                return {
                    'crustal_age': oceanic_age,
                    'age_confidence': 0.6,
                    'age_uncertainty': 0.4,
                    'crustal_type': 'oceanic',
                    'spreading_rate': spreading_rate,
                    'data_source': 'enhanced_oceanic_inference',
                    'method': 'spreading_rate_calculation'
                }
            else:
                # Enhanced continental age with geological constraints
                continental_age = self._estimate_continental_platform_age(lat, lon)
                return {
                    'crustal_age': continental_age['age'],
                    'age_confidence': continental_age['confidence'],
                    'age_uncertainty': continental_age['uncertainty'],
                    'crustal_type': 'continental',
                    'geological_setting': continental_age['setting'],
                    'data_source': 'enhanced_continental_inference',
                    'method': 'geological_constraint_analysis'
                }
                
        except Exception as e:
            self.logger.error(f"Advanced non-shield age estimation failed: {e}")
            # Basic fallback
            oceanic_check = self._is_oceanic_simple_check(lat, lon)
            return {
                'crustal_age': 100 if oceanic_check else 800,
                'age_confidence': 0.4,
                'age_uncertainty': 0.8,
                'crustal_type': 'oceanic' if oceanic_check else 'continental',
                'data_source': 'basic_fallback',
                'method': 'simple_tectonic_inference'
            }
    
    def _is_oceanic_simple_check(self, lat: float, lon: float) -> bool:
        """Advanced oceanic classification using bathymetry and multi-source data integration"""
        try:
            # Initialize data integration pipeline for bathymetry data
            if not hasattr(self, 'bathymetry_processor'):
                try:
                    from .data_integration_pipeline import DataLayer, GeophysicalProcessor
                    self.bathymetry_processor = DataLayer()
                    self.geophysical_processor = GeophysicalProcessor()
                except Exception:
                    self.bathymetry_processor = None
                    self.geophysical_processor = None
            
            # Multi-criteria oceanic classification
            oceanic_indicators = []
            confidence_scores = []
            
            # 1. Advanced bathymetry analysis
            if self.bathymetry_processor:
                try:
                    bathymetry_data = self.bathymetry_processor.get_bathymetry_data(lat, lon)
                    if bathymetry_data:
                        depth = bathymetry_data.get('depth', 0)
                        
                        # Oceanic depth thresholds with confidence scoring
                        if depth < -2000:  # Deep ocean
                            oceanic_indicators.append(True)
                            confidence_scores.append(0.95)
                        elif depth < -1000:  # Continental slope/rise
                            oceanic_indicators.append(True)
                            confidence_scores.append(0.75)
                        elif depth < -200:  # Continental shelf (transitional)
                            oceanic_indicators.append(False)
                            confidence_scores.append(0.60)
                        else:  # Shallow or land
                            oceanic_indicators.append(False)
                            confidence_scores.append(0.85)
                        
                        # Additional bathymetric features analysis
                        bathymetric_features = self._analyze_bathymetric_features(bathymetry_data, lat, lon)
                        if bathymetric_features:
                            oceanic_indicators.append(bathymetric_features['is_oceanic'])
                            confidence_scores.append(bathymetric_features['confidence'])
                except Exception as e:
                    self.logger.warning(f"Bathymetry analysis failed: {e}")
            
            # 2. Crustal type analysis using geophysical data
            if self.geophysical_processor:
                try:
                    crustal_analysis = self._analyze_crustal_type_geophysics(lat, lon)
                    if crustal_analysis:
                        oceanic_indicators.append(crustal_analysis['is_oceanic'])
                        confidence_scores.append(crustal_analysis['confidence'])
                except Exception as e:
                    self.logger.warning(f"Crustal geophysical analysis failed: {e}")
            
            # 3. Magnetic anomaly analysis (oceanic crust has distinctive patterns)
            magnetic_analysis = self._analyze_oceanic_magnetic_patterns(lat, lon)
            if magnetic_analysis:
                oceanic_indicators.append(magnetic_analysis['is_oceanic'])
                confidence_scores.append(magnetic_analysis['confidence'])
            
            # 4. Gravity anomaly analysis
            gravity_analysis = self._analyze_oceanic_gravity_signature(lat, lon)
            if gravity_analysis:
                oceanic_indicators.append(gravity_analysis['is_oceanic'])
                confidence_scores.append(gravity_analysis['confidence'])
            
            # 5. Sediment thickness analysis (oceanic crust typically has thinner sediments)
            sediment_analysis = self._analyze_sediment_thickness(lat, lon)
            if sediment_analysis:
                oceanic_indicators.append(sediment_analysis['is_oceanic'])
                confidence_scores.append(sediment_analysis['confidence'])
            
            # Ensemble classification with weighted voting
            if oceanic_indicators and confidence_scores:
                weights = np.array(confidence_scores)
                weights = weights / np.sum(weights)
                
                # Weighted average of oceanic indicators
                oceanic_votes = np.array([1 if indicator else 0 for indicator in oceanic_indicators])
                weighted_score = np.average(oceanic_votes, weights=weights)
                
                # Classification threshold with uncertainty consideration
                classification_threshold = 0.5
                is_oceanic = weighted_score >= classification_threshold
                
                # Store detailed results for future reference
                self._store_oceanic_classification_results(lat, lon, {
                    'is_oceanic': is_oceanic,
                    'confidence': np.average(confidence_scores, weights=weights),
                    'weighted_score': weighted_score,
                    'num_indicators': len(oceanic_indicators),
                    'method': 'advanced_multi_source'
                })
                
                return is_oceanic
            
            # Fallback to enhanced basic ocean basin check
            enhanced_oceanic = self._enhanced_basic_oceanic_check(lat, lon)
            return enhanced_oceanic
            
        except Exception as e:
            self.logger.error(f"Advanced oceanic classification failed: {e}")
            # Basic fallback
            return self._basic_ocean_basin_check(lat, lon)
    
    def _basic_ocean_basin_check(self, lat: float, lon: float) -> bool:
        """Enhanced basic ocean basin boundaries check"""
        # Expanded and refined ocean basin boundaries
        ocean_regions = [
            # Pacific Ocean (refined boundaries)
            (-65, 70, 130, -70),   # Main Pacific
            (-65, 70, -180, -130), # Western Pacific extension
            
            # Atlantic Ocean (refined boundaries)
            (-70, 85, -80, 20),    # Main Atlantic
            
            # Indian Ocean (refined boundaries)  
            (-65, 30, 20, 120),    # Main Indian Ocean
            
            # Arctic Ocean
            (65, 90, -180, 180),   # Arctic
            
            # Southern Ocean
            (-90, -60, -180, 180), # Southern Ocean
        ]
        
        for min_lat, max_lat, min_lon, max_lon in ocean_regions:
            if min_lat <= lat <= max_lat:
                if min_lon <= max_lon:  # Normal longitude range
                    if min_lon <= lon <= max_lon:
                        return True
                else:  # Longitude wraparound (Pacific)
                    if lon >= min_lon or lon <= max_lon:
                        return True
        return False
    
    def _estimate_crustal_thickness(self, lat: float, lon: float) -> float:
        """Advanced crustal thickness estimation using seismic tomography and gravity inversion"""
        try:
            # Initialize external data connectors for seismic and gravity data
            if not hasattr(self, 'seismic_data_connector'):
                try:
                    from .external_data_connectors import SeismicDataConnector, GravityDataConnector
                    self.seismic_data_connector = SeismicDataConnector()
                    self.gravity_data_connector = GravityDataConnector()
                except Exception:
                    self.seismic_data_connector = None
                    self.gravity_data_connector = None
            
            # Initialize geophysical processor for advanced analysis
            if not hasattr(self, 'geophysical_processor'):
                try:
                    from .data_integration_pipeline import GeophysicalProcessor
                    self.geophysical_processor = GeophysicalProcessor()
                except Exception:
                    self.geophysical_processor = None
            
            # Multi-method crustal thickness estimation
            thickness_estimates = []
            confidence_scores = []
            methods = []
            
            # 1. Seismic tomography-based thickness estimation
            if self.seismic_data_connector:
                try:
                    seismic_data = self.seismic_data_connector.get_seismic_tomography(lat, lon)
                    if seismic_data:
                        # P-wave velocity analysis for Moho detection
                        moho_depth = self._analyze_moho_from_pwave_velocity(seismic_data)
                        if moho_depth:
                            thickness_estimates.append(moho_depth)
                            confidence_scores.append(0.85)
                            methods.append('seismic_tomography')
                        
                        # S-wave velocity analysis
                        swave_thickness = self._analyze_moho_from_swave_velocity(seismic_data)
                        if swave_thickness:
                            thickness_estimates.append(swave_thickness)
                            confidence_scores.append(0.80)
                            methods.append('swave_analysis')
                except Exception as e:
                    self.logger.warning(f"Seismic tomography analysis failed: {e}")
            
            # 2. Receiver function analysis
            receiver_function_data = self._get_receiver_function_data(lat, lon)
            if receiver_function_data:
                try:
                    rf_moho_depth = self._analyze_receiver_functions(receiver_function_data)
                    if rf_moho_depth:
                        thickness_estimates.append(rf_moho_depth)
                        confidence_scores.append(0.90)
                        methods.append('receiver_functions')
                except Exception as e:
                    self.logger.warning(f"Receiver function analysis failed: {e}")
            
            # 3. Gravity inversion for crustal thickness
            if self.gravity_data_connector:
                try:
                    gravity_data = self.gravity_data_connector.get_gravity_field(lat, lon)
                    if gravity_data:
                        # Bouguer anomaly analysis
                        gravity_thickness = self._invert_gravity_for_crustal_thickness(gravity_data, lat, lon)
                        if gravity_thickness:
                            thickness_estimates.append(gravity_thickness)
                            confidence_scores.append(0.70)
                            methods.append('gravity_inversion')
                        
                        # Isostatic analysis
                        isostatic_thickness = self._analyze_isostatic_crustal_thickness(gravity_data, lat, lon)
                        if isostatic_thickness:
                            thickness_estimates.append(isostatic_thickness)
                            confidence_scores.append(0.65)
                            methods.append('isostatic_analysis')
                except Exception as e:
                    self.logger.warning(f"Gravity inversion failed: {e}")
            
            # 4. Ambient noise tomography
            if self.geophysical_processor:
                try:
                    ambient_noise_data = self.geophysical_processor.get_ambient_noise_tomography(lat, lon)
                    if ambient_noise_data:
                        noise_thickness = self._analyze_ambient_noise_moho(ambient_noise_data)
                        if noise_thickness:
                            thickness_estimates.append(noise_thickness)
                            confidence_scores.append(0.75)
                            methods.append('ambient_noise_tomography')
                except Exception as e:
                    self.logger.warning(f"Ambient noise tomography failed: {e}")
            
            # 5. Active source seismic data
            active_seismic_data = self._get_active_seismic_data(lat, lon)
            if active_seismic_data:
                try:
                    active_thickness = self._analyze_active_seismic_moho(active_seismic_data)
                    if active_thickness:
                        thickness_estimates.append(active_thickness)
                        confidence_scores.append(0.92)
                        methods.append('active_seismic')
                except Exception as e:
                    self.logger.warning(f"Active seismic analysis failed: {e}")
            
            # 6. Machine learning ensemble prediction
            ml_thickness = self._ml_crustal_thickness_prediction(lat, lon)
            if ml_thickness:
                thickness_estimates.append(ml_thickness['thickness'])
                confidence_scores.append(ml_thickness['confidence'])
                methods.append('ml_ensemble')
            
            # Ensemble prediction with uncertainty quantification
            if thickness_estimates:
                # Remove outliers using IQR method
                q1 = np.percentile(thickness_estimates, 25)
                q3 = np.percentile(thickness_estimates, 75)
                iqr = q3 - q1
                lower_bound = q1 - 1.5 * iqr
                upper_bound = q3 + 1.5 * iqr
                
                # Filter estimates within reasonable bounds
                filtered_estimates = []
                filtered_confidences = []
                filtered_methods = []
                
                for est, conf, method in zip(thickness_estimates, confidence_scores, methods):
                    if lower_bound <= est <= upper_bound:
                        filtered_estimates.append(est)
                        filtered_confidences.append(conf)
                        filtered_methods.append(method)
                
                if filtered_estimates:
                    # Weighted average
                    weights = np.array(filtered_confidences)
                    weights = weights / np.sum(weights)
                    
                    final_thickness = np.average(filtered_estimates, weights=weights)
                    thickness_std = np.std(filtered_estimates)
                    
                    # Store detailed results for analysis
                    self._store_crustal_thickness_analysis(lat, lon, {
                        'thickness': final_thickness,
                        'uncertainty': thickness_std,
                        'num_methods': len(filtered_estimates),
                        'methods': filtered_methods,
                        'individual_estimates': list(zip(filtered_estimates, filtered_confidences, filtered_methods))
                    })
                    
                    return max(5.0, min(80.0, final_thickness))  # Realistic bounds
            
            # Enhanced geological constraint fallback
            enhanced_thickness = self._enhanced_geological_thickness_estimate(lat, lon)
            return enhanced_thickness
            
        except Exception as e:
            self.logger.error(f"Advanced crustal thickness estimation failed: {e}")
            # Enhanced fallback with geological constraints
            return self._enhanced_geological_thickness_estimate(lat, lon)
    
    def _enhanced_geological_thickness_estimate(self, lat: float, lon: float) -> float:
        """Enhanced geological constraint-based thickness estimation"""
        try:
            # Geological province analysis
            geological_province = self._determine_geological_province(lat, lon)
            
            # Tectonic setting analysis
            tectonic_setting = self._analyze_tectonic_setting(lat, lon)
            
            # Base thickness estimation
            if self._is_oceanic_simple_check(lat, lon):
                # Oceanic crust thickness variations
                if tectonic_setting.get('spreading_rate', 'normal') == 'fast':
                    base_thickness = 6.0  # Fast spreading centers
                elif tectonic_setting.get('spreading_rate', 'normal') == 'slow':
                    base_thickness = 8.0  # Slow spreading centers
                else:
                    base_thickness = 7.0  # Normal oceanic crust
                
                # Volcanic additions
                volcanic_loading = self._estimate_volcanic_loading(lat, lon)
                final_thickness = base_thickness + volcanic_loading
                
            else:
                # Continental crust analysis
                shield_distance = self._calculate_shield_distance(lat, lon)
                
                if shield_distance < 5:  # Shield core
                    base_thickness = 45.0
                elif shield_distance < 15:  # Shield margin
                    base_thickness = 40.0
                elif geological_province in ['fold_belt', 'mountain_range']:
                    base_thickness = 50.0  # Thickened by orogeny
                elif geological_province == 'rift_valley':
                    base_thickness = 25.0  # Thinned by extension
                else:
                    base_thickness = 35.0  # Normal continental
                
                # Orogenic thickening or extensional thinning
                structural_modification = self._calculate_structural_thickness_modification(lat, lon)
                final_thickness = base_thickness * (1 + structural_modification)
            
            return max(5.0, min(80.0, final_thickness))
            
        except Exception:
            # Ultimate fallback
            if self._is_oceanic_simple_check(lat, lon):
                return 7.0
            else:
                return 35.0
    
    def _calculate_shield_distance(self, lat: float, lon: float) -> float:
        """Advanced shield distance calculation with real-time geological database integration"""
        try:
            # Initialize TimeScaleDB for real-time geological data
            if not hasattr(self, 'timescale_db_manager'):
                try:
                    from .database_integration import TimeScaleDBManager, DatabaseConfig
                    db_config = DatabaseConfig(
                        host='localhost',
                        port=5432,
                        database='prometheus_geological_timeseries',
                        user='prometheus',
                        connection_type='timescaledb'
                    )
                    self.timescale_db_manager = TimeScaleDBManager(db_config)
                except Exception:
                    self.timescale_db_manager = None
            
            # Initialize spatial database for shield boundaries
            if not hasattr(self, 'spatial_db_manager'):
                try:
                    from .database_integration import PostgreSQLGISManager, DatabaseConfig
                    spatial_config = DatabaseConfig(
                        host='localhost',
                        port=5432,
                        database='prometheus_spatial_geology',
                        user='prometheus',
                        connection_type='postgresql_gis'
                    )
                    self.spatial_db_manager = PostgreSQLGISManager(spatial_config)
                except Exception:
                    self.spatial_db_manager = None
            
            # Multi-source shield distance calculation
            shield_distances = []
            confidence_scores = []
            data_sources = []
            
            # 1. Real-time spatial database query for shield boundaries
            if self.spatial_db_manager:
                try:
                    shield_polygons = self._query_shield_boundaries_database(lat, lon)
                    if shield_polygons:
                        for shield_info in shield_polygons:
                            # Calculate precise distance to polygon boundary
                            boundary_distance = self._calculate_distance_to_polygon_boundary(
                                lat, lon, shield_info['geometry']
                            )
                            shield_distances.append(boundary_distance)
                            confidence_scores.append(shield_info['confidence'])
                            data_sources.append(f"spatial_db_{shield_info['name']}")
                except Exception as e:
                    self.logger.warning(f"Spatial database shield query failed: {e}")
            
            # 2. High-resolution digital geological maps integration
            geological_map_distance = self._query_geological_maps_for_shields(lat, lon)
            if geological_map_distance:
                shield_distances.append(geological_map_distance['distance'])
                confidence_scores.append(geological_map_distance['confidence'])
                data_sources.append('geological_maps')
            
            # 3. Geochronological database for age-constrained shield boundaries
            geochronology_distance = self._query_geochronological_shield_data(lat, lon)
            if geochronology_distance:
                shield_distances.append(geochronology_distance['distance'])
                confidence_scores.append(geochronology_distance['confidence'])
                data_sources.append('geochronology_database')
            
            # 4. Geophysical signature-based shield detection
            geophysical_shield_distance = self._analyze_geophysical_shield_signatures(lat, lon)
            if geophysical_shield_distance:
                shield_distances.append(geophysical_shield_distance['distance'])
                confidence_scores.append(geophysical_shield_distance['confidence'])
                data_sources.append('geophysical_signatures')
            
            # 5. Machine learning-based shield classification and distance
            ml_shield_analysis = self._ml_shield_distance_prediction(lat, lon)
            if ml_shield_analysis:
                shield_distances.append(ml_shield_analysis['distance'])
                confidence_scores.append(ml_shield_analysis['confidence'])
                data_sources.append('ml_classification')
            
            # Ensemble distance calculation with uncertainty quantification
            if shield_distances:
                # Remove extreme outliers
                q1 = np.percentile(shield_distances, 25)
                q3 = np.percentile(shield_distances, 75)
                iqr = q3 - q1
                lower_bound = max(0, q1 - 1.5 * iqr)
                upper_bound = q3 + 1.5 * iqr
                
                # Filter distances within reasonable bounds
                filtered_distances = []
                filtered_confidences = []
                filtered_sources = []
                
                for dist, conf, source in zip(shield_distances, confidence_scores, data_sources):
                    if lower_bound <= dist <= upper_bound:
                        filtered_distances.append(dist)
                        filtered_confidences.append(conf)
                        filtered_sources.append(source)
                
                if filtered_distances:
                    # Confidence-weighted average
                    weights = np.array(filtered_confidences)
                    weights = weights / np.sum(weights)
                    
                    ensemble_distance = np.average(filtered_distances, weights=weights)
                    distance_std = np.std(filtered_distances)
                    
                    # Store analysis results for future reference
                    self._store_shield_distance_analysis(lat, lon, {
                        'distance': ensemble_distance,
                        'uncertainty': distance_std,
                        'num_sources': len(filtered_distances),
                        'data_sources': filtered_sources,
                        'individual_estimates': list(zip(filtered_distances, filtered_confidences, filtered_sources))
                    })
                    
                    return max(0.0, ensemble_distance)
            
            # Enhanced fallback with improved shield definitions
            enhanced_distance = self._enhanced_shield_distance_calculation(lat, lon)
            return enhanced_distance
            
        except Exception as e:
            self.logger.error(f"Advanced shield distance calculation failed: {e}")
            return self._enhanced_shield_distance_calculation(lat, lon)
    
