    def _determine_geological_region(self, lat: float, lon: float) -> str:
        """Determine optimal geological region for model selection"""
        try:
            # Major geological regions for model specificity
            if -90 <= lat <= -60:
                return 'antarctic'
            elif -60 <= lat <= -30:
                if -60 <= lon <= 20:
                    return 'south_atlantic'
                elif 120 <= lon <= 180 or -180 <= lon <= -120:
                    return 'south_pacific'
                else:
                    return 'indian_ocean'
            elif -30 <= lat <= 30:
                if -20 <= lon <= 50:
                    return 'africa'
                elif 50 <= lon <= 150:
                    return 'asia_oceania'
                elif -120 <= lon <= -30:
                    return 'south_america'
                else:
                    return 'pacific'
            elif 30 <= lat <= 60:
                if -30 <= lon <= 60:
                    return 'europe_africa'
                elif 60 <= lon <= 150:
                    return 'asia'
                elif -150 <= lon <= -60:
                    return 'north_america'
                else:
                    return 'north_pacific'
            else:  # Arctic
                return 'arctic'
                
        except Exception:
            return 'global'
    
    def _determine_geological_province(self, lat: float, lon: float) -> str:
        """Advanced geological province determination"""
        try:
            shield_distance = self._calculate_shield_distance(lat, lon)
            
            if shield_distance < 5:
                return 'shield'
            elif self._is_oceanic_simple_check(lat, lon):
                return 'oceanic'
            else:
                # Use topographic and geological indicators
                elevation = self._get_elevation_estimate(lat, lon)
                
                if elevation > 2000:
                    return 'mountain_range'
                elif elevation < -1000:
                    return 'rift_valley'
                elif 500 <= elevation <= 2000:
                    return 'fold_belt'
                else:
                    return 'continental_platform'
                    
        except Exception:
            return 'continental_platform'
    
