    def _analyze_multiscale_surface_complexity(self, geological_data: Dict) -> Dict:
        """Multi-scale surface complexity analysis"""
        try:
            complexity = {
                'micro_scale_roughness': 0.2,  # < 1m
                'meso_scale_roughness': 0.3,   # 1-100m 
                'macro_scale_roughness': 0.4   # > 100m
            }
            
            if 'surface_measurements' in geological_data:
                surface_data = geological_data['surface_measurements']
                complexity['micro_scale_roughness'] = surface_data.get('micro_roughness', 0.2)
                complexity['meso_scale_roughness'] = surface_data.get('meso_roughness', 0.3)
                complexity['macro_scale_roughness'] = surface_data.get('macro_roughness', 0.4)
                
            return complexity
        except Exception:
            return {'micro_scale_roughness': 0.2, 'meso_scale_roughness': 0.3, 'macro_scale_roughness': 0.4}
    
    def _model_geological_unit_roughness(self, geological_data: Dict) -> float:
        """Model roughness based on geological units with ML enhancement"""
        try:
            units = geological_data.get('geological_units', [])
            if not units:
                return 0.4
            
            # Advanced unit-based roughness calculation
            unit_roughness_map = {
                'basalt': 0.6, 'andesite': 0.55, 'rhyolite': 0.5,
                'granite': 0.45, 'gneiss': 0.65, 'schist': 0.7,
                'sandstone': 0.3, 'limestone': 0.25, 'shale': 0.35,
                'conglomerate': 0.5, 'quartzite': 0.4
            }
            
            total_roughness = 0
            for unit in units:
                unit_str = str(unit).lower()
                for rock_type, roughness in unit_roughness_map.items():
                    if rock_type in unit_str:
                        # Apply ML correction if model manager is available
                        if hasattr(self, 'model_manager') and self.model_manager:
                            roughness = self._apply_ml_unit_roughness_correction(rock_type, roughness)
                        total_roughness += roughness
                        break
                else:
                    total_roughness += 0.4  # Default
                    
            return total_roughness / max(len(units), 1)
            
        except Exception:
            return 0.4
    
    def _apply_ml_unit_roughness_correction(self, rock_type: str, base_roughness: float) -> float:
        """Apply ML correction to unit-based roughness"""
        try:
            # Use model manager for enhanced roughness prediction
            feature_vector = self._encode_rock_type_features(rock_type)
            if hasattr(self.model_manager, 'predict_roughness_correction'):
                correction = self.model_manager.predict_roughness_correction(feature_vector)
                return max(0.1, min(base_roughness * correction, 1.0))
            return base_roughness
        except Exception:
            return base_roughness
    
    def _encode_rock_type_features(self, rock_type: str) -> np.ndarray:
        """Encode rock type as feature vector for ML models"""
        try:
            # Advanced rock type encoding
            feature_map = {
                'igneous': [1, 0, 0, 0.8, 0.6],      # igneous, texture, hardness, weathering
                'sedimentary': [0, 1, 0, 0.4, 0.8],   # sedimentary
                'metamorphic': [0, 0, 1, 0.9, 0.3],   # metamorphic
                'volcanic': [1, 0, 0, 0.7, 0.5],      # volcanic
                'plutonic': [1, 0, 0, 0.9, 0.4]       # plutonic
            }
            
            for key, vector in feature_map.items():
                if key in rock_type.lower():
                    return np.array(vector, dtype=np.float32)
            
            return np.array([0.33, 0.33, 0.33, 0.5, 0.5], dtype=np.float32)  # Default
        except Exception:
            return np.array([0.5, 0.5, 0.5, 0.5, 0.5], dtype=np.float32)
    
