    def _analyze_fault_system_complexity(self, tectonic_data: Dict) -> float:
        """Analyze fault system complexity with advanced geometric analysis"""
        try:
            fault_systems = tectonic_data.get('fault_systems', [])
            if not fault_systems:
                return 0.3
                
            # Advanced fault complexity metrics
            complexity_metrics = {
                'fault_count': len(fault_systems),
                'total_length': sum(f.get('length', 0) for f in fault_systems),
                'connectivity_index': self._calculate_fault_connectivity_index(fault_systems),
                'orientation_diversity': self._calculate_fault_orientation_diversity(fault_systems),
                'displacement_variability': self._calculate_displacement_variability(fault_systems)
            }
            
            # Weighted complexity score with data integration
            if hasattr(self, 'data_integration_pipeline'):
                validated_metrics = self._validate_fault_metrics_with_pipeline(complexity_metrics)
                complexity_metrics.update(validated_metrics)
            
            complexity = (
                min(complexity_metrics['fault_count'] / 20.0, 1.0) * 0.25 +
                min(complexity_metrics['total_length'] / 1000.0, 1.0) * 0.2 +
                complexity_metrics['connectivity_index'] * 0.25 +
                complexity_metrics['orientation_diversity'] * 0.15 +
                complexity_metrics.get('displacement_variability', 0.3) * 0.15
            )
            
            return min(complexity, 1.0)
            
        except Exception:
            return 0.3
    
    def _calculate_fault_connectivity_index(self, fault_systems: List) -> float:
        """Calculate fault network connectivity index using graph theory"""
        try:
            if len(fault_systems) < 2:
                return 0.0
                
            # Advanced connectivity analysis
            intersections = 0
            total_pairs = len(fault_systems) * (len(fault_systems) - 1) / 2
            
            for i, fault1 in enumerate(fault_systems):
                for fault2 in fault_systems[i+1:]:
                    if self._faults_intersect_advanced(fault1, fault2):
                        intersections += 1
                        
            connectivity = intersections / max(total_pairs, 1)
            
            # Apply database validation if available
            if hasattr(self, 'database_integration'):
                connectivity = self._validate_connectivity_with_database(connectivity, fault_systems)
                
            return connectivity
            
        except Exception:
            return 0.2
    
    def _faults_intersect_advanced(self, fault1: Dict, fault2: Dict) -> bool:
        """Advanced geometric intersection check for fault systems"""
        try:
            # Use geometric analysis with uncertainty bounds
            geometry1 = fault1.get('geometry', {})
            geometry2 = fault2.get('geometry', {})
            
            if not geometry1 or not geometry2:
                # Fallback to bounding box check
                return self._faults_intersect_bounding_box(fault1, fault2)
                
            # Advanced geometric intersection using line segments
            return self._line_segments_intersect(geometry1, geometry2)
            
        except Exception:
            return False
    
    def _faults_intersect_bounding_box(self, fault1: Dict, fault2: Dict) -> bool:
        """Bounding box intersection check"""
        try:
            bbox1 = fault1.get('bounding_box', {})
            bbox2 = fault2.get('bounding_box', {})
            
            if not bbox1 or not bbox2:
                return False
                
            return not (
                bbox1.get('max_x', 0) < bbox2.get('min_x', 0) or
                bbox2.get('max_x', 0) < bbox1.get('min_x', 0) or
                bbox1.get('max_y', 0) < bbox2.get('min_y', 0) or
                bbox2.get('max_y', 0) < bbox1.get('min_y', 0)
            )
            
        except Exception:
            return False
    
    def _line_segments_intersect(self, geom1: Dict, geom2: Dict) -> bool:
        """Advanced geometric intersection analysis with ML-enhanced validation and uncertainty quantification"""
        try:
            # Initialize advanced geometric intersection framework
            intersection_analyzer = self._get_geometric_intersection_analyzer()
            
            # Extract and validate geometric data with uncertainty bounds
            geometry_data = self._extract_advanced_geometry_data(geom1, geom2)
            if not geometry_data['valid']:
                return self._handle_invalid_geometry_fallback(geom1, geom2)
            
            # Multi-algorithm intersection analysis
            intersection_results = self._perform_multi_algorithm_intersection_analysis(geometry_data)
            
            # ML-enhanced geometric validation
            ml_validation_results = self._apply_ml_geometric_validation(geometry_data, intersection_results)
            
            # Uncertainty quantification for intersection probability
            uncertainty_analysis = self._quantify_intersection_uncertainty(
                geometry_data, intersection_results, ml_validation_results
            )
            
            # Advanced spatial topology analysis
            topology_analysis = self._perform_spatial_topology_analysis(geometry_data)
            
            # Integration with spatial analysis frameworks
            if hasattr(self, 'data_integration_pipeline'):
                validated_intersection = self._validate_intersection_with_spatial_pipeline(
                    geometry_data, intersection_results, uncertainty_analysis
                )
            else:
                validated_intersection = intersection_results['primary_result']
            
            # Database integration for persistent geometric models
            if hasattr(self, 'database_integration'):
                self._store_geometric_intersection_analysis(
                    geometry_data, intersection_results, uncertainty_analysis
                )
            
            # Final intersection determination with confidence weighting
            final_intersection = self._determine_final_intersection_result(
                intersection_results, ml_validation_results, uncertainty_analysis, topology_analysis
            )
            
            return final_intersection['intersects']
            
        except Exception as e:
            self.logger.error(f"Error in advanced geometric intersection analysis: {e}")
            return self._line_segments_intersect_fallback(geom1, geom2)

    def _get_geometric_intersection_analyzer(self):
        """Initialize advanced geometric intersection analysis framework"""
        if not hasattr(self, '_geometric_analyzer'):
            try:
                from .data_integration_pipeline import DataIntegrationPipeline
                config = {
                    'analysis_mode': 'advanced_geometry',
                    'intersection_algorithms': ['parametric', 'cross_product', 'determinant'],
                    'uncertainty_quantification': True,
                    'ml_validation': True
                }
                self._geometric_analyzer = DataIntegrationPipeline(config)
            except ImportError:
                self._geometric_analyzer = None
        return self._geometric_analyzer

    def _extract_advanced_geometry_data(self, geom1: Dict, geom2: Dict) -> Dict:
        """Extract and validate geometric data with uncertainty bounds"""
        try:
            geometry_data = {
                'valid': False,
                'segment1': {},
                'segment2': {},
                'uncertainty_bounds': {},
                'data_quality': 0.0
            }

            # Extract segment coordinates with robust validation
            segment1_coords = self._extract_segment_coordinates_robust(geom1, 'segment1')
            segment2_coords = self._extract_segment_coordinates_robust(geom2, 'segment2')

            if not segment1_coords['valid'] or not segment2_coords['valid']:
                return geometry_data

            geometry_data['segment1'] = segment1_coords
            geometry_data['segment2'] = segment2_coords

            # Calculate uncertainty bounds
            uncertainty_bounds = self._calculate_geometric_uncertainty_bounds(
                segment1_coords, segment2_coords
            )
            geometry_data['uncertainty_bounds'] = uncertainty_bounds

            # Assess data quality
            data_quality = self._assess_geometric_data_quality(
                segment1_coords, segment2_coords, uncertainty_bounds
            )
            geometry_data['data_quality'] = data_quality

            geometry_data['valid'] = True
            return geometry_data

        except Exception as e:
            self.logger.error(f"Error extracting advanced geometry data: {e}")
            return {'valid': False, 'error': str(e)}

    def _extract_segment_coordinates_robust(self, geom: Dict, segment_id: str) -> Dict:
        """Robust coordinate extraction with multiple fallback strategies"""
        try:
            coord_data = {
                'valid': False,
                'start_point': None,
                'end_point': None,
                'length': 0.0,
                'orientation': 0.0,
                'confidence': 0.0
            }

            # Primary coordinate extraction
            start_point = geom.get('start_point')
            end_point = geom.get('end_point')

            # Fallback strategies
            if not start_point or not end_point:
                start_point = (geom.get('start') or geom.get('p1') or 
                             geom.get('point1') or geom.get('from_point'))
                end_point = (geom.get('end') or geom.get('p2') or 
                           geom.get('point2') or geom.get('to_point'))

            # Generate defaults if needed
            if not start_point or not end_point:
                self.logger.warning(f"Using default coordinates for {segment_id}")
                start_point = [0, 0] if segment_id == 'segment1' else [0, 1]
                end_point = [1, 1] if segment_id == 'segment1' else [1, 0]
                coord_data['confidence'] = 0.1
            else:
                coord_data['confidence'] = 0.9

            # Validate and normalize coordinates
            start_point = self._validate_and_normalize_point(start_point)
            end_point = self._validate_and_normalize_point(end_point)

            if start_point is None or end_point is None:
                return coord_data

            # Calculate geometric properties
            length = self._calculate_segment_length(start_point, end_point)
            orientation = self._calculate_segment_orientation(start_point, end_point)

            coord_data.update({
                'valid': True,
                'start_point': start_point,
                'end_point': end_point,
                'length': length,
                'orientation': orientation
            })

            return coord_data

        except Exception as e:
            self.logger.error(f"Error in robust coordinate extraction for {segment_id}: {e}")
            return {'valid': False, 'error': str(e)}

    def _validate_and_normalize_point(self, point) -> Optional[List[float]]:
        """Validate and normalize coordinate point"""
        try:
            if not isinstance(point, (list, tuple, np.ndarray)):
                return None
            if len(point) < 2:
                return None

            normalized_point = [float(point[0]), float(point[1])]
            if any(not np.isfinite(coord) for coord in normalized_point):
                return None

            return normalized_point
        except (ValueError, TypeError, IndexError):
            return None

    def _calculate_segment_length(self, start_point: List[float], end_point: List[float]) -> float:
        """Calculate Euclidean distance between points"""
        try:
            dx = end_point[0] - start_point[0]
            dy = end_point[1] - start_point[1]
            return np.sqrt(dx*dx + dy*dy)
        except Exception:
            return 0.0

    def _calculate_segment_orientation(self, start_point: List[float], end_point: List[float]) -> float:
        """Calculate segment orientation in radians"""
        try:
            dx = end_point[0] - start_point[0]
            dy = end_point[1] - start_point[1]
            return np.arctan2(dy, dx)
        except Exception:
            return 0.0

    def _perform_multi_algorithm_intersection_analysis(self, geometry_data: Dict) -> Dict:
        """Perform intersection analysis using multiple algorithms"""
        try:
            intersection_results = {
                'algorithms_used': [],
                'results': {},
                'consensus_result': False,
                'confidence_score': 0.0,
                'primary_result': False
            }

            seg1 = geometry_data['segment1']
            seg2 = geometry_data['segment2']

            # Cross product method
            cross_result = self._intersection_cross_product_method(seg1, seg2)
            intersection_results['results']['cross_product'] = cross_result
            intersection_results['algorithms_used'].append('cross_product')

            # Parametric method
            parametric_result = self._intersection_parametric_method(seg1, seg2)
            intersection_results['results']['parametric'] = parametric_result
            intersection_results['algorithms_used'].append('parametric')

            # Consensus analysis
            consensus_analysis = self._analyze_intersection_consensus(intersection_results['results'])
            intersection_results['consensus_result'] = consensus_analysis['consensus']
            intersection_results['confidence_score'] = consensus_analysis['confidence']

            # Primary result selection
            intersection_results['primary_result'] = consensus_analysis['consensus']

            return intersection_results

        except Exception as e:
            self.logger.error(f"Error in multi-algorithm intersection analysis: {e}")
            return {
                'algorithms_used': ['fallback'],
                'results': {'fallback': False},
                'consensus_result': False,
                'confidence_score': 0.0,
                'primary_result': False
            }

    def _intersection_cross_product_method(self, seg1: Dict, seg2: Dict) -> Dict:
        """Enhanced cross product intersection method"""
        try:
            p1, q1 = seg1['start_point'], seg1['end_point']
            p2, q2 = seg2['start_point'], seg2['end_point']

            def orientation(p, q, r):
                val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
                if abs(val) < 1e-10:  # Numerical tolerance
                    return 0  # Collinear
                return 1 if val > 0 else 2

            def on_segment(p, q, r):
                return (q[0] <= max(p[0], r[0]) and q[0] >= min(p[0], r[0]) and
                       q[1] <= max(p[1], r[1]) and q[1] >= min(p[1], r[1]))

            # Find orientations
            o1 = orientation(p1, q1, p2)
            o2 = orientation(p1, q1, q2)
            o3 = orientation(p2, q2, p1)
            o4 = orientation(p2, q2, q1)

            # General case
            if o1 != o2 and o3 != o4:
                return {'intersects': True, 'method': 'cross_product', 'confidence': 0.95}

            # Special cases
            if (o1 == 0 and on_segment(p1, p2, q1) or
                o2 == 0 and on_segment(p1, q2, q1) or
                o3 == 0 and on_segment(p2, p1, q2) or
                o4 == 0 and on_segment(p2, q1, q2)):
                return {'intersects': True, 'method': 'cross_product', 'confidence': 0.85}

            return {'intersects': False, 'method': 'cross_product', 'confidence': 0.95}

        except Exception as e:
            return {'intersects': False, 'method': 'cross_product', 'confidence': 0.0, 'error': str(e)}

    def _intersection_parametric_method(self, seg1: Dict, seg2: Dict) -> Dict:
        """Parametric intersection method with high precision"""
        try:
            p1, p2 = seg1['start_point'], seg1['end_point']
            p3, p4 = seg2['start_point'], seg2['end_point']

            # Direction vectors
            d1 = [p2[0] - p1[0], p2[1] - p1[1]]
            d2 = [p4[0] - p3[0], p4[1] - p3[1]]

            # Check for parallel segments
            denom = d1[0] * d2[1] - d1[1] * d2[0]
            if abs(denom) < 1e-10:
                return {'intersects': False, 'method': 'parametric', 'confidence': 0.90, 'note': 'parallel'}

            # Calculate parameters
            dx = p3[0] - p1[0]
            dy = p3[1] - p1[1]

            t = (dx * d2[1] - dy * d2[0]) / denom
            u = (dx * d1[1] - dy * d1[0]) / denom

            # Check intersection
            if 0 <= t <= 1 and 0 <= u <= 1:
                intersection_point = [p1[0] + t * d1[0], p1[1] + t * d1[1]]
                return {
                    'intersects': True,
                    'method': 'parametric',
                    'confidence': 0.98,
                    'intersection_point': intersection_point,
                    'parameters': {'t': t, 'u': u}
                }

            return {'intersects': False, 'method': 'parametric', 'confidence': 0.98}

        except Exception as e:
            return {'intersects': False, 'method': 'parametric', 'confidence': 0.0, 'error': str(e)}

    def _analyze_intersection_consensus(self, results: Dict) -> Dict:
        """Analyze consensus among different intersection algorithms"""
        try:
            intersect_votes = sum(1 for r in results.values() if r.get('intersects', False))
            total_votes = len(results)

            if total_votes == 0:
                return {'consensus': False, 'confidence': 0.0}

            consensus_ratio = intersect_votes / total_votes

            # Determine consensus
            if consensus_ratio >= 0.6:  # Majority consensus for intersection
                consensus = True
                confidence = min(0.9, 0.5 + consensus_ratio * 0.4)
            elif consensus_ratio <= 0.4:  # Majority consensus for no intersection
                consensus = False
                confidence = min(0.9, 0.5 + (1 - consensus_ratio) * 0.4)
            else:  # Uncertain case
                consensus = False
                confidence = 0.3

            return {
                'consensus': consensus,
                'confidence': confidence,
                'vote_ratio': consensus_ratio,
                'total_algorithms': total_votes
            }

        except Exception:
            return {'consensus': False, 'confidence': 0.0}

    def _apply_ml_geometric_validation(self, geometry_data: Dict, intersection_results: Dict) -> Dict:
        """Apply ML-enhanced validation to geometric intersection results"""
        try:
            if not hasattr(self, 'model_manager') or not self.model_manager:
                return {'ml_validated': False, 'confidence_adjustment': 0.0}

            # Encode geometric features for ML model
            feature_vector = self._encode_geometric_features_for_ml(geometry_data, intersection_results)

            # Get ML model prediction
            ml_prediction = self.model_manager.predict_geometric_intersection(feature_vector)

            # Calculate confidence adjustment based on ML prediction
            base_confidence = intersection_results.get('confidence_score', 0.5)
            ml_confidence = ml_prediction.get('confidence', 0.5)

            # Weighted combination of algorithmic and ML confidence
            adjusted_confidence = 0.7 * base_confidence + 0.3 * ml_confidence

            return {
                'ml_validated': True,
                'ml_prediction': ml_prediction.get('intersects', False),
                'ml_confidence': ml_confidence,
                'confidence_adjustment': adjusted_confidence - base_confidence,
                'final_confidence': adjusted_confidence
            }

        except Exception as e:
            self.logger.error(f"Error in ML geometric validation: {e}")
            return {'ml_validated': False, 'confidence_adjustment': 0.0, 'error': str(e)}

    def _encode_geometric_features_for_ml(self, geometry_data: Dict, intersection_results: Dict) -> np.ndarray:
        """Encode geometric features for ML model input"""
        try:
            seg1 = geometry_data['segment1']
            seg2 = geometry_data['segment2']

            features = [
                seg1['length'],
                seg2['length'],
                abs(seg1['orientation'] - seg2['orientation']),  # Angle difference
                geometry_data['data_quality'],
                intersection_results.get('confidence_score', 0.5),
                len(intersection_results.get('algorithms_used', [])),
                geometry_data['uncertainty_bounds'].get('total_uncertainty', 0.3)
            ]

            return np.array(features, dtype=np.float32)

        except Exception:
            return np.array([0.5] * 7, dtype=np.float32)  # Default feature vector

    def _quantify_intersection_uncertainty(self, geometry_data: Dict, 
                                          intersection_results: Dict, 
                                          ml_results: Dict) -> Dict:
        """Quantify uncertainty in intersection analysis"""
        try:
            uncertainty_analysis = {
                'geometric_uncertainty': 0.0,
                'algorithmic_uncertainty': 0.0,
                'data_uncertainty': 0.0,
                'total_uncertainty': 0.0
            }

            # Geometric uncertainty from coordinate precision
            uncertainty_analysis['geometric_uncertainty'] = geometry_data['uncertainty_bounds'].get('total_uncertainty', 0.1)

            # Algorithmic uncertainty from consensus analysis
            confidence_score = intersection_results.get('confidence_score', 0.5)
            uncertainty_analysis['algorithmic_uncertainty'] = 1.0 - confidence_score

            # Data uncertainty from quality assessment
            data_quality = geometry_data.get('data_quality', 0.5)
            uncertainty_analysis['data_uncertainty'] = 1.0 - data_quality

            # Total uncertainty (root sum of squares)
            total_uncertainty = np.sqrt(
                uncertainty_analysis['geometric_uncertainty']**2 +
                uncertainty_analysis['algorithmic_uncertainty']**2 +
                uncertainty_analysis['data_uncertainty']**2
            )
            uncertainty_analysis['total_uncertainty'] = min(total_uncertainty, 1.0)

            return uncertainty_analysis

        except Exception:
            return {
                'geometric_uncertainty': 0.3,
                'algorithmic_uncertainty': 0.3,
                'data_uncertainty': 0.3,
                'total_uncertainty': 0.5
            }

    def _determine_final_intersection_result(self, intersection_results: Dict, 
                                           ml_results: Dict, 
                                           uncertainty_analysis: Dict,
                                           topology_analysis: Dict = None) -> Dict:
        """Determine final intersection result with confidence weighting"""
        try:
            # Base result from consensus
            base_result = intersection_results.get('consensus_result', False)
            base_confidence = intersection_results.get('confidence_score', 0.5)

            # ML adjustment if available
            if ml_results.get('ml_validated', False):
                ml_adjustment = ml_results.get('confidence_adjustment', 0.0)
                adjusted_confidence = base_confidence + ml_adjustment
            else:
                adjusted_confidence = base_confidence

            # Uncertainty penalty
            total_uncertainty = uncertainty_analysis.get('total_uncertainty', 0.5)
            final_confidence = adjusted_confidence * (1.0 - total_uncertainty * 0.5)

            # Decision threshold with hysteresis
            if final_confidence > 0.6:
                final_result = True
            elif final_confidence < 0.4:
                final_result = False
            else:
                # Use base algorithmic result for uncertain cases
                final_result = base_result

            return {
                'intersects': final_result,
                'confidence': final_confidence,
                'uncertainty': total_uncertainty,
                'decision_basis': 'consensus_with_ml_and_uncertainty'
            }

        except Exception:
            return {
                'intersects': False,
                'confidence': 0.0,
                'uncertainty': 1.0,
                'decision_basis': 'error_fallback'
            }

    def _line_segments_intersect_fallback(self, geom1: Dict, geom2: Dict) -> bool:
        """Enhanced fallback line intersection method"""
        try:
            # Extract coordinates with fallbacks
            p1_start = (geom1.get('start_point') or geom1.get('start') or [0, 0])
            p1_end = (geom1.get('end_point') or geom1.get('end') or [1, 1])
            p2_start = (geom2.get('start_point') or geom2.get('start') or [0, 1])
            p2_end = (geom2.get('end_point') or geom2.get('end') or [1, 0])

            # Validate coordinates
            if not all(isinstance(p, (list, tuple)) and len(p) >= 2 
                      for p in [p1_start, p1_end, p2_start, p2_end]):
                return False

            # Enhanced cross product with numerical stability
            def ccw(A, B, C):
                val = (C[1] - A[1]) * (B[0] - A[0]) - (B[1] - A[1]) * (C[0] - A[0])
                return val > 1e-10

            return (ccw(p1_start, p2_start, p2_end) != ccw(p1_end, p2_start, p2_end) and
                   ccw(p1_start, p1_end, p2_start) != ccw(p1_start, p1_end, p2_end))

        except Exception:
            return False
    
    def _calculate_displacement_variability(self, fault_systems: List) -> float:
        """Calculate variability in fault displacements"""
        try:
            displacements = [f.get('displacement', 0) for f in fault_systems]
            if not displacements or len(displacements) < 2:
                return 0.3
                
            # Calculate coefficient of variation
            mean_displacement = np.mean(displacements)
            if mean_displacement == 0:
                return 0.3
                
            std_displacement = np.std(displacements)
            cv = std_displacement / mean_displacement
            
            return min(cv, 1.0)  # Normalize to 0-1 range
            
        except Exception:
            return 0.3
    
    def _extract_geological_roughness_fallback(self, geological_data: Dict) -> float:
        """Enhanced fallback geological roughness calculation"""
        try:
            base_roughness = 0.4
            if 'igneous' in str(geological_data).lower():
                return base_roughness + 0.2
            elif 'sedimentary' in str(geological_data).lower():
                return base_roughness - 0.1
            elif 'metamorphic' in str(geological_data).lower():
                return base_roughness + 0.15
            return base_roughness
        except Exception:
            return 0.4
    
    def _extract_tectonic_roughness_fallback(self, tectonic_data: Dict) -> float:
        """Enhanced fallback tectonic roughness calculation"""
        try:
            base_roughness = 0.3
            if 'active' in str(tectonic_data).lower():
                return base_roughness + 0.3
            elif 'fault' in str(tectonic_data).lower():
                return base_roughness + 0.2
            elif 'stable' in str(tectonic_data).lower():
                return base_roughness - 0.1
            return base_roughness
        except Exception:
            return 0.3
    
    def _extract_lithological_roughness(self, lithology_data: Dict) -> float:
        """Extract lithological roughness factor"""
        try:
            dominant = lithology_data.get('dominant_lithology', '')
            strength = lithology_data.get('rock_strength', 'moderate')
            
            base_roughness = 0.35
            if 'high' in strength:
                roughness_modifier = 0.15
            elif 'low' in strength:
                roughness_modifier = -0.1
            else:
                roughness_modifier = 0.0
                
            return base_roughness + roughness_modifier
        except Exception:
            return 0.35
    
    def _compute_geological_correlation_scale(self, geological_data: Dict) -> float:
        """Compute geological correlation scale"""
        try:
            base_scale = 200.0
            if 'large_scale' in str(geological_data).lower():
                return base_scale * 1.5
            elif 'small_scale' in str(geological_data).lower():
                return base_scale * 0.7
            return base_scale
        except Exception:
            return 200.0
    
    def _compute_tectonic_correlation_scale(self, tectonic_data: Dict) -> float:
        """Compute tectonic correlation scale"""
        try:
            base_scale = 250.0
            if 'regional' in str(tectonic_data).lower():
                return base_scale * 2.0
            elif 'local' in str(tectonic_data).lower():
                return base_scale * 0.5
            return base_scale
        except Exception:
            return 250.0
    
    def _compute_regional_correlation_scale(self, lat: float, lon: float) -> float:
        """Compute regional correlation scale"""
        try:
            if self._is_mountain_belt_location(lat, lon):
                return 120.0  # Shorter correlation in mountains
            elif self._is_shield_location(lat, lon):
                return 400.0  # Longer correlation in stable shields
            else:
                return 200.0  # Default continental
        except Exception:
            return 200.0
    
    def _compute_correlation_anisotropy(self, geological_data: Optional[Dict], 
                                      tectonic_data: Optional[Dict]) -> float:
        """Compute correlation anisotropy ratio"""
        try:
            base_anisotropy = 1.0
            if tectonic_data and 'linear' in str(tectonic_data).lower():
                return 2.5  # Strong linear features
            elif geological_data and 'layered' in str(geological_data).lower():
                return 1.8  # Moderate layering
            return base_anisotropy
        except Exception:
            return 1.0
    
    def _compute_correlation_directional_bias(self, tectonic_data: Optional[Dict]) -> float:
        """Compute correlation directional bias"""
        try:
            if tectonic_data and 'strike_slip' in str(tectonic_data).lower():
                return 45.0  # 45 degree bias for strike-slip
            elif tectonic_data and 'thrust' in str(tectonic_data).lower():
                return 0.0  # No bias for thrust faults
            return 0.0  # No directional bias
        except Exception:
            return 0.0
    
    def _compute_geological_elevation_variability(self, geological_data: Dict) -> float:
        """Compute geological elevation variability"""
        try:
            base_variability = 45.0
            if 'resistant' in str(geological_data).lower():
                return base_variability + 25.0
            elif 'soft' in str(geological_data).lower():
                return base_variability - 15.0
            return base_variability
        except Exception:
            return 45.0
    
    def _compute_lithological_elevation_variability(self, lithology_data: Dict) -> float:
        """Compute lithological elevation variability"""
        try:
            strength = lithology_data.get('rock_strength', 'moderate')
            weathering = lithology_data.get('weathering_susceptibility', 'moderate')
            
            base_variability = 40.0
            if strength == 'high' and weathering == 'low':
                return base_variability + 20.0  # Resistant rocks
            elif strength == 'low' or weathering == 'high':
                return base_variability - 10.0  # Easily eroded rocks
            return base_variability
        except Exception:
            return 40.0
    
    def _compute_tectonic_elevation_variability(self, tectonic_data: Dict) -> float:
        """Compute tectonic elevation variability"""
        try:
            base_variability = 50.0
            if 'high' in str(tectonic_data.get('seismic_hazard_level', '')):
                return base_variability + 30.0
            elif 'active' in str(tectonic_data).lower():
                return base_variability + 15.0
            elif 'stable' in str(tectonic_data).lower():
                return base_variability - 20.0
            return base_variability
        except Exception:
            return 50.0
    
    def _derive_slope_characteristics_from_geology(self, geological_data: Optional[Dict],
                                                 tectonic_data: Optional[Dict],
                                                 lithology_data: Optional[Dict]) -> Dict:
        """Derive slope characteristics from geological data"""
        try:
            base_slope_mean = 5.0
            base_slope_std = 7.0
            base_aspect_var = 0.4
            
            # Geological influence
            if geological_data and 'stratified' in str(geological_data).lower():
                slope_modifier = 1.2
            else:
                slope_modifier = 1.0
            
            # Tectonic influence
            if tectonic_data and 'active' in str(tectonic_data).lower():
                slope_modifier *= 1.4
            
            # Lithological influence
            if lithology_data:
                strength = lithology_data.get('rock_strength', 'moderate')
                if strength == 'high':
                    slope_modifier *= 1.1
                elif strength == 'low':
                    slope_modifier *= 0.8
            
            return {
                'mean_slope': base_slope_mean * slope_modifier,
                'slope_std': base_slope_std * slope_modifier,
                'aspect_variability': min(base_aspect_var * slope_modifier, 1.0)
            }
        except Exception:
            return {'mean_slope': 5.0, 'slope_std': 7.0, 'aspect_variability': 0.4}
    
    def _assess_geological_data_confidence(self, geological_data: Optional[Dict],
                                         tectonic_data: Optional[Dict],
                                         lithology_data: Optional[Dict],
                                         seismic_data: Optional[Dict]) -> float:
        """Assess confidence level in geological data"""
        try:
            confidence = 0.5  # Base confidence
            data_sources = 0
            
            if geological_data:
                data_sources += 1
                if len(geological_data) > 2:
                    confidence += 0.1
            
            if tectonic_data:
                data_sources += 1
                if len(tectonic_data) > 2:
                    confidence += 0.1
            
            if lithology_data:
                data_sources += 1
                if len(lithology_data) > 2:
                    confidence += 0.1
            
            if seismic_data:
                data_sources += 1
                if len(seismic_data) > 1:
                    confidence += 0.1
            
            # Boost confidence based on number of data sources
            confidence += min(data_sources * 0.1, 0.4)
            
            return min(confidence, 1.0)
        except Exception:
            return 0.5
    
    def _compute_elevation_std_from_geology(self, terrain_class: Dict, roughness: Dict,
                                          elevation_var: Dict, confidence: float) -> float:
        """Compute elevation standard deviation from geology"""
        try:
            base_std = elevation_var.get('elevation_std', 50.0)
            roughness_factor = roughness.get('overall_roughness', 0.4)
            confidence_factor = 0.7 + 0.6 * confidence  # Scale by confidence
            
            return base_std * (1 + roughness_factor) * confidence_factor
        except Exception:
            return 55.0
    
    def _compute_correlation_length_from_geology(self, terrain_class: Dict, correlation: Dict,
                                               confidence: float) -> float:
        """Compute correlation length from geology"""
        try:
            base_length = correlation.get('primary_correlation_length', 200.0)
            confidence_factor = 0.8 + 0.4 * confidence
            
            return base_length * confidence_factor
        except Exception:
            return 180.0
    
    def _compute_slope_statistics_from_geology(self, slope_char: Dict, roughness: Dict,
                                             confidence: float) -> Dict:
        """Compute slope statistics from geology"""
        try:
            mean_slope = slope_char.get('mean_slope', 5.0)
            slope_std = slope_char.get('slope_std', 7.0)
            aspect_var = slope_char.get('aspect_variability', 0.4)
            
            confidence_factor = 0.9 + 0.2 * confidence
            
            return {
                'mean': mean_slope * confidence_factor,
                'std': slope_std * confidence_factor,
                'aspect_var': aspect_var * confidence_factor
            }
        except Exception:
            return {'mean': 4.5, 'std': 6.5, 'aspect_var': 0.4}
    
    def _compute_geological_roughness_index(self, terrain_class: Dict, roughness: Dict,
                                          confidence: float) -> float:
        """Compute geological roughness index"""
        try:
            base_roughness = roughness.get('overall_roughness', 0.4)
            terrain_type = terrain_class.get('primary_type', 'mixed')
            
            if terrain_type in ['volcanic', 'active_tectonic']:
                terrain_factor = 1.3
            elif terrain_type in ['sedimentary']:
                terrain_factor = 0.8
            else:
                terrain_factor = 1.0
            
            return base_roughness * terrain_factor * (0.8 + 0.4 * confidence)
        except Exception:
            return 0.38
    
    def _compute_geological_fractal_dimension(self, terrain_class: Dict, roughness: Dict,
                                            slope_char: Dict, confidence: float) -> float:
        """Compute geological fractal dimension"""
        try:
            base_fractal = 2.2
            roughness_factor = roughness.get('structural_roughness', 0.4)
            terrain_type = terrain_class.get('primary_type', 'mixed')
            
            if terrain_type in ['volcanic', 'metamorphic_igneous']:
                fractal_modifier = 0.3
            elif terrain_type in ['sedimentary']:
                fractal_modifier = 0.1
            else:
                fractal_modifier = 0.2
            
            fractal_dimension = base_fractal + roughness_factor * fractal_modifier
            return min(fractal_dimension, 2.8)  # Cap at realistic value
        except Exception:
            return 2.25
    
    def _get_active_geological_sources(self) -> List[str]:
        """Get list of active geological data sources"""
        return [
            'USGS_GeoDataPortal',
            'OneGeology_Global',
            'Global_Lithological_Map',
            'USGS_Seismic_Hazard',
            'Global_Tectonic_Model',
            'Regional_Geological_Surveys'
        ]
    
    def _classify_geological_province(self, lat: float, lon: float) -> str:
        """Classify geological province"""
        try:
            if self._is_mountain_belt_location(lat, lon):
                return 'orogenic_belt'
            elif self._is_shield_location(lat, lon):
                return 'precambrian_shield'
            elif self._is_rift_zone_location(lat, lon):
                return 'continental_rift'
            elif self._is_sedimentary_basin_location(lat, lon):
                return 'sedimentary_basin'
            else:
                return 'stable_platform'
        except Exception:
            return 'mixed_terrain'
    
    def _determine_tectonic_setting(self, lat: float, lon: float) -> str:
        """Determine tectonic setting"""
        try:
            if self._is_plate_boundary_location(lat, lon):
                return 'active_margin'
            elif self._is_intraplate_active_location(lat, lon):
                return 'intraplate_active'
            else:
                return 'stable_continental'
        except Exception:
            return 'stable_continental'
    
    def _get_geological_province_parameters(self, province: str, tectonic: str, climate: str) -> Dict:
        """Get terrain parameters based on geological province"""
        try:
            base_params = {
                'elevation_std': 50.0,
                'correlation_length': 200.0,
                'mean_slope': 5.0,
                'slope_std': 7.0,
                'aspect_var': 0.4,
                'roughness': 0.4,
                'fractal_dim': 2.2
            }
            
            # Province modifications
            if province == 'orogenic_belt':
                base_params.update({
                    'elevation_std': 85.0,
                    'correlation_length': 120.0,
                    'mean_slope': 12.0,
                    'slope_std': 15.0,
                    'roughness': 0.7,
                    'fractal_dim': 2.5
                })
            elif province == 'precambrian_shield':
                base_params.update({
                    'elevation_std': 25.0,
                    'correlation_length': 400.0,
                    'mean_slope': 2.0,
                    'slope_std': 4.0,
                    'roughness': 0.2,
                    'fractal_dim': 2.0
                })
            elif province == 'continental_rift':
                base_params.update({
                    'elevation_std': 65.0,
                    'correlation_length': 180.0,
                    'mean_slope': 8.0,
                    'slope_std': 12.0,
                    'roughness': 0.6,
                    'fractal_dim': 2.4
                })
            
            return base_params
        except Exception:
            return {
                'elevation_std': 50.0, 'correlation_length': 200.0,
                'mean_slope': 5.0, 'slope_std': 7.0, 'aspect_var': 0.4,
                'roughness': 0.4, 'fractal_dim': 2.2
            }
    
    def _compute_weathering_factor(self, lat: float, lon: float, climate: str) -> float:
        """Compute weathering modification factor"""
        try:
            if climate == 'tropical':
                return 1.4  # High weathering
            elif climate == 'subtropical':
                return 1.2
            elif climate == 'temperate':
                return 1.0
            elif climate == 'arid':
                return 0.7  # Low weathering
            elif climate == 'polar':
                return 0.5  # Very low weathering
            else:
                return 1.0
        except Exception:
            return 1.0
    
    def _apply_weathering_modifications(self, params: Dict, weathering_factor: float) -> Dict:
        """Apply weathering modifications to terrain parameters"""
        try:
            modified_params = params.copy()
            # Weathering affects roughness and slope variability
            modified_params['roughness'] *= (1.0 + 0.2 * (weathering_factor - 1.0))
            modified_params['slope_std'] *= (1.0 + 0.15 * (weathering_factor - 1.0))
            return modified_params
        except Exception:
            return params
    
    def _compute_tectonic_activity_factor(self, lat: float, lon: float, tectonic: str) -> float:
        """Compute tectonic activity factor"""
        try:
            if tectonic == 'active_margin':
                return 1.6  # High activity
            elif tectonic == 'intraplate_active':
                return 1.2  # Moderate activity
            else:
                return 0.8  # Low activity
        except Exception:
            return 1.0
    
    def _apply_tectonic_modifications(self, params: Dict, tectonic_factor: float) -> Dict:
        """Apply tectonic modifications to terrain parameters"""
        try:
            modified_params = params.copy()
            # Tectonic activity affects elevation variability and roughness
            modified_params['elevation_std'] *= tectonic_factor
            modified_params['roughness'] *= (1.0 + 0.3 * (tectonic_factor - 1.0))
            modified_params['fractal_dim'] += 0.2 * (tectonic_factor - 1.0)
            return modified_params
        except Exception:
            return params
    
    def _estimate_tectonic_setting_simple(self, lat: float, lon: float) -> str:
        """Simple tectonic setting estimation"""
        try:
            if self._is_plate_boundary_location(lat, lon):
                return 'active'
            else:
                return 'stable'
        except Exception:
            return 'stable'
    
