    def _classify_north_american_province(self, lat: float, lon: float) -> str:
        """Classify North American geological province using USGS and GSC databases"""
        try:
            # Query USGS National Geologic Map Database
            usgs_data = self._query_usgs_geology_api(lat, lon)
            if usgs_data and 'province' in usgs_data:
                return usgs_data['province']
            
            # Query Geological Survey of Canada database
            gsc_data = self._query_gsc_geology_api(lat, lon)
            if gsc_data and 'geological_province' in gsc_data:
                return gsc_data['geological_province']
            
            # Query regional state geological surveys
            regional_data = self._query_regional_north_american_surveys(lat, lon)
            if regional_data and 'province' in regional_data:
                return regional_data['province']
            
            # Machine learning classification using trained model
            ml_result = self._classify_province_ml(lat, lon, 'north_america')
            if ml_result:
                return ml_result
                
        except Exception as e:
            logging.warning(f"Province classification failed: {e}")
        
        # Enhanced fallback with geological feature analysis
        return self._classify_province_from_geological_features(lat, lon, 'north_america')
    
    def _estimate_north_american_lithology(self, lat: float, lon: float) -> str:
        """Estimate North American lithology using comprehensive geological databases"""
        try:
            # Query USGS mineral resources database
            usgs_lithology = self._query_usgs_lithology_api(lat, lon)
            if usgs_lithology and 'primary_lithology' in usgs_lithology:
                return self._standardize_lithology_name(usgs_lithology['primary_lithology'])
            
            # Query North American bedrock geology database
            bedrock_data = self._query_north_american_bedrock_db(lat, lon)
            if bedrock_data and 'lithology' in bedrock_data:
                return self._standardize_lithology_name(bedrock_data['lithology'])
            
            # Query regional geological maps (1:250,000 scale)
            regional_map = self._query_regional_geological_maps(lat, lon)
            if regional_map and 'rock_type' in regional_map:
                return self._standardize_lithology_name(regional_map['rock_type'])
            
            # Geochemical analysis integration
            geochem_data = self._query_geochemical_databases(lat, lon)
            if geochem_data:
                return self._infer_lithology_from_geochemistry(geochem_data)
                
        except Exception as e:
            logging.warning(f"Lithology estimation failed: {e}")
        
        # Province-based lithology estimation with uncertainty
        province = self._classify_north_american_province(lat, lon)
        return self._estimate_lithology_from_province(province, lat, lon)
    
    def _analyze_north_american_tectonics(self, lat: float, lon: float) -> str:
        """Analyze North American tectonic history using comprehensive databases"""
        try:
            # Query USGS tectonic map database
            usgs_tectonics = self._query_usgs_tectonics_api(lat, lon)
            if usgs_tectonics and 'tectonic_setting' in usgs_tectonics:
                return usgs_tectonics['tectonic_setting']
            
            # Query North American crustal age database
            crustal_age_data = self._query_crustal_age_database(lat, lon)
            if crustal_age_data:
                return self._interpret_tectonic_history(crustal_age_data)
            
            # Query seismic hazard databases for active tectonics
            seismic_data = self._query_seismic_hazard_maps(lat, lon)
            if seismic_data:
                return self._analyze_active_tectonics(seismic_data)
            
            # Structural geology database integration
            structural_data = self._query_structural_geology_db(lat, lon)
            if structural_data:
                return self._interpret_structural_tectonics(structural_data)
                
        except Exception as e:
            logging.warning(f"Tectonic analysis failed: {e}")
        
        # Advanced tectonic interpretation using multiple datasets
        return self._comprehensive_tectonic_analysis(lat, lon, 'north_america')
    
