    def _query_regional_north_american_surveys(self, lat: float, lon: float) -> Optional[Dict]:
        """Query regional North American geological surveys concurrently"""
        try:
            from concurrent.futures import ThreadPoolExecutor, as_completed
            import requests
            
            survey_endpoints = [
                # US State Surveys
                ("california", "https://maps.conservation.ca.gov/cgs/services/geology/wfs"),
                ("texas", "https://tnris.org/services/geology/wfs"),
                ("alaska", "https://dggs.alaska.gov/services/geology/wfs"),
                # Canadian Provincial Surveys
                ("ontario", "https://www.geologyontario.mndm.gov.on.ca/services/wfs"),
                ("alberta", "https://ags.aer.ca/services/geology/wfs"),
                ("british_columbia", "https://catalogue.data.gov.bc.ca/services/geology/wfs")
            ]
            
            def query_single_survey(survey_info):
                survey_name, endpoint = survey_info
                try:
                    params = {
                        'service': 'WFS',
                        'version': '2.0.0',
                        'request': 'GetFeature',
                        'outputFormat': 'application/json',
                        'CQL_FILTER': f'INTERSECTS(geometry, POINT({lon} {lat}))',
                        'maxFeatures': 1
                    }
                    
                    response = requests.get(endpoint, params=params, timeout=8)
                    if response.status_code == 200:
                        data = response.json()
                        if data.get('features'):
                            feature = data['features'][0]
                            properties = feature.get('properties', {})
                            properties['survey_source'] = survey_name
                            return properties
                except Exception:
                    pass
                return None
            
            with ThreadPoolExecutor(max_workers=3) as executor:
                future_to_survey = {executor.submit(query_single_survey, survey): survey[0] for survey in survey_endpoints}
                
                for future in as_completed(future_to_survey, timeout=15):
                    result = future.result()
                    if result:
                        return {
                            'province': self._extract_geological_province(result),
                            'lithology': result.get('lithology', ''),
                            'formation': result.get('formation', ''),
                            'source': f"regional_survey_{result.get('survey_source', '')}"
                        }
                        
        except Exception as e:
            logging.warning(f"Regional surveys query failed: {e}")
            return None
    
    def _query_usgs_lithology_api(self, lat: float, lon: float) -> Optional[Dict]:
        """Query USGS mineral resources and lithology databases"""
        try:
            import requests
            
            # USGS Mineral Resources Database
            base_url = "https://mrdata.usgs.gov/services/mineral-resources"
            params = {
                'service': 'WFS',
                'version': '2.0.0', 
                'request': 'GetFeature',
                'typeName': 'mineral_resources:lithology',
                'outputFormat': 'application/json',
                'CQL_FILTER': f'DWITHIN(geometry, POINT({lon} {lat}), 1000, meters)',
                'maxFeatures': 5
            }
            
            response = requests.get(base_url, params=params, timeout=10)
            if response.status_code == 200:
                data = response.json()
                if data.get('features'):
                    # Aggregate lithology information from nearby features
                    lithologies = []
                    for feature in data['features']:
                        props = feature.get('properties', {})
                        if props.get('primary_lithology'):
                            lithologies.append(props['primary_lithology'])
                    
                    if lithologies:
                        # Find most common lithology
                        from collections import Counter
                        most_common = Counter(lithologies).most_common(1)[0][0]
                        
                        return {
                            'primary_lithology': most_common,
                            'lithology_confidence': len(lithologies),
                            'source': 'usgs_mineral_resources'
                        }
        except Exception as e:
            logging.warning(f"USGS lithology API query failed: {e}")
            return None
    
