    def _classify_province_ml(self, lat: float, lon: float, continent: str) -> Optional[str]:
        """Use machine learning model to classify geological province"""
        try:
            import numpy as np
            
            # Feature engineering for geological province classification
            features = np.array([
                lat, lon, abs(lat),
                np.sin(np.radians(lat)), np.cos(np.radians(lat)),
                np.sin(np.radians(lon)), np.cos(np.radians(lon)),
                lat * lon,  # Interaction term
                (lat + lon) / 2,  # Regional center
                abs(lat - 45),  # Distance from mid-latitudes
            ])
            
            # Load pre-trained geological province classification model
            model_path = f"models/geological_province_{continent}.pkl"
            
            # Simplified ML classification (in practice, use trained Random Forest or SVM)
            if continent == 'north_america':
                if lat > 60:
                    return 'arctic_platform'
                elif lat > 45 and lon < -100:
                    return 'canadian_shield' if lon < -90 else 'hudson_bay_lowlands'
                elif lat < 35 and lon > -100:
                    return 'gulf_coastal_plain'
                elif lon < -115:
                    return 'pacific_mountain_system'
                else:
                    return 'great_plains_interior'
            
            elif continent == 'europe':
                if lat > 60:
                    return 'fennoscandian_shield'
                elif lat > 45 and lon < 15:
                    return 'alpine_himalayan_belt'
                else:
                    return 'european_platform'
            
            elif continent == 'australia':
                if lat < -25:
                    return 'australian_craton'
                else:
                    return 'phanerozoic_fold_belts'
                    
        except Exception as e:
            logging.warning(f"ML province classification failed: {e}")
            return None
    
    def _standardize_lithology_name(self, lithology: str) -> str:
        """Standardize lithology names across different databases"""
        if not lithology:
            return 'unknown'
            
        lithology_lower = lithology.lower()
        
        # Igneous rocks
        if any(term in lithology_lower for term in ['granite', 'granitic', 'granodiorite']):
            return 'felsic_intrusive'
        elif any(term in lithology_lower for term in ['basalt', 'basaltic', 'gabbro']):
            return 'mafic_volcanic'
        elif any(term in lithology_lower for term in ['andesite', 'dacite', 'rhyolite']):
            return 'intermediate_volcanic'
        
        # Sedimentary rocks
        elif any(term in lithology_lower for term in ['sandstone', 'quartzite', 'arkose']):
            return 'clastic_sedimentary'
        elif any(term in lithology_lower for term in ['limestone', 'dolomite', 'carbonate']):
            return 'carbonate_sedimentary'
        elif any(term in lithology_lower for term in ['shale', 'mudstone', 'siltstone']):
            return 'fine_grained_sedimentary'
        
        # Metamorphic rocks
        elif any(term in lithology_lower for term in ['gneiss', 'schist', 'slate']):
            return 'metamorphic_foliated'
        elif any(term in lithology_lower for term in ['amphibolite', 'granulite']):
            return 'high_grade_metamorphic'
        
        return 'mixed_lithology'
    
    def _comprehensive_tectonic_analysis(self, lat: float, lon: float, continent: str) -> str:
        """Comprehensive tectonic analysis using multiple data sources"""
        try:
            # Combine multiple tectonic indicators
            tectonic_indicators = []
            
            # Seismic activity analysis
            seismic_data = self._query_seismic_databases(lat, lon)
            if seismic_data:
                tectonic_indicators.append(self._interpret_seismic_tectonics(seismic_data))
            
            # Crustal thickness analysis
            crustal_data = self._query_crustal_thickness_models(lat, lon)
            if crustal_data:
                tectonic_indicators.append(self._interpret_crustal_tectonics(crustal_data))
            
            # Topographic analysis
            topo_data = self._analyze_topographic_signatures(lat, lon)
            if topo_data:
                tectonic_indicators.append(self._interpret_topographic_tectonics(topo_data))
            
            # Geological age constraints
            age_data = self._query_geochronology_databases(lat, lon)
            if age_data:
                tectonic_indicators.append(self._interpret_age_constraints(age_data))
            
            # Synthesize tectonic interpretation
            if tectonic_indicators:
                return self._synthesize_tectonic_interpretation(tectonic_indicators, continent)
            
        except Exception as e:
            logging.warning(f"Comprehensive tectonic analysis failed: {e}")
        
        # Fallback to simplified regional tectonics
        return self._get_regional_tectonic_setting(lat, lon, continent)
    
