    def _estimate_source_location(self, beam_result: Dict) -> Optional[Dict]:
        """Estimate source location from beam parameters"""
        try:
            slowness = beam_result.get('best_slowness', 0.0)
            azimuth = beam_result.get('azimuth', 0.0)
            back_azimuth = beam_result.get('back_azimuth', azimuth)
            
            # Simple distance estimation from slowness
            if slowness > 0:
                distance_km = min(1000.0, slowness * 1000.0)
            else:
                distance_km = 100.0
            
            return {
                'distance_km': float(distance_km),
                'azimuth_deg': float(azimuth),
                'back_azimuth_deg': float(back_azimuth),
                'location_quality': 'estimated'
            }
        except Exception:
            return None
    
