    def _assess_detection_capability(self, location: Dict, beam_result: Dict) -> Dict:
        """Assess detection capability"""
        distance_km = location.get('distance_km', 100.0)
        coherence = beam_result.get('coherence', 0.5)
        
        if distance_km < 50 and coherence > 0.7:
            capability = 'excellent'
        elif distance_km < 200 and coherence > 0.5:
            capability = 'good'
        else:
            capability = 'moderate'
        
        return {
            'overall_capability': capability,
            'magnitude_threshold': 2.0 if capability == 'excellent' else 3.0,
            'location_accuracy_km': 2.0 if capability == 'excellent' else 5.0
        }
    
    def _analyze_network_geometry(self) -> Dict:
        """Analyze network geometry"""
        if hasattr(self, 'geometry') and hasattr(self.geometry, 'station_coords'):
            coords = self.geometry.station_coords
            n_stations = len(coords)
            
            if n_stations >= 4:
                geometry_quality = 'good'
                azimuthal_gap = 60.0
            elif n_stations >= 3:
                geometry_quality = 'fair'
                azimuthal_gap = 90.0
            else:
                geometry_quality = 'poor'
                azimuthal_gap = 180.0
        else:
            geometry_quality = 'unknown'
            azimuthal_gap = 120.0
            n_stations = 0
        
        return {
            'geometry_quality': geometry_quality,
            'azimuthal_gap': azimuthal_gap,
            'station_count': n_stations
        }
    
    def _assess_noise_conditions(self, beam_result: Dict) -> Dict:
        """Assess noise conditions"""
        signal_level = beam_result.get('power', 1.0)
        coherence = beam_result.get('coherence', 0.5)
        
        # Estimate SNR from power and coherence
        estimated_snr = signal_level * coherence * 10
        
        if estimated_snr > 20:
            noise_level = 'low'
        elif estimated_snr > 10:
            noise_level = 'moderate'
        else:
            noise_level = 'high'
        
        return {
            'noise_level': noise_level,
            'estimated_snr': estimated_snr,
            'coherence_based_quality': 'good' if coherence > 0.6 else 'poor'
        }
    
