    def _fetch_volcanic_data(self, latitude: float, longitude: float) -> Dict:
        """Fetch comprehensive volcanic data using real-time API integration"""
        try:
            # Initialize query parameters for comprehensive volcanic data
            query_params = {
                'location': {'latitude': latitude, 'longitude': longitude},
                'radius_km': 100,  # Search radius
                'data_types': ['seismic', 'thermal', 'gas_emissions', 'deformation'],
                'time_window': '30_days',
                'volcanic_systems': ['all'],
                'include_real_time': True,
                'quality_threshold': 0.7
            }
            
            # Use data integration pipeline for comprehensive volcanic data
            if hasattr(self, 'data_pipeline') and hasattr(self.data_pipeline, 'query_comprehensive_volcanic_data'):
                comprehensive_data = self.data_pipeline.query_comprehensive_volcanic_data(query_params)
                
                # Extract key metrics from comprehensive data
                volcanic_systems = comprehensive_data.get('volcanic_systems', {})
                quality_metrics = comprehensive_data.get('quality_metrics', {})
                
                # Determine activity level from multi-source data
                activity_level = self._assess_activity_from_comprehensive_data(volcanic_systems)
                alert_level = self._determine_alert_from_systems_data(volcanic_systems)
                
                # Get real-time enhancements if available
                real_time_data = {}
                if hasattr(self.data_pipeline, 'get_real_time_volcanic_data'):
                    base_features = np.array([latitude, longitude])
                    real_time_enhancement = self.data_pipeline.get_real_time_volcanic_data(base_features)
                    real_time_data = {
                        'thermal_anomalies': float(np.mean(real_time_enhancement)),
                        'enhancement_confidence': float(np.std(real_time_enhancement))
                    }
                
                return {
                    'volcanic_activity': activity_level,
                    'alert_level': alert_level,
                    'data_source': 'integrated_multi_source',
                    'systems_count': len(volcanic_systems),
                    'data_quality': quality_metrics.get('overall_quality', 0.0),
                    'temporal_coverage': quality_metrics.get('temporal_coverage', 0.0),
                    'real_time_data': real_time_data,
                    'source_systems': list(volcanic_systems.keys())[:5],  # Top 5 systems
                    'confidence_score': self._calculate_data_confidence(quality_metrics),
                    'last_updated': comprehensive_data.get('query_timestamp', 'unknown')
                }
            
            # Fallback to enhanced regional analysis
            return self._fetch_enhanced_regional_volcanic_data(latitude, longitude)
            
        except Exception as e:
            self.logger.warning(f"Advanced volcanic data fetch failed: {e}")
            return self._fetch_enhanced_regional_volcanic_data(latitude, longitude)
    
