    def _calculate_adaptive_ensemble_weights(self, predictions: Dict, uncertainties: Dict, 
                                           metadata: Dict, features: np.ndarray) -> Dict[str, float]:
        """Calculate adaptive weights based on model performance and context"""
        weights = {}
        total_weight = 0.0
        
        for model_name in predictions.keys():
            if predictions[model_name] is not None:
                # Base weight from model metadata (historical performance)
                base_weight = metadata[model_name].get('validation_score', 0.5)
                
                # Uncertainty-based adjustment (lower uncertainty = higher weight)
                uncertainty_factor = 1.0 / (1.0 + uncertainties[model_name])
                
                # Context-specific model expertise weighting
                expertise_weight = self._get_model_expertise_weight(
                    model_name, features
                )
                
                # Recent performance adjustment
                recent_performance = self._get_recent_model_performance(model_name)
                
                final_weight = (base_weight * 0.3 + 
                              uncertainty_factor * 0.3 + 
                              expertise_weight * 0.2 + 
                              recent_performance * 0.2)
                
                weights[model_name] = max(0.01, final_weight)  # Minimum weight
                total_weight += weights[model_name]
        
        # Normalize weights
        if total_weight > 0:
            weights = {k: v/total_weight for k, v in weights.items()}
        
        return weights
    
    def _bayesian_model_averaging(self, predictions: Dict, weights: Dict, 
                                 prior_geological_knowledge: Dict) -> Dict[str, float]:
        """Bayesian model averaging with geological priors"""
        rock_types = set()
        for pred_dict in predictions.values():
            if pred_dict is not None:
                if isinstance(pred_dict, dict):
                    rock_types.update(pred_dict.keys())
                elif hasattr(pred_dict, '__iter__'):
                    # Handle array predictions
                    standard_types = [
                        'volcanic_basaltic', 'volcanic_andesitic', 'volcanic_rhyolitic',
                        'sedimentary_sandstone', 'sedimentary_limestone', 'sedimentary_shale',
                        'metamorphic_gneiss', 'metamorphic_schist', 'igneous_granite',
                        'igneous_diorite', 'ultramafic'
                    ]
                    rock_types.update(standard_types[:len(pred_dict)])
        
        averaged_probabilities = {}
        
        for rock_type in rock_types:
            weighted_sum = 0.0
            total_weight = 0.0
            
            for model_name, prediction in predictions.items():
                if prediction is not None and model_name in weights:
                    weight = weights[model_name]
                    
                    if isinstance(prediction, dict):
                        prob = prediction.get(rock_type, 0.0)
                    elif hasattr(prediction, '__getitem__'):
                        # Handle array predictions
                        try:
                            type_index = list(rock_types).index(rock_type)
                            prob = prediction[type_index] if type_index < len(prediction) else 0.0
                        except (ValueError, IndexError):
                            prob = 0.0
                    else:
                        prob = 0.0
                    
                    weighted_sum += weight * prob
                    total_weight += weight
            
            if total_weight > 0:
                # Apply Bayesian update with geological priors
                prior_prob = prior_geological_knowledge.get(rock_type, 0.1)
                posterior_prob = (weighted_sum / total_weight + prior_prob) / 2.0
                averaged_probabilities[rock_type] = posterior_prob
            else:
                averaged_probabilities[rock_type] = prior_geological_knowledge.get(rock_type, 0.0)
        
        # Normalize probabilities
        total_prob = sum(averaged_probabilities.values())
        if total_prob > 0:
            averaged_probabilities = {k: v/total_prob for k, v in averaged_probabilities.items()}
        
        return averaged_probabilities
    
