    # ==================== DATABASE INTEGRATION METHODS ====================
    
    def query_plate_boundaries(self, latitude: float, longitude: float) -> Optional[Dict]:
        """Query plate boundary database with caching"""
        try:
            if not self.model_database:
                return None
            
            # Check cache first
            cache_key = f"plate_boundaries_{latitude:.4f}_{longitude:.4f}"
            
            # Try to get from model database
            cached_data = self._get_cached_plate_boundary_data(cache_key)
            if cached_data:
                return cached_data
            
            # If not in cache, perform analysis and store
            plate_data = self._perform_plate_boundary_analysis(latitude, longitude)
            if plate_data:
                self._cache_plate_boundary_data(cache_key, plate_data)
            
            return plate_data
            
        except Exception as e:
            self.logger.error(f"Plate boundary query failed: {e}")
            return None
    
    def cache_tectonic_analysis(self, latitude: float, longitude: float, results: Dict):
        """Cache tectonic analysis results in comprehensive database system"""
        try:
            # Initialize database connections if needed
            if not hasattr(self, 'model_database') or self.model_database is None:
                self._initialize_tectonic_database_connections()
            
            # Store in multiple database systems for redundancy and specialized access
            self._store_tectonic_model_database(latitude, longitude, results)
            self._store_tectonic_cache_database(latitude, longitude, results)
            self._store_tectonic_timeseries_database(latitude, longitude, results)
            
            # Update spatial indices for fast geographic queries
            self._update_tectonic_spatial_indices(latitude, longitude, results)
            
        except Exception as e:
            self.logger.error(f"Failed to cache tectonic analysis: {e}")
    
