    def _store_tectonic_model_database(self, latitude: float, longitude: float, results: Dict):
        """Store tectonic analysis in model database with full metadata"""
        if not self.model_database:
            return
        
        try:
            from datetime import datetime, timezone
            import json
            import uuid
            
            # Create comprehensive analysis metadata
            analysis_id = str(uuid.uuid4())
            metadata = {
                'analysis_id': analysis_id,
                'model_type': 'tectonic_analysis',
                'model_subtype': results.get('analysis_type', 'comprehensive'),
                'location': {
                    'latitude': latitude,
                    'longitude': longitude,
                    'region': self._determine_tectonic_region(latitude, longitude),
                    'tectonic_province': results.get('tectonic_province', 'unknown')
                },
                'timestamp': datetime.now(timezone.utc).isoformat(),
                'version': '2.0',
                'confidence_score': results.get('confidence', 0.0),
                'quality_metrics': {
                    'data_completeness': results.get('data_completeness', 0.0),
                    'spatial_resolution': results.get('spatial_resolution_km', 10.0),
                    'temporal_coverage': results.get('temporal_coverage_years', 0),
                    'validation_score': results.get('validation_score', 0.0)
                },
                'data_sources': results.get('data_sources', []),
                'processing_parameters': results.get('processing_parameters', {}),
                'tectonic_features': {
                    'fault_systems': results.get('fault_systems', []),
                    'stress_regime': results.get('stress_regime', 'unknown'),
                    'seismicity_rate': results.get('seismicity_rate', 0.0),
                    'crustal_structure': results.get('crustal_structure', {})
                },
                'geophysical_properties': {
                    'heat_flow': results.get('heat_flow_mw_m2', None),
                    'gravity_anomaly': results.get('gravity_anomaly_mgal', None),
                    'magnetic_anomaly': results.get('magnetic_anomaly_nt', None),
                    'crustal_thickness': results.get('crustal_thickness_km', None)
                },
                'analysis_results': results
            }
            
            # Register analysis model in database
            model_registration = {
                'model_id': analysis_id,
                'model_name': f'tectonic_analysis_{latitude:.4f}_{longitude:.4f}',
                'model_type': 'tectonic_analysis',
                'region': metadata['location']['region'],
                'status': 'active',
                'creation_date': datetime.now(timezone.utc),
                'metadata': json.dumps(metadata),
                'file_path': None,  # Stored directly in database
                'model_size_bytes': len(json.dumps(results)),
                'performance_metrics': json.dumps(metadata['quality_metrics'])
            }
            
            # Store using model database interface
            self.model_database.register_model(model_registration)
            
            # Store detailed analysis data
            self.model_database.store_analysis_data(analysis_id, {
                'raw_results': results,
                'processed_metadata': metadata,
                'spatial_bounds': self._calculate_analysis_bounds(latitude, longitude, results),
                'feature_vectors': self._extract_tectonic_features(results)
            })
            
        except Exception as e:
            self.logger.error(f"Failed to store in model database: {e}")
    
    def _store_tectonic_cache_database(self, latitude: float, longitude: float, results: Dict):
        """Store in fast-access cache database with spatial indexing"""
        if not self.geological_cache_db:
            return
        
        try:
            from datetime import datetime, timezone
            import json
            
            # Create cache record with spatial geometry
            cursor = self.geological_cache_db.cursor()
            
            # Insert or update cache record
            upsert_query = """
            INSERT INTO tectonic_analysis_cache (
                location_point,
                latitude,
                longitude,
                cache_key,
                analysis_type,
                confidence_score,
                tectonic_province,
                stress_regime,
                seismicity_rate,
                data_sources,
                results_json,
                created_at,
                updated_at,
                expiry_date
            ) VALUES (
                ST_Point(%s, %s),
                %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s
            )
            ON CONFLICT (cache_key) DO UPDATE SET
                confidence_score = EXCLUDED.confidence_score,
                tectonic_province = EXCLUDED.tectonic_province,
                stress_regime = EXCLUDED.stress_regime,
                seismicity_rate = EXCLUDED.seismicity_rate,
                data_sources = EXCLUDED.data_sources,
                results_json = EXCLUDED.results_json,
                updated_at = EXCLUDED.updated_at,
                expiry_date = EXCLUDED.expiry_date
            """
            
            cache_key = f"tectonic_{latitude:.4f}_{longitude:.4f}"
            now = datetime.now(timezone.utc)
            expiry = now + timedelta(days=30)  # Cache for 30 days
            
            cursor.execute(upsert_query, (
                longitude, latitude,  # PostGIS ST_Point(lon, lat)
                latitude, longitude,
                cache_key,
                results.get('analysis_type', 'comprehensive'),
                results.get('confidence', 0.0),
                results.get('tectonic_province', 'unknown'),
                results.get('stress_regime', 'unknown'),
                results.get('seismicity_rate', 0.0),
                json.dumps(results.get('data_sources', [])),
                json.dumps(results),
                now, now, expiry
            ))
            
            self.geological_cache_db.commit()
            
        except Exception as e:
            self.logger.error(f"Failed to store in cache database: {e}")
    
    def _store_tectonic_timeseries_database(self, latitude: float, longitude: float, results: Dict):
        """Store in TimescaleDB for temporal analysis and monitoring"""
        if not self.tectonic_timescale_db:
            return
        
        try:
            from datetime import datetime, timezone
            import json
            
            cursor = self.tectonic_timescale_db.cursor()
            
            # Insert time-series record for tectonic monitoring
            insert_query = """
            INSERT INTO tectonic_timeseries (
                timestamp,
                location_point,
                latitude,
                longitude,
                analysis_version,
                confidence_score,
                stress_regime_numeric,
                seismicity_rate,
                heat_flow,
                crustal_thickness,
                fault_density,
                tectonic_activity_index,
                data_quality_score,
                processing_time_ms,
                metadata_json
            ) VALUES (
                %s, ST_Point(%s, %s), %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s
            )
            """
            
            # Convert stress regime to numeric for time-series analysis
            stress_regime_map = {
                'extensional': 1, 'compressional': 2, 'strike_slip': 3,
                'transpressional': 4, 'transtensional': 5, 'unknown': 0
            }
            stress_numeric = stress_regime_map.get(results.get('stress_regime', 'unknown'), 0)
            
            # Calculate tectonic activity index
            activity_index = self._calculate_tectonic_activity_index(results)
            
            cursor.execute(insert_query, (
                datetime.now(timezone.utc),
                longitude, latitude,  # PostGIS ST_Point(lon, lat)
                latitude, longitude,
                '2.0',  # analysis version
                results.get('confidence', 0.0),
                stress_numeric,
                results.get('seismicity_rate', 0.0),
                results.get('heat_flow_mw_m2', None),
                results.get('crustal_thickness_km', None),
                results.get('fault_density_per_km2', 0.0),
                activity_index,
                results.get('data_quality_score', 0.0),
                results.get('processing_time_ms', 0),
                json.dumps({
                    'analysis_type': results.get('analysis_type', 'comprehensive'),
                    'data_sources': results.get('data_sources', []),
                    'processing_parameters': results.get('processing_parameters', {})
                })
            ))
            
            self.tectonic_timescale_db.commit()
            
        except Exception as e:
            self.logger.error(f"Failed to store in timeseries database: {e}")
    
    def _update_tectonic_spatial_indices(self, latitude: float, longitude: float, results: Dict):
        """Update spatial indices for efficient geographic queries"""
        try:
            if self.geological_cache_db:
                cursor = self.geological_cache_db.cursor()
                
                # Update spatial index statistics
                cursor.execute("ANALYZE tectonic_analysis_cache;")
                
                # Update region-based aggregations
                region = self._determine_tectonic_region(latitude, longitude)
                self._update_regional_tectonic_statistics(region, results)
                
        except Exception as e:
            self.logger.error(f"Failed to update spatial indices: {e}")
    
    def _determine_tectonic_region(self, latitude: float, longitude: float) -> str:
        """Advanced tectonic region determination using comprehensive database integration"""
        try:
            # Initialize tectonic database connections if needed
            if not hasattr(self, 'tectonic_region_db') or self.tectonic_region_db is None:
                self._initialize_tectonic_region_database()
            
            # Primary: Query global tectonic model databases
            region_data = self._query_global_tectonic_models(latitude, longitude)
            if region_data and region_data.get('confidence', 0) >= 0.8:
                return region_data['tectonic_region']
            
            # Secondary: Query plate boundary databases (PB2002, NUVEL)
            plate_data = self._query_plate_boundary_databases(latitude, longitude)
            if plate_data and plate_data.get('plate_name'):
                return self._standardize_plate_name(plate_data['plate_name'])
            
            # Tertiary: Query regional geological survey databases
            geological_data = self._query_regional_geological_databases(latitude, longitude)
            if geological_data and geological_data.get('tectonic_province'):
                return self._map_tectonic_province_to_region(geological_data['tectonic_province'])
            
            # Quaternary: Machine learning classification using cached models
            ml_region = self._classify_tectonic_region_ml(latitude, longitude)
            if ml_region and ml_region.get('confidence', 0) >= 0.7:
                return ml_region['region']
            
            # Fallback: Enhanced regional classification with uncertainty
            return self._enhanced_regional_classification(latitude, longitude)
            
        except Exception as e:
            self.logger.warning(f"Advanced tectonic region determination failed: {e}")
            return self._fallback_tectonic_region_classification(latitude, longitude)
    
    def _initialize_tectonic_region_database(self):
        """Initialize database connections for tectonic region analysis"""
        try:
            # Global tectonic model database
            tectonic_config = self.config.get('databases', {}).get('tectonic_models', {})
            if tectonic_config:
                self.tectonic_region_db = get_database_connection(tectonic_config)
            
            # Plate boundary database (PB2002/NUVEL)
            plate_boundary_config = self.config.get('databases', {}).get('plate_boundaries', {})
            if plate_boundary_config:
                self.plate_boundary_db = get_database_connection(plate_boundary_config)
            
            # Regional geological database
            geological_config = self.config.get('databases', {}).get('geological_data', {})
            if geological_config:
                self.regional_geological_db = get_database_connection(geological_config)
                
        except Exception as e:
            self.logger.error(f"Failed to initialize tectonic region databases: {e}")
            self.tectonic_region_db = None
            self.plate_boundary_db = None
            self.regional_geological_db = None
    
    def _query_global_tectonic_models(self, latitude: float, longitude: float) -> Optional[Dict]:
        """Query global tectonic model databases for authoritative region classification"""
        try:
            if not self.tectonic_region_db:
                return None
            
            # Query comprehensive global tectonic models
            query = """
                SELECT 
                    t.tectonic_region,
                    t.plate_name,
                    t.tectonic_domain,
                    t.confidence_score,
                    ST_Distance(t.boundary_geometry, ST_Point(%s, %s)) as distance_km,
                    t.data_source,
                    t.last_updated
                FROM global_tectonic_models t
                WHERE ST_DWithin(t.boundary_geometry, ST_Point(%s, %s), 0.5)
                ORDER BY t.confidence_score DESC, distance_km ASC
                LIMIT 5;
            """
            
            cursor = self.tectonic_region_db.cursor()
            cursor.execute(query, (longitude, latitude, longitude, latitude))
            results = cursor.fetchall()
            
            if results:
                best_result = results[0]
                return {
                    'tectonic_region': best_result[0],
                    'plate_name': best_result[1],
                    'tectonic_domain': best_result[2],
                    'confidence': best_result[3],
                    'distance_km': best_result[4],
                    'data_source': best_result[5],
                    'last_updated': best_result[6]
                }
            
            return None
            
        except Exception as e:
            self.logger.debug(f"Global tectonic model query failed: {e}")
            return None
    
    def _query_plate_boundary_databases(self, latitude: float, longitude: float) -> Optional[Dict]:
        """Query authoritative plate boundary databases (PB2002, NUVEL-1A)"""
        try:
            if not self.plate_boundary_db:
                return None
            
            # Query PB2002 and NUVEL plate boundary databases
            query = """
                SELECT 
                    pb.plate1_name,
                    pb.plate2_name,
                    pb.boundary_type,
                    pb.relative_motion_rate,
                    ST_Distance(pb.boundary_geometry, ST_Point(%s, %s)) as distance_km,
                    pb.data_source
                FROM plate_boundaries pb
                WHERE ST_DWithin(pb.boundary_geometry, ST_Point(%s, %s), 2.0)
                ORDER BY distance_km ASC
                LIMIT 3;
            """
            
            cursor = self.plate_boundary_db.cursor()
            cursor.execute(query, (longitude, latitude, longitude, latitude))
            results = cursor.fetchall()
            
            if results:
                closest_boundary = results[0]
                # Determine which plate the point is closest to
                primary_plate = closest_boundary[0] if closest_boundary[4] < 50 else closest_boundary[1]
                
                return {
                    'plate_name': primary_plate,
                    'boundary_type': closest_boundary[2],
                    'motion_rate': closest_boundary[3],
                    'distance_km': closest_boundary[4],
                    'data_source': closest_boundary[5],
                    'secondary_plate': closest_boundary[1]
                }
            
            return None
            
        except Exception as e:
            self.logger.debug(f"Plate boundary database query failed: {e}")
            return None
    
    def _query_regional_geological_databases(self, latitude: float, longitude: float) -> Optional[Dict]:
        """Query regional geological survey databases for tectonic province information"""
        try:
            if not self.regional_geological_db:
                return None
            
            # Query multiple regional geological databases
            queries = [
                # USGS geological provinces
                """
                SELECT 'USGS' as source, province_name, tectonic_setting, age_range
                FROM usgs_geological_provinces 
                WHERE ST_Contains(boundary_geometry, ST_Point(%s, %s))
                """,
                # Global geological provinces
                """
                SELECT 'Global' as source, province_name, tectonic_domain, formation_age
                FROM global_geological_provinces 
                WHERE ST_Contains(province_geometry, ST_Point(%s, %s))
                """,
                # Regional tectonic units
                """
                SELECT 'Regional' as source, unit_name, tectonic_context, structural_domain
                FROM regional_tectonic_units 
                WHERE ST_Contains(unit_geometry, ST_Point(%s, %s))
                """
            ]
            
            cursor = self.regional_geological_db.cursor()
            
            for query in queries:
                try:
                    cursor.execute(query, (longitude, latitude))
                    result = cursor.fetchone()
                    if result:
                        return {
                            'data_source': result[0],
                            'tectonic_province': result[1],
                            'tectonic_setting': result[2],
                            'additional_info': result[3]
                        }
                except Exception:
                    continue
            
            return None
            
        except Exception as e:
            self.logger.debug(f"Regional geological database query failed: {e}")
            return None
    
    def _classify_tectonic_region_ml(self, latitude: float, longitude: float) -> Optional[Dict]:
        """Machine learning-based tectonic region classification using trained models"""
        try:
            # Check if ML models are available in model database
            if not hasattr(self, 'model_database') or not self.model_database:
                return None
            
            # Search for tectonic region classification models
            ml_models = self.model_database.search_models({
                'model_type': 'tectonic_region_classifier',
                'status': 'active'
            })
            
            if not ml_models:
                return None
            
            # Use the most recent/highest confidence model
            best_model = max(ml_models, key=lambda m: m.get('accuracy', 0))
            
            # Prepare feature vector
            features = self._extract_tectonic_region_features(latitude, longitude)
            if not features:
                return None
            
            # Perform prediction
            prediction = self.model_database.predict(best_model['model_id'], features)
            
            if prediction and prediction.get('confidence', 0) >= 0.7:
                return {
                    'region': prediction['predicted_class'],
                    'confidence': prediction['confidence'],
                    'model_id': best_model['model_id'],
                    'model_accuracy': best_model.get('accuracy', 0),
                    'feature_importance': prediction.get('feature_importance', {})
                }
            
            return None
            
        except Exception as e:
            self.logger.debug(f"ML tectonic region classification failed: {e}")
            return None
    
    def _extract_tectonic_region_features(self, latitude: float, longitude: float) -> Optional[List[float]]:
        """Extract feature vector for ML-based tectonic region classification"""
        try:
            features = []
            
            # Geographic coordinates (normalized)
            features.extend([latitude / 90.0, longitude / 180.0])
            
            # Distance to plate boundaries
            plate_boundary_distance = self._calculate_plate_boundary_distance(latitude, longitude)
            features.append(min(plate_boundary_distance.get('distance_km', 1000) / 1000.0, 1.0))
            
            # Seismicity characteristics
            seismic_data = self._get_local_seismicity_summary(latitude, longitude)
            features.extend([
                seismic_data.get('earthquake_density', 0) / 10.0,
                seismic_data.get('average_magnitude', 0) / 9.0,
                seismic_data.get('depth_variability', 0) / 700.0
            ])
            
            # Topographic/bathymetric features
            topo_data = self._get_topographic_summary(latitude, longitude)
            features.extend([
                max(min(topo_data.get('elevation', 0) / 8000.0, 1.0), -1.0),  # Normalized elevation
                topo_data.get('slope', 0) / 45.0,  # Normalized slope
                topo_data.get('roughness', 0)  # Already normalized
            ])
            
            return features if len(features) >= 8 else None
            
        except Exception as e:
            self.logger.debug(f"Feature extraction for tectonic region failed: {e}")
            return None
    
    def _standardize_plate_name(self, plate_name: str) -> str:
        """Standardize plate names to consistent regional identifiers"""
        plate_mapping = {
            'Pacific': 'pacific_plate',
            'North American': 'north_american_plate', 
            'Eurasian': 'eurasian_plate',
            'African': 'african_plate',
            'Antarctic': 'antarctic_plate',
            'South American': 'south_american_plate',
            'Australian': 'indo_australian_plate',
            'Indian': 'indo_australian_plate',
            'Nazca': 'nazca_plate',
            'Cocos': 'cocos_plate',
            'Caribbean': 'caribbean_plate',
            'Philippine Sea': 'philippine_sea_plate',
            'Scotia': 'scotia_plate',
            'Juan de Fuca': 'juan_de_fuca_plate'
        }
        
        # Fuzzy matching for plate names
        plate_name_clean = plate_name.strip().title()
        for standard_name, region_code in plate_mapping.items():
            if standard_name.lower() in plate_name.lower():
                return region_code
        
        # Default regional classification
        return self._map_coordinates_to_region(0, 0, plate_name)
    
    def _map_tectonic_province_to_region(self, tectonic_province: str) -> str:
        """Map tectonic province names to standardized regional identifiers"""
        province_mapping = {
            'Pacific Basin': 'pacific_plate',
            'Cordilleran': 'north_american_plate',
            'Appalachian': 'north_american_plate',
            'Canadian Shield': 'north_american_plate',
            'Andean': 'south_american_plate',
            'Brazilian Shield': 'south_american_plate',
            'Alpine': 'eurasian_plate',
            'Variscan': 'eurasian_plate',
            'Caledonian': 'eurasian_plate',
            'Ural': 'eurasian_plate',
            'Himalayan': 'eurasian_plate',
            'East African Rift': 'african_plate',
            'West African Craton': 'african_plate',
            'Australian Craton': 'indo_australian_plate',
            'Tasman': 'indo_australian_plate'
        }
        
        province_clean = tectonic_province.strip().title()
        for province_name, region_code in province_mapping.items():
            if province_name.lower() in province_clean.lower():
                return region_code
        
        return 'other_tectonic_province'
    
    def _enhanced_regional_classification(self, latitude: float, longitude: float) -> str:
        """Enhanced regional classification with geological and geophysical context"""
        try:
            # Multi-criteria regional analysis
            criteria_scores = {}
            
            # Geographic proximity to major plate centers
            plate_proximities = self._calculate_major_plate_proximities(latitude, longitude)
            
            # Seismicity patterns
            seismic_signature = self._analyze_regional_seismic_signature(latitude, longitude)
            
            # Topographic/bathymetric characteristics
            topographic_signature = self._analyze_regional_topographic_signature(latitude, longitude)
            
            # Combine criteria with weights
            for plate_name, proximity in plate_proximities.items():
                score = proximity * 0.4  # Base geographic score
                
                # Add seismic signature bonus
                if seismic_signature.get('dominant_pattern') == plate_name:
                    score += seismic_signature.get('confidence', 0) * 0.3
                
                # Add topographic signature bonus  
                if topographic_signature.get('characteristic_terrain') == plate_name:
                    score += topographic_signature.get('confidence', 0) * 0.3
                
                criteria_scores[plate_name] = score
            
            # Return highest scoring region
            if criteria_scores:
                best_region = max(criteria_scores.items(), key=lambda x: x[1])
                return best_region[0] if best_region[1] > 0.5 else 'transitional_zone'
            
            return self._fallback_tectonic_region_classification(latitude, longitude)
            
        except Exception as e:
            self.logger.debug(f"Enhanced regional classification failed: {e}")
            return self._fallback_tectonic_region_classification(latitude, longitude)
    
    def _calculate_major_plate_proximities(self, latitude: float, longitude: float) -> Dict[str, float]:
        """Calculate proximity scores to major tectonic plate centers"""
        plate_centers = {
            'pacific_plate': [(-150, 0), (150, -30)],  # Pacific has two main centers
            'north_american_plate': [(-100, 45)],
            'eurasian_plate': [(30, 50), (90, 30)],  # European and Asian centers
            'south_american_plate': [(-60, -15)],
            'african_plate': [(20, 0)],
            'antarctic_plate': [(0, -80)],
            'indo_australian_plate': [(130, -25)]
        }
        
        proximities = {}
        for plate_name, centers in plate_centers.items():
            max_proximity = 0
            for center_lon, center_lat in centers:
                # Calculate great circle distance approximation
                distance = ((latitude - center_lat)**2 + (longitude - center_lon)**2)**0.5
                proximity = max(0, 1 - distance / 90)  # Normalize by quarter-globe
                max_proximity = max(max_proximity, proximity)
            
            proximities[plate_name] = max_proximity
        
        return proximities
    
    def _analyze_regional_seismic_signature(self, latitude: float, longitude: float) -> Dict:
        """Analyze regional seismic signature for tectonic identification"""
        try:
            # Get local seismicity characteristics
            seismic_data = self._get_local_seismicity_summary(latitude, longitude)
            
            # Characteristic seismic signatures by region
            signatures = {
                'pacific_plate': {'high_activity': True, 'deep_events': True, 'subduction': True},
                'north_american_plate': {'moderate_activity': True, 'shallow_focus': True},
                'eurasian_plate': {'variable_activity': True, 'collision_zone': True},
                'south_american_plate': {'high_activity': True, 'subduction': True},
                'african_plate': {'rift_activity': True, 'moderate_activity': True}
            }
            
            # Match observed signature to regional patterns
            best_match = 'other_plate'
            best_confidence = 0
            
            earthquake_density = seismic_data.get('earthquake_density', 0)
            average_depth = seismic_data.get('average_depth', 0)
            
            for region, signature in signatures.items():
                confidence = 0
                
                if signature.get('high_activity') and earthquake_density > 5:
                    confidence += 0.3
                elif signature.get('moderate_activity') and 1 <= earthquake_density <= 5:
                    confidence += 0.3
                
                if signature.get('deep_events') and average_depth > 100:
                    confidence += 0.2
                elif signature.get('shallow_focus') and average_depth < 50:
                    confidence += 0.2
                
                if confidence > best_confidence:
                    best_match = region
                    best_confidence = confidence
            
            return {
                'dominant_pattern': best_match,
                'confidence': best_confidence,
                'seismic_characteristics': seismic_data
            }
            
        except Exception as e:
            self.logger.debug(f"Regional seismic signature analysis failed: {e}")
            return {'dominant_pattern': 'other_plate', 'confidence': 0}
    
    def _analyze_regional_topographic_signature(self, latitude: float, longitude: float) -> Dict:
        """Analyze regional topographic signature for tectonic identification"""
        try:
            topo_data = self._get_topographic_summary(latitude, longitude)
            
            elevation = topo_data.get('elevation', 0)
            slope = topo_data.get('slope', 0)
            roughness = topo_data.get('roughness', 0)
            
            # Characteristic topographic signatures
            if elevation < -2000:  # Deep ocean
                if roughness > 0.3:
                    return {'characteristic_terrain': 'pacific_plate', 'confidence': 0.7}
                else:
                    return {'characteristic_terrain': 'abyssal_plain', 'confidence': 0.5}
            elif elevation > 3000:  # High mountains  
                if latitude > 30:
                    return {'characteristic_terrain': 'eurasian_plate', 'confidence': 0.6}
                else:
                    return {'characteristic_terrain': 'south_american_plate', 'confidence': 0.6}
            elif 0 <= elevation < 1000 and slope < 5:  # Continental platforms
                if -60 <= longitude <= 60:
                    return {'characteristic_terrain': 'african_plate', 'confidence': 0.5}
                else:
                    return {'characteristic_terrain': 'north_american_plate', 'confidence': 0.5}
            
            return {'characteristic_terrain': 'transitional', 'confidence': 0.3}
            
        except Exception as e:
            self.logger.debug(f"Regional topographic signature analysis failed: {e}")
            return {'characteristic_terrain': 'other_plate', 'confidence': 0}
    
    def _fallback_tectonic_region_classification(self, latitude: float, longitude: float) -> str:
        """Fallback tectonic region classification using enhanced coordinate-based logic"""
        # Enhanced coordinate-based classification with overlap zones
        if -180 <= longitude <= -60:
            if latitude >= 15:
                return 'north_american_plate'
            elif -30 <= latitude < 15:
                return 'south_american_plate' if -90 <= longitude <= -30 else 'pacific_plate_eastern'
            else:
                return 'antarctic_plate' if latitude < -60 else 'pacific_plate_eastern'
        
        elif -60 < longitude <= 60:
            if latitude >= 30:
                return 'eurasian_plate'
            elif -30 <= latitude < 30:
                return 'african_plate'
            else:
                return 'antarctic_plate'
        
        else:  # 60 < longitude <= 180
            if latitude >= 30:
                return 'eurasian_plate'  
            elif -30 <= latitude < 30:
                return 'indo_australian_plate' if longitude <= 120 else 'pacific_plate_western'
            else:
                return 'antarctic_plate' if latitude < -60 else 'indo_australian_plate'
    
    def _calculate_analysis_bounds(self, latitude: float, longitude: float, results: Dict) -> Dict:
        """Calculate spatial bounds of analysis for indexing"""
        radius_km = results.get('analysis_radius_km', 100.0)
        lat_offset = radius_km / 111.0  # rough km to degrees
        lon_offset = radius_km / (111.0 * abs(math.cos(math.radians(latitude))))
        
        return {
            'min_latitude': latitude - lat_offset,
            'max_latitude': latitude + lat_offset,
            'min_longitude': longitude - lon_offset,
            'max_longitude': longitude + lon_offset
        }
    
    def _extract_tectonic_features(self, results: Dict) -> Dict:
        """Extract feature vectors for machine learning applications"""
        features = {
            'seismicity_rate': results.get('seismicity_rate', 0.0),
            'heat_flow': results.get('heat_flow_mw_m2', 0.0),
            'crustal_thickness': results.get('crustal_thickness_km', 35.0),
            'fault_density': results.get('fault_density_per_km2', 0.0),
            'stress_magnitude': results.get('stress_magnitude_mpa', 0.0),
            'gravity_anomaly': results.get('gravity_anomaly_mgal', 0.0),
            'magnetic_anomaly': results.get('magnetic_anomaly_nt', 0.0)
        }
        
        # Normalize features for ML applications
        normalized_features = {}
        for key, value in features.items():
            if isinstance(value, (int, float)):
                normalized_features[f'{key}_normalized'] = self._normalize_feature(key, value)
        
        return {**features, **normalized_features}
    
    def _normalize_feature(self, feature_name: str, value: float) -> float:
        """Normalize feature values for ML applications"""
        normalization_ranges = {
            'seismicity_rate': (0.0, 10.0),
            'heat_flow': (0.0, 200.0),
            'crustal_thickness': (5.0, 80.0),
            'fault_density': (0.0, 5.0),
            'stress_magnitude': (0.0, 1000.0),
            'gravity_anomaly': (-500.0, 500.0),
            'magnetic_anomaly': (-1000.0, 1000.0)
        }
        
        if feature_name in normalization_ranges:
            min_val, max_val = normalization_ranges[feature_name]
            return max(0.0, min(1.0, (value - min_val) / (max_val - min_val)))
        
        return value
    
    def _calculate_tectonic_activity_index(self, results: Dict) -> float:
        """Calculate composite tectonic activity index"""
        # Weighted combination of tectonic indicators
        weights = {
            'seismicity_rate': 0.3,
            'heat_flow': 0.2,
            'fault_density': 0.2,
            'stress_magnitude': 0.15,
            'crustal_deformation': 0.15
        }
        
        activity_score = 0.0
        for indicator, weight in weights.items():
            value = results.get(indicator.replace('_', '_'), 0.0)
            if indicator == 'seismicity_rate':
                normalized = min(1.0, value / 5.0)  # Normalize to 0-1
            elif indicator == 'heat_flow':
                normalized = min(1.0, results.get('heat_flow_mw_m2', 0.0) / 100.0)
            elif indicator == 'fault_density':
                normalized = min(1.0, results.get('fault_density_per_km2', 0.0) / 2.0)
            elif indicator == 'stress_magnitude':
                normalized = min(1.0, results.get('stress_magnitude_mpa', 0.0) / 500.0)
            elif indicator == 'crustal_deformation':
                normalized = min(1.0, results.get('deformation_rate_mm_yr', 0.0) / 10.0)
            else:
                normalized = 0.0
            
            activity_score += weight * normalized
        
        return round(activity_score, 4)
    
    def _update_regional_tectonic_statistics(self, region: str, results: Dict):
        """Update regional aggregated tectonic statistics"""
        try:
            if not self.geological_cache_db:
                return
            
            cursor = self.geological_cache_db.cursor()
            
            # Update or insert regional statistics
            upsert_query = """
            INSERT INTO regional_tectonic_stats (
                tectonic_region,
                analysis_count,
                avg_seismicity_rate,
                avg_heat_flow,
                avg_crustal_thickness,
                avg_activity_index,
                last_updated
            ) VALUES (%s, 1, %s, %s, %s, %s, %s)
            ON CONFLICT (tectonic_region) DO UPDATE SET
                analysis_count = regional_tectonic_stats.analysis_count + 1,
                avg_seismicity_rate = (regional_tectonic_stats.avg_seismicity_rate * regional_tectonic_stats.analysis_count + %s) / (regional_tectonic_stats.analysis_count + 1),
                avg_heat_flow = (regional_tectonic_stats.avg_heat_flow * regional_tectonic_stats.analysis_count + %s) / (regional_tectonic_stats.analysis_count + 1),
                avg_crustal_thickness = (regional_tectonic_stats.avg_crustal_thickness * regional_tectonic_stats.analysis_count + %s) / (regional_tectonic_stats.analysis_count + 1),
                avg_activity_index = (regional_tectonic_stats.avg_activity_index * regional_tectonic_stats.analysis_count + %s) / (regional_tectonic_stats.analysis_count + 1),
                last_updated = %s
            """
            
            seismicity_rate = results.get('seismicity_rate', 0.0)
            heat_flow = results.get('heat_flow_mw_m2', 0.0)
            crustal_thickness = results.get('crustal_thickness_km', 35.0)
            activity_index = self._calculate_tectonic_activity_index(results)
            now = datetime.now(timezone.utc)
            
            cursor.execute(upsert_query, (
                region, seismicity_rate, heat_flow, crustal_thickness, activity_index, now,
                seismicity_rate, heat_flow, crustal_thickness, activity_index, now
            ))
            
            self.geological_cache_db.commit()
            
        except Exception as e:
            self.logger.error(f"Failed to update regional statistics: {e}")
    
    def cache_crustal_analysis(self, latitude: float, longitude: float, results: Dict):
        """Cache crustal analysis results in model database"""
        try:
            if not self.model_database:
                return
            
            # Create metadata for crustal analysis
            from datetime import datetime, timezone
            metadata = {
                'type': 'crustal_analysis',
                'location': {'latitude': latitude, 'longitude': longitude},
                'timestamp': datetime.now(timezone.utc).isoformat(),
                'version': '1.0',
                'confidence': results.get('confidence', 0.0),
                'data_sources': results.get('data_sources', []),
                'results': results
            }
            
            # Store in database
            cache_key = f"crustal_{latitude:.4f}_{longitude:.4f}"
            self._store_analysis_result(cache_key, metadata)
            
        except Exception as e:
            self.logger.error(f"Failed to cache crustal analysis: {e}")
    
