    async def _predict_slowness_ml_enhanced(self, data_tensor: torch.Tensor, geometry_tensor: torch.Tensor, 
                                          batch_metadata: List) -> Dict:
        """ML-enhanced slowness prediction using model manager integration"""
        try:
            if hasattr(self, 'model_manager_slowness') and self.model_manager_slowness:
                # Prepare features for ML slowness prediction
                slowness_features = await self._prepare_slowness_prediction_features(
                    data_tensor, geometry_tensor, batch_metadata
                )
                
                # Multi-model ensemble slowness prediction
                ensemble_predictions = await self.model_manager_slowness.predict_slowness_ensemble(
                    slowness_features,
                    geometry=geometry_tensor.cpu().numpy(),
                    metadata=batch_metadata
                )
                
                if ensemble_predictions:
                    # Convert predictions to torch tensors
                    ml_slowness_vectors = torch.tensor(
                        ensemble_predictions['slowness_vectors'], 
                        dtype=torch.float32
                    )
                    
                    return {
                        'slowness_vectors': ml_slowness_vectors,
                        'confidence': ensemble_predictions.get('confidence', 0.7),
                        'model_uncertainty': ensemble_predictions.get('uncertainty', 0.1),
                        'method': 'ml_ensemble',
                        'feature_importance': ensemble_predictions.get('feature_importance', {})
                    }
            
            # Fallback to basic ML approach
            return await self._basic_ml_slowness_prediction(data_tensor, geometry_tensor)
            
        except Exception as e:
            logging.error(f"ML slowness prediction failed: {e}")
            return await self._fallback_ml_slowness_prediction(data_tensor, geometry_tensor)
    
