    def _calculate_metamorphic_grade_uncertainty(self, ml_grade: float, traditional_grade: float, 
                                               numerical_grade: float, petrology_data: Dict) -> float:
        """Calculate uncertainty in metamorphic grade estimation"""
        predictions = [ml_grade, traditional_grade, numerical_grade/10]
        prediction_variance = np.var(predictions) if len(predictions) > 1 else 0.3
        data_quality = len(petrology_data) / 5  # More data = better quality
        return max(0.1, min(prediction_variance + (1 - data_quality), 0.5))
    
    def _calculate_metamorphic_weights(self, petrology_data: Dict, thermal_models: Dict) -> Dict[str, float]:
        """Calculate ensemble weights for metamorphic grade prediction"""
        ml_weight = 0.6 if thermal_models else 0.2
        data_weight = len(petrology_data) / 10
        
        weights = {
            'ml': ml_weight,
            'traditional': 0.3,
            'numerical': 0.1 + data_weight
        }
        
        # Normalize weights
        total = sum(weights.values())
        return {k: v/total for k, v in weights.items()}

