    def _calculate_precursor_strength_enhanced_fallback(self, features: Dict) -> float:
        """Enhanced fallback precursor strength calculation with database context"""
        try:
            # Enhanced multi-parameter analysis
            seismic_features = features.get('seismic_features', {})
            deformation_features = features.get('deformation_features', {})
            gas_features = features.get('gas_features', {})
            thermal_features = features.get('thermal_features', {})
            
            # Advanced seismic strength with frequency analysis
            seismic_strength = min(1.0, (
                seismic_features.get('event_rate', 0) / 100.0 +
                seismic_features.get('magnitude_avg', 0) / 5.0 +
                seismic_features.get('energy_release', 0) / 1e12
            ) / 3.0)
            
            # Enhanced deformation strength with multi-component analysis
            deformation_strength = min(1.0, (
                abs(deformation_features.get('vertical_velocity_mm_year', 0)) / 50.0 +
                abs(deformation_features.get('radial_velocity_mm_year', 0)) / 30.0 +
                deformation_features.get('strain_rate', 0) / 1e-6
            ) / 3.0)
            
            # Advanced gas strength with composition ratios
            gas_strength = min(1.0, (
                gas_features.get('so2_flux_tons_day', 0) / 1000.0 +
                gas_features.get('co2_so2_ratio', 0) / 10.0 +
                gas_features.get('temperature_c', 0) / 500.0
            ) / 3.0)
            
            # Enhanced thermal strength with spatial analysis
            thermal_strength = min(1.0, (
                thermal_features.get('temperature_anomaly_k', 0) / 10.0 +
                thermal_features.get('thermal_area_km2', 0) / 5.0 +
                thermal_features.get('heat_flux_w_m2', 0) / 100.0
            ) / 3.0)
            
            # Weighted combination based on data quality
            weights = {
                'seismic': 0.3,
                'deformation': 0.3, 
                'gas': 0.2,
                'thermal': 0.2
            }
            
            total_strength = (
                seismic_strength * weights['seismic'] +
                deformation_strength * weights['deformation'] +
                gas_strength * weights['gas'] +
                thermal_strength * weights['thermal']
            )
            
            return float(total_strength)
            
        except Exception as e:
            self.logger.error(f"Error in enhanced fallback precursor calculation: {e}")
            return 0.5
    
    def _calculate_pattern_likelihood_enhanced_fallback(self, features: Dict, pattern) -> float:
        """Enhanced fallback pattern likelihood calculation with multi-dimensional analysis"""
        try:
            # Enhanced multi-dimensional pattern comparison
            precursor_strength = self._calculate_precursor_strength(features)
            pattern_strength = getattr(pattern, 'precursor_strength', 0.5)
            
            # Multi-parameter similarity analysis
            seismic_similarity = self._calculate_seismic_similarity(features, pattern)
            deformation_similarity = self._calculate_deformation_similarity(features, pattern)
            gas_similarity = self._calculate_gas_similarity(features, pattern) 
            thermal_similarity = self._calculate_thermal_similarity(features, pattern)
            temporal_similarity = self._calculate_temporal_similarity(features, pattern)
            
            # Weighted similarity scores
            similarity_weights = {
                'strength': 0.2,
                'seismic': 0.25,
                'deformation': 0.25,
                'gas': 0.15,
                'thermal': 0.1,
                'temporal': 0.05
            }
            
            # Gaussian likelihood with multiple parameters
            strength_diff = abs(precursor_strength - pattern_strength)
            strength_likelihood = np.exp(-strength_diff**2 / (2 * 0.15**2))
            
            # Combined likelihood using all similarity measures
            total_likelihood = (
                strength_likelihood * similarity_weights['strength'] +
                seismic_similarity * similarity_weights['seismic'] +
                deformation_similarity * similarity_weights['deformation'] +
                gas_similarity * similarity_weights['gas'] +
                thermal_similarity * similarity_weights['thermal'] +
                temporal_similarity * similarity_weights['temporal']
            )
            
            return float(np.clip(total_likelihood, 0.0, 1.0))
            
        except Exception as e:
            self.logger.error(f"Error in enhanced pattern likelihood fallback: {e}")
            return 0.1
    
    def _calculate_seismic_similarity(self, features: Dict, pattern) -> float:
        """Calculate seismic pattern similarity"""
        try:
            current_seismic = features.get('seismic_features', {})
            pattern_seismic = getattr(pattern, 'seismic_characteristics', {})
            
            event_rate_sim = 1.0 - abs(
                current_seismic.get('event_rate', 0) - pattern_seismic.get('event_rate', 0)
            ) / max(100.0, max(current_seismic.get('event_rate', 0), pattern_seismic.get('event_rate', 0)))
            
            magnitude_sim = 1.0 - abs(
                current_seismic.get('magnitude_avg', 0) - pattern_seismic.get('magnitude_avg', 0)
            ) / 8.0  # Max magnitude scale
            
            return (event_rate_sim + magnitude_sim) / 2.0
            
        except Exception:
            return 0.5
    
    def _calculate_deformation_similarity(self, features: Dict, pattern) -> float:
        """Calculate deformation pattern similarity"""
        try:
            current_def = features.get('deformation_features', {})
            pattern_def = getattr(pattern, 'deformation_characteristics', {})
            
            vertical_sim = 1.0 - abs(
                current_def.get('vertical_velocity_mm_year', 0) - 
                pattern_def.get('vertical_velocity_mm_year', 0)
            ) / 200.0  # Max expected velocity
            
            radial_sim = 1.0 - abs(
                current_def.get('radial_velocity_mm_year', 0) - 
                pattern_def.get('radial_velocity_mm_year', 0)
            ) / 100.0
            
            return (vertical_sim + radial_sim) / 2.0
            
        except Exception:
            return 0.5
    
    def _calculate_gas_similarity(self, features: Dict, pattern) -> float:
        """Calculate gas emission pattern similarity"""
        try:
            current_gas = features.get('gas_features', {})
            pattern_gas = getattr(pattern, 'gas_characteristics', {})
            
            so2_sim = 1.0 - abs(
                current_gas.get('so2_flux_tons_day', 0) - pattern_gas.get('so2_flux_tons_day', 0)
            ) / 2000.0  # Max expected flux
            
            ratio_sim = 1.0 - abs(
                current_gas.get('co2_so2_ratio', 0) - pattern_gas.get('co2_so2_ratio', 0)
            ) / 20.0  # Max expected ratio
            
            return (so2_sim + ratio_sim) / 2.0
            
        except Exception:
            return 0.5
    
    def _calculate_thermal_similarity(self, features: Dict, pattern) -> float:
        """Calculate thermal pattern similarity"""
        try:
            current_thermal = features.get('thermal_features', {})
            pattern_thermal = getattr(pattern, 'thermal_characteristics', {})
            
            temp_sim = 1.0 - abs(
                current_thermal.get('temperature_anomaly_k', 0) - 
                pattern_thermal.get('temperature_anomaly_k', 0)
            ) / 50.0  # Max expected anomaly
            
            area_sim = 1.0 - abs(
                current_thermal.get('thermal_area_km2', 0) - 
                pattern_thermal.get('thermal_area_km2', 0)
            ) / 20.0  # Max expected area
            
            return (temp_sim + area_sim) / 2.0
            
        except Exception:
            return 0.5
    
    def _calculate_temporal_similarity(self, features: Dict, pattern) -> float:
        """Calculate temporal pattern similarity"""
        try:
            current_temporal = features.get('temporal_context', {})
            pattern_temporal = getattr(pattern, 'temporal_characteristics', {})
            
            duration_sim = 1.0 - abs(
                current_temporal.get('precursor_duration_days', 0) - 
                pattern_temporal.get('precursor_duration_days', 0)
            ) / 1000.0  # Max expected duration
            
            return duration_sim
            
        except Exception:
            return 0.5
    
    def _calculate_pressure_buildup_enhanced_fallback(self, uplift_rate: float, depth: float, volume: float) -> float:
        """Enhanced physics-based pressure buildup calculation with database constraints"""
        try:
            # Enhanced Mogi model with variable parameters
            depth_m = depth * 1000  # Convert km to m
            
            # Database-informed crustal properties
            crustal_properties = self._get_crustal_properties_from_database(depth)
            shear_modulus = crustal_properties.get('shear_modulus', 30e9)  # Pa
            poisson_ratio = crustal_properties.get('poisson_ratio', 0.25)
            bulk_modulus = crustal_properties.get('bulk_modulus', 50e9)  # Pa
            
            # Convert uplift rate from mm/year to m/s
            uplift_rate_ms = (uplift_rate / 1000.0) / (365.25 * 24 * 3600)
            
            # Enhanced pressure calculation with multiple models
            # Primary: Mogi point source model
            mogi_pressure_rate = (3 * uplift_rate_ms * shear_modulus * depth_m**2) / (volume * (1 - poisson_ratio))
            
            # Secondary: Finite source correction
            source_radius = (3 * volume / (4 * np.pi))**(1/3)
            finite_correction = 1 + (source_radius / depth_m)**2 / 3
            finite_pressure_rate = mogi_pressure_rate * finite_correction
            
            # Tertiary: Viscoelastic correction for time-dependent behavior
            viscoelastic_correction = self._calculate_viscoelastic_correction(depth, uplift_rate)
            viscoelastic_pressure_rate = finite_pressure_rate * viscoelastic_correction
            
            return viscoelastic_pressure_rate
            
        except Exception as e:
            self.logger.error(f"Error in enhanced pressure buildup fallback: {e}")
            return 0.0
    
    def _assess_physics_data_quality(self, features: Dict) -> float:
        """Assess quality of physical data for physics-based modeling"""
        try:
            quality_factors = []
            
            # Deformation data quality
            deformation = features.get('deformation_features', {})
            if 'vertical_velocity_mm_year' in deformation and 'velocity_uncertainty' in deformation:
                velocity = deformation['vertical_velocity_mm_year']
                uncertainty = deformation.get('velocity_uncertainty', velocity * 0.5)
                if velocity > 0:
                    quality_factors.append(min(1.0, velocity / max(0.1, uncertainty)))
            
            # Seismic data quality
            seismic = features.get('seismic_features', {})
            if 'event_rate' in seismic:
                quality_factors.append(min(1.0, seismic['event_rate'] / 10.0))  # Normalize by 10 events/day
            
            # Gas data quality
            gas = features.get('gas_features', {})
            if 'so2_flux_tons_day' in gas:
                quality_factors.append(min(1.0, gas['so2_flux_tons_day'] / 100.0))  # Normalize by 100 tons/day
            
            return np.mean(quality_factors) if quality_factors else 0.3
            
        except Exception:
            return 0.3  # Default moderate quality
    
    def _fallback_eruption_prediction(self, features: Dict) -> Dict:
        """Fallback eruption prediction when advanced methods fail"""
        try:
            # Simple heuristic based on available features
            feature_array = features.get('feature_array', np.array([]))
            
            if len(feature_array) == 0:
                probability = 0.1  # Very low default
                confidence = 0.3
            else:
                # Simple scoring based on feature magnitudes
                normalized_features = feature_array / (np.max(np.abs(feature_array)) + 1e-6)
                activity_score = np.mean(np.abs(normalized_features))
                
                # Convert activity score to probability (0-1 range)
                probability = min(0.95, max(0.05, activity_score))
                confidence = 0.4  # Low confidence for fallback method
            
            alert_level = self._determine_volcanic_alert_level(probability, confidence)
            
            return {
                'success': True,
                'eruption_probability': probability,
                'confidence': confidence,
                'alert_level': alert_level,
                'time_to_eruption_days': None,
                'method': 'fallback_heuristic',
                'warning': 'Using simplified fallback method due to advanced method failures',
                'timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Fallback prediction failed: {e}")
            return {
                'success': False,
                'error': str(e),
                'eruption_probability': 0.1,
                'confidence': 0.2,
                'alert_level': 'MINIMAL',
                'method': 'emergency_fallback'
            }


